/* 全库分片 10/43，共 1000 首（chinese-gushiwen / chinese-poetry）*/
window.QUAN_KU_PART_9 = [
  {"t":"酬裴员外以诗代书","p":"","d":"唐代","a":"高适","c":["少时方浩荡，遇物犹尘埃。脱略身外事，交游天下才。", "单车入燕赵，独立心悠哉。宁知戎马间，忽展平生怀。", "且欣清论高，岂顾夕阳颓。题诗碣石馆，纵酒燕王台。", "北望沙漠垂，漫天雪皑皑。临边无策略，览古空裴回。", "乐毅吾所怜，拔齐翻见猜。荆卿吾所悲，适秦不复回。", "然诺多死地，公忠成祸胎。与君从此辞，每恐流年催。", "如何俱老大，始复忘形骸。兄弟真二陆，声名连八裴。", "乙未将星变，贼臣候天灾。胡骑犯龙山，乘舆经马嵬。", "千官无倚著，万姓徒悲哀。诛吕鬼神动，安刘天地开。", "奔波走风尘，倏忽值云雷。拥旄出淮甸，入幕征楚材。", "誓当剪鲸鲵，永以竭驽骀。小人胡不仁，谗我成死灰。", "赖得日月明，照耀无不该。留司洛阳宫，詹府唯蒿莱。", "是时扫氛祲，尚未歼渠魁。背河列长围，师老将亦乖。", "归军剧风火，散卒争椎埋。一夕瀍洛空，生灵悲曝腮。", "衣冠投草莽，予欲驰江淮。登顿宛叶下，栖遑襄邓隈。", "城池何萧条，邑屋更崩摧。纵横荆棘丛，但见瓦砾堆。", "行人无血色，战骨多青苔。遂除彭门守，因得朝玉阶。", "激昂仰鹓鹭，献替欣盐梅。驱传及远蕃，忧思郁难排。", "罢人纷争讼，赋税如山崖。所思在畿甸，曾是鲁宓侪。", "自从拜郎官，列宿焕天街。那能访遐僻，还复寄琼瑰。", "金玉本高价，埙篪终易谐。朗咏临清秋，凉风下庭槐。", "何意寇盗间，独称名义偕。辛酸陈侯诔，叹息季鹰杯。", "白日屡分手，青春不再来。卧看中散论，愁忆太常斋。", "酬赠徒为尔，长歌还自咍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汎昆明池至近华浦大观楼","p":"","d":"清代","a":"郑珍","c":["云南正月半，杨柳青满湖。浮舟出郡郭，逌然如画图。", "汪汪千顷波，晴沙畅平铺。和风弄舞燕，微澜漾浮凫。", "赤脚两桨女，妙称樗散徒。踏舷唱小梅，浩气淩八区。", "沐氏旧西园，宛在似篷壶。早树发初绿，粉墙明精庐。", "诸渔集门曲，幽清无鸟呼。何人构层楼，倒映水府居。", "凭阑纵周眺，心目乃以舒。群山从北来，柘城烟有无。", "九十九水窦，足锸十万夫。夕阳转西山，岩观正模糊。", "何处昆阳州，风帆尽南趋。俯仰一杯酒，襟怀千载馀。", "霸业垂扫尽，苍茫留此潴。海风送黄鹤，思便朝清都。", "弟妹各牵衣，白云不可呼。长啸动归桡，月上东城隅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陶渊明归田园居六诗","p":"","d":"宋代","a":"陈造","c":["种禾摭其实，即穊乃可稀。", "儒吏瞢不长，竟为老农归。", "萋芸儿可犂，称力食且衣。", "平生睎庞翁，此意今不违。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂兴六首","p":"","d":"宋代","a":"陆游","c":["故交零落形吊影，陈迹凄凉口语心。", "辛苦一生成底事，祈招空解诵愔愔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"野眺","p":"","d":"明代","a":"张宇初","c":["山谷寒应早，幽怀绝垢氛。", "白波双涧雨，红树半坳云。", "啼鸟欺新冷，潜鱼傍夕曛。", "寂寥何所慰，先哲有遗文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"齐天乐五十首 其二","p":"","d":"清代","a":"端木埰","c":["万家香霭腾金阙，余寒酿成春意。爆竹催年，铭椒献岁，又是阳和将至。", "流光逝水，怅催老英雄，者般容易。后饮屠苏，有人犹抱少年志。", "平生豪气未减，记萧斋读月，长剑孤倚。碧海屠鲸，青天饲鹤，少日心情空记，新来更喜。", "幸留得儿时，夜灯书味。为问梅华，可容同调比。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓兴二首 其二","p":"","d":"明代","a":"黄衷","c":["诸天缥缈入云门，浪遣华镳踏市喧。梦里和南多旧侣，壁间留偈总真言。", "长松石隐维摩室，蔓草金微舍利园。法眼只堪观物幻，道身宁为坐花尊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄范十九","p":"","d":"宋代","a":"刘敞","c":["君毋走马君竟走，走马蹶块伤君手。蹭蹬翻成折臂翁，世间肯要三公否。", "西郊虏骑非常壮，年年犯边杀边将。劲弓长剑如君徒，始堪追逐青海上。", "功名弃置时未可，意气激昂人所望。侧身万里风雪寒，无由赠子黄金丹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洛水铭","p":"","d":"两汉","a":"李尤","c":["洛出熊耳，东流会集。夏禹导疏，经於洛邑。元龟赤字，汉符是立。", "帝都通路，建国南乡。万乘终济，造舟为梁。三都五州，贡篚万方。", "广视远听，审任贤良。元首昭明，庶物是康。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题聂松厓印谱","p":"","d":"清代","a":"戴亨","c":["君不能身佩长剑趋明光，又不能手提孟劳开八荒。", "郁郁蓬荜不得志，慨然嗜古穷轩苍。一艺精专可千古，何须奔走荣名场。", "但持昆吾五寸铁，直探隆古龟龙穴。阴晴寒暑四十年，心摹手拟精神结。", "天不雨金鬼夜哭，魂招斯籀来奔谒。长安文苑多英奇，挥毫洒墨咸繇□。", "偶得邀君为篆刻，便觉名姓生光辉。陋我逢君苦不早，晤言欢若平生好。", "为我购石镌数方，但觉鸿黄气邃窈。印谱传为希世珍，谱中人识辽东老。", "文三桥，何雪渔，高名已并前贤驱。劝君怀宝且归去，烟霞啸傲栖蓬庐。", "蓬庐之乐乐莫比，琬琰休向街头市。君谓绝技可赢饶，千里辞家客燕邸。", "时方重利较锱铢，真赏于今竟谁是。况君负郭有良田，丰歉不至啼妻子。", "劝君早赋归去来，我实饥寒不得已。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"逍遥咏 其六","p":"","d":"宋代","a":"赵炅","c":["何处堪依仗，经心便皱眉。世情多诡诈，业重信愚痴。", "取次招他谤，违非不自知。貌恭无德行，祸福在修持。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"碧云寺","p":"","d":"清代","a":"钱谦益","c":["丹青台殿起层层，玉砌雕闹取次登。", "禁近恩波蒙葬地，内家香火傍掸灯。", "丰碑巨刻书元宰，碧海红尘问老僧。", "礼罢空王三叹息，自穿萝径拄孤藤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬日","p":"","d":"明代","a":"释函是","c":["厌闹思投老，甘心堕小乘。时危村寺稳，道替竹林增。", "适意惟高枕，清谈共数僧。海门红日下，危坐剔孤灯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"时宰生日诗三十绝 其二十二","p":"","d":"宋代","a":"周紫芝","c":["黄金新铸景钟鸣，公作铭诗纪告成。从此圣朝郊祀典，文章无复数西京。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠西平侯沐英","p":"","d":"明代","a":"解缙","c":["彩凤有遗雏，喤喤泣载途。神龙亲哺育，跃马赞皇图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"为建昌南城包显道题光风霁月之阁","p":"","d":"宋代","a":"项安世","c":["扁以槐堂之钜笔，铭以云谷之高辞。镇以平园之签帙，照以太极之肝脾。", "千岩万壑转芳气，青天碧海流清规。春晨画出舞雩咏，夜景看成彭泽诗。", "勉哉此事要真积，昔者所闻无坐驰。愿追策骥予陶子，勿但嘐嘐如牧皮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"予居云溪七载，岁岁皆有灯花，今乃得见之。同者数人，李智国命作诗。时正月十四之夜，立春之次日也","p":"","d":"当代","a":"卢青山","c":["折首枯茅仰爪丫，闻春昨至隐谁家？且抬世界灰尘眼，暂看天空幻想花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟行舣韶下石夜听","p":"","d":"宋代","a":"曾丰","c":["江响合蛮吹，鸟声谐越吟。", "仍收南郭籁，并入大韶音。", "纚纚听于耳，徐徐写以琴。", "倘犹有作韵，着语付何阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"从驾游内苑应制","p":"","d":"宋代","a":"岳飞","c":["敕报游西内，春光霭上林。", "花围千朵锦，柳捻万株金。", "燕绕龙旗舞，莺随凤辇吟。", "君王多雨露，化育一人心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"园林瞻眺同仲木作二首 其二","p":"","d":"明代","a":"康海","c":["膏雨既周彻，田工粗可期。黾勉命童仆，篮舆诣东菑。", "欣此麰麦遂，坐令芳意弥。业岁望丰衍，行乐值晴熙。", "况与良士同，更惬山水思。击筑发古调，弹筝奋新词。", "夜以继白日，潇洒孰可追。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五禽言五首，并叙 其二","p":"","d":"宋代","a":"苏轼","c":["昨夜南山雨，西溪不可渡。溪边布谷儿，劝我脱破裤。", "不辞脱裤溪水寒，水中照见催租瘢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"妙音方丈","p":"","d":"宋代","a":"黄彦平","c":["弥勒同龛夕，难摩示病情。", "炉残文武火，灯暗短长檠。", "耿介游良苦，温柔梦不成。", "颦眉挑锦字，相忆恨高城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"击蛇笏","p":"","d":"宋代","a":"白珽","c":["孔明庙前柏，手版贼其枝。", "枯秭无生气，众目炫一时。", "何如孔公笏，铁面含霜姿。", "虺蛇何足道，正气屡奸欺。", "祥符庆历间，岂无纤人斯。", "闻之胆为落，不在彼在兹。", "圣学亿万年，圣源浩无涯。", "八传得巨源，愤学求似之。", "遗经与遗物，保护如婴儿。", "万里去复远，见者咸赍咨。", "况此一尺槐，千载孔林思。", "非无原壤杖，非无少正铍。", "用舍各有时，小大各有施。", "畴能起段公，共赋甘堂诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红（甲辰岁盘门外寓居过重午）","p":"","d":"宋代","a":"吴文英","c":["结束萧仙，啸梁鬼、依还未灭。荒城外、无聊闲看，野烟一抹。梅子未黄愁夜雨，榴花不见簪秋雪。又重罗、红字写香词，年时节。", "帘底事，凭燕说。合欢缕，双条脱。自香消红臂，旧情都别。湘水离魂菰叶怨，扬州无梦铜华阙。倩卧箫、吹裂晚天云，看新月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀二首选一","p":"","d":"近代","a":"林散之","c":["自辟五亩园，辛苦二十稔。虽无长者车，孤游供息寝。", "江上易气象，日月殊光景。物换何匆匆，几醒庐生枕。", "版图惊战祸，一十九行省。城郭与池台，多半劫灰烬。", "小人与君子，多半沙虫影。念兹散木堂，犹能在人境。", "偶然亦天意，物存真自幸。年年秋风至，松竹色明靓。", "风雨又今年，寒绿更凄紧。友朋时过从，儿女有朝请。", "余生话灯火，尘缘暂相屏。功名细事耳，死生乃俄顷。", "陆沉慨神州，闰余羞蛙黾。不荷娲皇宠，谁能补完整。", "东山思太傅，西湖念和靖。疏梅共豪竹，天性各有秉。", "辜负诚可怜，转侧秋江冷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋朝览镜","p":"","d":"唐代","a":"薛稷","c":["客心惊落木，夜坐听秋风。朝日看容鬓，生涯在镜中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渡海歌","p":"","d":"明代","a":"成鹫","c":["天地之大夫如何，谛观沧海成叵罗。垂云大翼驾与鹅，乘风巨舰机中梭。", "蛟龙戏水蛇旋涡，江豚拜浪豕涉波。我生七尺胡足多，聚散珠转风中荷。", "今朝渡海天气和，柔风吹席行蹉跎。天空海阔无复他，眼前有景不得歌。", "沧波极目殊山河，朱明回首荒烟萝。登高望远无斧柯，老眼一日三摩挲。", "白云缥缈山嵯峨，东乌西匿虚阳戈。终朝形役暮则那，停舟见月扬纤蛾。", "古镜出匣尘未磨，微光照客寝复吪。三更隔水闻枯螺，千家海市枕灵鼍。", "晓来登岸人肩摩，风景恍惚曾经过。天涯走杀老头陀，江边笑倒春梦婆。", "呵呵呵，天涯走杀老头陀，江边笑倒春梦婆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朝斗坛","p":"","d":"宋代","a":"胡衍","c":["不见铜龙何处飞，空馀芳草旧台基。月明风冷禽声碎，疑是仙人佩玉归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大热二首","p":"","d":"宋代","a":"欧阳修","c":["阳晖烁四野，万里纤云收。", "羲和困路远，正午当空留。", "枝条不动影，草木皆含愁。", "深林虎不啸，卧喘如吴牛。", "蜩蝉一何微，嗟尔徒啾啾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"日本杂事诗 其一二二","p":"","d":"清代","a":"黄遵宪","c":["抟花作饭胜胡麻，嚼蕊流酥更点茶。费尽挼莎才结果，果然团子贵于花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"伤春","p":"","d":"宋代","a":"张耒","c":["山城夜来雨，卧病惜残春。", "暗暗鸟啼树，飘飘花去人。", "地偏佳客断，官冷酒钱贫。", "乘兴还骑马，田家乐更真。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠僧宗佑","p":"","d":"宋代","a":"黄彦臣","c":["潇潇丰姿迥不同，少年来住此禅丛。", "谁知今日佑和尚，便是当年钟令公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"徵招　挽择庐翁","p":"","d":"近代","a":"寇梦碧","c":["西风唤笛江城晚，凄凉顿添秋绪。薤唱冷烟沽，问鸥盟谁主。", "夜台悲碎语。抵多少、断宫零羽。剪碧词怀，听风吟兴，一暝终古。", "前度。溯追游，怜才意，题襟许陪尊俎。玄赏负深期，叹年华空误。", "素弦今独抚。剩依黯、云谣新谱。断魂远，拟叩灵阍，奈梦边无路。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"看病二首 其二","p":"","d":"明代","a":"释函是","c":["余心不得已，静想亦奚为。续命非关药，劳形只是痴。", "百年同旦夕，转盼忽支离。独坐空长啸，人天何太迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感寓 其二十","p":"","d":"宋代","a":"刘弇","c":["疾雷疑车音，出门乃知非。抱影长自明，流萤点霜帏。", "罗带剪秋水，黄金缕春衣。持看清夜阑，愁无故时辉。", "食葵心知倾，茹腊肠虚肥。纂纂枣下歌，惜此岁月违。", "因声劝语侬，忽复迟迟归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杭正月十三夜","p":"","d":"宋代","a":"方回","c":["歌鼓犹闻治世音，逃喧爱寂自沈吟。九衢翠钿春□□，一室青灯夜独深。", "岂不冻云开霁月，其如老眼异童心。□□变幻凉州梦，便觉繁华胜似今。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜坐感怀","p":"","d":"宋代","a":"唐庚","c":["声断钟楼月，文书对坐时。破窗灯焰走，冻砚笔锋迟。", "名利发将鹤，风霜手欲龟。何当一蓑雨，披晓剪莼丝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜坐","p":"","d":"明代","a":"赠钰","c":["庭虚初月上，树响微风入。栖鹊听犹惊，流萤堕还拾。", "沉沉寒漏滴，隐隐余钟急。坐久不知疲，凉衣露吹湿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"顿消缘虑","p":"喜迁莺","d":"宋代","a":"佚名","c":["顿消缘虑。觉梦蝶劳生，鹑居蓬户。饭蚁醯鸡，尘衫风帽，赢得百年虚度。利如断霞残照，名若落花飞絮。岂坚固。似风中秉烛，枝头垂露。谁悟。独归去。收拾水云，高卧曹溪路。竹外流泉，篱边丛菊，妆点野棠闲趣。五柳槛前吟醉，一笑人间今古。欲分付。叹烟波渺渺，知音何处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送何济川为庞公使庆阳席上探得冬字","p":"","d":"宋代","a":"司马光","c":["幕府遥三舍，传车乘一封。", "忠深轻远道，醉暖朱严冬。", "圁水犹飞檄，芦关未灭烽。", "贤侯虽喜士，人得久从容。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词","p":"","d":"宋代","a":"杨皇后","c":["缺月流光入绮疏，金壶傅箭梦回初。", "秦台彩凤无消息，桂影空闲十二除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪纱 其十一","p":"","d":"清代","a":"程颂万","c":["闻雨伤春梦不成。客中谁最有风情。", "武陵一曲想南征。", "蜀纸麝煤添笔媚，风帘残烛隔霜清。", "已携孤剑事离程。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莪默绝句集译笺乙集 其四八四","p":"","d":"当代","a":"伯昏子","c":["翼仙拂曙御风临，奉爵拟邀同啸吟。且唱雄王化尘土，年轮月毂碾骎骎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"好事近 赋朱庵台桂，桂为明季一老尼手植，枝柯四周蟉结，累八九层，如浮屠状，庵在秀州南堰","p":"","d":"清代","a":"朱祖谋","c":["遗世广寒仙，香界别开蟾户。一例恒沙劫换，比月盘松古。", "色身不碍被黄絁，糁地碎天布。遮莫穷檐薪尽，供箨龙斤斧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"兵乱后自嬄杂诗 其六","p":"","d":"宋代","a":"吕本中","c":["叛将斩关入，通衢列众兵。军声逐飞瓦，杀气暗前旌。", "事定愁方剧，身危梦尚惊。乾坤空纳纳，何处寄馀生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙 其一","p":"","d":"清代","a":"汪东","c":["羸病新知白发增。未妨春气透疏棂。小园梅蕊已含馨。", "伏枥尚存千里志，培风终拟九霄行。莫将修短论余生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早朝诗","p":"","d":"明代","a":"杨子器","c":["平旦曈昽瑞霭浮，曙星送月下西楼。画衣遥入迎仙跸，黄伞高擎覆采旒。", "鸾帚拂尘花雨霁，霓旌曳影柳风柔。太平无事春如海，天保歌长乐未休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"悬崖菊","p":"","d":"当代","a":"陈永正","c":["谁令此花热，衣香盈古丘。倒悬消几日，相望是何秋。", "无主偏增媚，临波始欲愁。名园尘暗动，不待雨风收。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一箩金 题扬州女子静怜月底修箫谱障子","p":"","d":"清代","a":"郑文焯","c":["镜里愁妆熏麝苦。细玉参差，却替花魂语。人瘦于花花尚妒。", "冷香吹雪开庭暮。", "罗袂禁寒谁伴汝。曲曲阑干，曲到无凭处。满把春星和梦数。", "旧情红老东风树。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵明叔九日见怀","p":"","d":"宋代","a":"周紫芝","c":["准拟重阳共一杯，幅巾临水复登台。飞花扑面君相送，落叶满山人未回。", "故国只凭幽梦到，断肠频寄尺书来。此生终向江湖老，黄菊红萸笑谩催。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"又和宋侯三首","p":"","d":"宋代","a":"刘克庄","c":["铃斋教令得民和，月色今宵十倍多。", "节物人家俱插柳，霁华田舍可鞭禾。", "坐中客醉僛僛舞，陌上花开缓缓歌。", "老子尚堪牵率在，夜归已有木鱼过。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋词","p":"","d":"元代","a":"萨都剌","c":["清夜宫车出建章，紫衣小队两三行。", "石阑干畔银灯过，照见芙蓉叶上霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望江南十三首 其七 旅窗杂忆","p":"","d":"近代","a":"丁宁","c":["幽栖好，吾自爱吾庐。满院金风朝试剑，一帘凉月夜摊书。", "曾几感离居。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"牧大同原杨林坑即事","p":"","d":"明代","a":"吴与弼","c":["既辍黄岚游，却入同原嬉。三阳时向交，暖律回春晖。", "人情惜旧好，物熊含新辉。悠哉四圣心，静向林间窥。", "单骑日日来，飘飘澹忘归。偶携二三子，丽泽同箴规。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满庭芳","p":"","d":"宋代","a":"赵令","c":["玉枕生凉，金缸传晓，败叶飞破清秋。雨余翻浪，渺渺阻行舟。暂系汀洲侧畔，风夜起、荻叶添愁。银屏远，龙香渐尽，还是梦扬州。", "更筹。何太永，当年情事，今日堪酬。最苦恨红楼，笑我飘浮。为寄相思细字，教字字、愁蹙眉头。凄凉久，渔人唱晓，随月过横沟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚晴书事呈同舍","p":"","d":"宋代","a":"陆游","c":["鱼复城边夕照红，物华偏解恼衰翁。", "巴莺有恨啼芳树，野水无情人故宫。", "许国渐疏悲壮志，读书多忘媿新功。", "因君共语增惆怅，京洛交游欲半空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"念三日酉时立秋晚对感叹","p":"","d":"明代","a":"郭之奇","c":["忽值西来爽，薄暮洒幽窗。轻烟团桂影，细霭拂漓江。", "百年衰变感，自疑蓬鬓双。飒飒同人世，悲凉满血腔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"僧园秋集同田生二首 其一","p":"","d":"明代","a":"李梦阳","c":["榴竹晴相媚，秋光满给孤。微风捎果重，残暑入林无。", "宝塔金杯映，青天白鹤呼。不须谈浩劫，吾醉亦忘吾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"厅前柏","p":"","d":"宋代","a":"苏辙","c":["稚柏如婴儿，冉冉三尺长。移根出涧石，植干对华堂。", "重露恣膏沐，清风时抑扬。我老不耐寒，怜汝堪风霜。", "朝夕望尔长，尺寸常度量。知非老人伴，可入诸孙行。", "想见十年后，檐前蔚苍苍。人来顾汝笑，诵我此诗章。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 秋夜不寐，枕上口占","p":"","d":"清代","a":"陈嘉","c":["银汉无声珠露湿。一抹秋痕，沁透诗人骨。冰簟凉生清梦惬。", "枕边茉莉花如雪。", "风飏罗帷灯欲灭。切切凄凄，向曙啼蛩急。远寺钟鸣催落月。", "纱窗微透东方白。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题郑承事所作惠兰三首","p":"","d":"宋代","a":"陈鉴之","c":["兰如君子蕙如士，此评吾得这涪翁。", "有余不足姑勿率，毕竟清幽气类同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽云屋徐侍郎 其一","p":"","d":"宋代","a":"王义山","c":["阖朝奔逸荡无关，夜半潇潇风雨寒。世乱争先寻活路，时贫输与做穷官。", "平生自谓学无事，一死谅非君所难。到此徬徨犹不忍，国亡那敢计身安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿蒋山栖霞寺","p":"","d":"宋代","a":"俞紫芝","c":["独坐清谈久亦劳，碧松燃火暖衾袍。夜深童子唤不起，猛虎一声山月高。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江乡","p":"","d":"明代","a":"郑文康","c":["江乡酒熟黍离离，莼菜鲈鱼正及时。堪笑同行门外客，月明乌鹊叹无枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题高房山夜山图","p":"","d":"宋代","a":"张逢原","c":["地位清高眼界宽，尽收风景入豪端。废宫台榭和烟锁，隔岸江山对月看。", "一水中分吴越近，层楼低接斗牛寒。有声画意吟难了，更把瑶琴膝上弹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浪淘沙 海上初秋快晴，楼望","p":"","d":"清代","a":"何振岱","c":["楼阁上初阳。净绝秋光。晨清万影辨微茫。一叶飞过瞒不得，如蝶飘黄。", "节候已新凉。倚槛天长。神游五岳梦三湘。却展道书成晏坐，小炷炉香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酒泉子","p":"","d":"唐代","a":"温庭筠","c":["花映柳条，闲向绿萍池上。凭栏干，窥细浪，雨萧萧¤", "近来音信两疏索，洞房空寂寞。掩银屏，垂翠箔，度春宵。", "日映纱窗，金鸭小屏山碧。故乡春，烟霭隔，背兰釭¤", "宿妆惆怅倚高阁，千里云影薄。草初齐，花又落，燕双飞。", "楚女不归，楼枕小河春水。月孤明，风又起，杏花稀¤", "玉钗斜篸云鬟重，裙上金缕凤。八行书，千里梦，雁南飞。", "罗带惹香，犹系别时红豆。泪痕新，金缕旧，断离肠¤", "一双娇燕语雕梁，还是去年时节。绿杨浓，芳草歇，", "柳花狂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双调忆江南","p":"","d":"当代","a":"梁羽生","c":["秋夜静，独自对残灯。", "啼笑非非谁识我，坐行梦梦皆缘君，何所慰消沉。", "风卷雨，雨复卷侬心。", "心似欲随风雨去，茫茫大海任浮沉。", "无爱亦无憎。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵杂兴二百首 其七十四","p":"","d":"宋代","a":"苏泂","c":["缚屋牵牛旋旋归，淮边绿野尽耕犁。弓刀武备何曾识，只是当初田舍儿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题盛懋秋林萧散图","p":"","d":"清代","a":"弘历","c":["佳荫之下铺芳蘅，是何处兮曰蓬瀛。青鸾白鹤两不藉，飘飘旬五御风行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"柬开周","p":"满江红","d":"清代","a":"陆震","c":["屋漏床床，是杜老、当年诗句。却今日、任生屋内，也无乾处。", "四壁篱颓浑不葺，三重茅去凭谁补。恼天公、昨夜又飘摇，桃花雨。", "或栖止，山中树。或岸上，牵船住。算古来如此，君无太苦。", "海现晴虹当户挂，瓮馀浊酒呼儿取。试寻他、王谢旧时门，馀荒土。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"庆魏伯广寿","p":"","d":"明代","a":"徐庸","c":["中吴山水多清淑，峰峦涌翠波浮绿。虞山琴川尤出奇，种秀山川有名族。", "魏君伯广号慎轩，古貌古心异流俗。襟怀夷坦绝崖岸，德能润身富润屋。", "有田千顷阅人耕，有书五车教子读。稻禾𥝧稏连三区，云子岁收仓廪足。", "礼贤下士存恭敬，恤匮赒穷罄金玉。声誉馨香比蕙兰，岁寒操守侔松竹。", "筑堤捍水功尤大，郡侯赞美诗盈轴。高风如此追古贤，青史无惭为褒录。", "年推甲子月仲冬，蓂留五荚清传馥。画堂开宴庆生申，洞天正喜蟠桃熟。", "九叠光浮翡翠屏，连枝绣展芙蓉褥。碧落行云遏不飞，朱唇皓齿歌新曲。", "兽□清燃龙脑香，鸾刀细切驼峰肉。高人硕士总称贤，衣冠济济来相续。", "臞樵先生仙之徒，丘壑峥嵘饱胸腹。蓬莱阆苑入挥洒，万里扶桑连若木。", "金银宫阙驻群仙，半衣冰绡半霞縠。瑞鸟珍禽鸣古涧，紫芝瑶草蕃深谷。", "莲叶长巢不老龙，琪花乱点长生鹿。丹青神妙夺造化，意匠经营成大辐。", "玉堂学士松雪翁，伟世高名得追逐。图成装潢为持献，按图邀我题诗祝。", "我闻老子出关图，千载传誇人刮目。古今虽异事乃同，若合符节犹式谷。", "紫霞杯香进春酒，膝前戏舞斑斓服。八千寿算比庄椿，健步从容跻百福。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"安乡县西晚泊","p":"","d":"宋代","a":"范成大","c":["水阔鸟乌倦，墟寒童仆饥。", "一湾村县过，百折暮江迟。", "晓梦孤灯见，春阴病骨知。", "简书宁不畏，旅力奈先疲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"云门大师赞","p":"","d":"宋代","a":"释智遇","c":["掉发睦州，脱赚灵树。", "赤体露金风，清波无透路。", "阿师脚跛不能行，休对乾峰南岳去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仙塘","p":"","d":"宋代","a":"利登","c":["一椽自著此山幽，芦苇萧萧绕屋头。", "野老屡来询姓字，社人相约赛春秋。", "寒山此去无飞燕，白水初传有远鸥。", "病起偶然成独往，冷烟斜照使人愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观物吟","p":"","d":"宋代","a":"邵雍","c":["时有代谢，物有枯荣。", "人有衰盛，事有废兴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵刘明远移家","p":"","d":"宋代","a":"徐玑","c":["躬耕儒者事，甘苦自能便。", "叩角吟山际，休锄坐竹边。", "长年多涉沥，丰岁少尤煎。", "一一旧所好，知君能弃捐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中读韩致光诗偶池上鹿葱盛开因效其体 其一","p":"","d":"宋代","a":"周紫芝","c":["曲栏干外水平阶，池上朱扉绕翠苔。燕子飞来人不到，鹿葱花在雨中开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮","p":"","d":"近代","a":"朱庸斋","c":["人人共说东风好。人人共向东风道。花胜去年红。定教年更丰。", "綵狮腾旭日。瑞气呈阡陌。何以报春阳。稻云连社香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将次项城阻风舟不能进","p":"","d":"宋代","a":"梅尧臣","c":["逆水寒风急，轻舟晚不前。", "因来泊古渡，聊且上平田。", "草软行方稳，鹑惊去瞥然。", "却寻孤岸远，吹帻乱华颠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐 七夕口占","p":"","d":"清代","a":"梁启勋","c":["巧如可乞。更有何人拙。垂地银河自清澈。亘古不闻呜咽。", "纱窗已入新凉。流萤明灭低昂。庭树远连天阔，双星徐度红墙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄山中诸子","p":"","d":"明代","a":"成鹫","c":["山缘渐密世缘疏，敢望良朋远寄书。地僻不知曾有雁，水清宁复叹无鱼。", "梦回冷榻闻钟后，僧老空林落叶初。一盏孤灯伴禅定，岂知人世有乘除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送吴辩叔知巩县","p":"","d":"宋代","a":"梅尧臣","c":["言为西邑宰，本是洛阳人。", "送馹往归魏，迎车来入秦。", "山川成巩固，陵庙壮威神。", "好学河阳政，栽花作县春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋浦登舟，阻风泊池口","p":"","d":"宋代","a":"杨万里","c":["牛眼化蝶化未成，梦中澒洞发大声。", "军鼙雷鼓百千面，援桴齐下作一鸣。", "起来推窗无一物，海潮打入齐山窟。", "数洲翻覆相荡摩，四山动摇皆突兀。", "钱塘潮来声惊天，金陵潮来声寂然。", "此去金陵一千里，郡得潮声来到此。", "长年三老笑复嘲，云是波声不是潮。", "清溪波头高过屋，大江波头发日毂。", "清溪去江一步地，大江可望不可至。", "北风向晚动地来，跳出银峰万万堆。", "侬船莫管行不得，且看银峰永今夕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠朱象先处士十韵","p":"","d":"宋代","a":"刘季孙","c":["前身应画师，摩诘初自许。咫尺论万里，宰也少陵与。", "朱翁趣岂凡，山水忘羁旅。晴窗布风云，夏木回炎暑。", "坐来摧虎头，兴尽秃鸡矩。况其尘外怀，出门皆胜侣。", "一画不轻付，俗子吾避汝。能令希世迹，千载得处所。", "斯人定何如，箧有东坡语。画以适其意，能文不求举。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上丁斋宿","p":"","d":"宋代","a":"张孝祥","c":["青衿陪祀忆初年，老矣斋居重慨然。俎豆不知鹅鹳事，牲牢空荐犬羊膻。", "北来被发车连野，东去乘槎浪接天。汲汲两宫常旰食，受膰归去泪如川。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏萤","p":"","d":"唐代","a":"于季子","c":["卉草诚幽贱，枯朽绝因依。忽逢借羽翼，不觉生光辉。", "直念恩华重，长嗟报效微。方思助日月，为许愿曾飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"览先祖太傅留题国清寺继和","p":"","d":"宋代","a":"赵抃","c":["得谢殊狂客，无言愧净名。心观潭月白，梵听海潮声。", "晓色开华顶，秋晖照赤城。公诗播人口，冰玉未为清。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游梅冈和石亭韵","p":"","d":"明代","a":"王韦","c":["将军埋甲处，登望一凄然。江映杯光动，岚消剑气悬。", "郊坰摧草树，时序变风烟。惟有翻经阁，还开落照边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书与士瞻上人十首 其八","p":"","d":"宋代","a":"仇远","c":["倦游懒著小乌巾，短发丝丝雪满簪。信手拈书聊慰眼，转头忘事太无心。", "笑他杜老频看镜，爱我昭文不鼓琴。喜有山林方外友，时携佳纸索新吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庐陵乐府十首 其二","p":"","d":"宋代","a":"郭祥正","c":["鸿雁殊未来，思君一弹琴。泠泠别鹤语，折尽幽兰心。", "蛛丝漫相续，难系骅骝足。白日无时停，云鬓宁长绿。", "年华要不老，不若丹青好。对之虽无言，犹胜种萱草。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"醉石","p":"","d":"宋代","a":"史尧弼","c":["有时醉浊清，随意眠小大。", "何须酒池中，始了一生课。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题喻景山大飞书房","p":"","d":"宋代","a":"陈宓","c":["仙溪七十里，半世祇闻名。一日见山色，千年怀友情。", "古匏浮美醁，清水照尘缨。霜月亭亭白，连床语到明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠吕希曾","p":"","d":"元代","a":"王佐","c":["十里长堤旧筑沙，桥林犹自拥高牙。九霄鸡犬神仙宅，七叶貂蝉宰相家。", "徐榻清风挥麈尾，谢庭春雨长兰芽。辉煌不独金符重，紫诰千函灿墨花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂诗 其十七","p":"","d":"宋代","a":"李复","c":["权利为祸根，苟合非纯士。嗟哉凭轼生，行见烹齐市。", "晴鸠不逐妇，猛虎不食子。魏国将乐羊，齐人疑吴起。", "凶险甚鸟兽，妻子自烹死。呜呼天壤间，亲无骨肉比。", "残毒就功名，于君安可恃。中山昔置相，尝取放麑翁。", "异类犹有恩，事君必致忠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖山堂再修仅有","p":"","d":"宋代","a":"方回","c":["飞鸟穿堂柱半欹，春晴犹不似春时。", "上梁文记临邛魏，天目洪家却立碑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次瑶攴石望鞋山","p":"","d":"元代","a":"陈谟","c":["舟移瑶攴下，遥望石如屣。舟人云是大姑娘，一掬弓弯曾堕此。", "吾闻古有巨人迹，姜嫄履之生后稷，神灵奇踪此其一。", "水仙罗袜凌波轻，安取盘囷如此石。又闻大禹乘四载，浚川来经彭蠡滨，遗此表徵千万春。", "江神呵禁畴敢登，偶一践踏风雷惊。导河自昆崙，砥柱碣石壮本根。", "瞿塘滟滪堆，舟航不敢争飞奔。长江钜石天意存，此其小者疑屣云。", "君不见小姑健儿女将军，剑峰屹立当海门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"仙桥渡","p":"","d":"明代","a":"郑一统","c":["金碧丛中芳未歇，天风淅淅东井冽。道人一醉紫霞归，双眼玲珑弄秋月。", "双眼玲珑弄秋月，渔声何处施罛濊。便将野渡作星槎，直泛银河访机织。", "一水盈盈异悲悦，我欲万丈驾云梁，无劳太史虚饶舌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题梅仙坛","p":"","d":"宋代","a":"刘霆午","c":["吏隐清风几百年，长松脩竹满坛前。汉皇若听三书谏，未必先生便肯仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋堂积雨新凉入","p":"菩萨蛮","d":"宋代","a":"郭应祥","c":["秋堂积雨新凉入。今宵雅乘鹏飞集。劲翮会高风。功名欬唾中。笔头元有准。快写平生蕴。何日捷书来。重阳把一杯。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"归怀","p":"","d":"明代","a":"区大相","c":["已约还山伴，春深定采芝。如何拂衣日，又过秋风期。", "疲马倦长路，栖禽思故枝。因声寄松桂，莫笑我归迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"季夏仝李郁林卢省潜卢静虚刘建侯郊外泛舟归饮贾襄一书舍","p":"","d":"明代","a":"申佳允","c":["乘兴飘摇一叶舟，阆仙许我过斋头。青毡趺坐翻书帙，白眼斜看醉酒瓯。", "树隐蝉声方噪暑，风生羽扇忽惊秋。归来不尽登临意，何日联翩续壮游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邸中种竹十二首 其六","p":"","d":"明代","a":"何吾驺","c":["静落叶有声，晓吹竿作响。寄书订七贤，让我称林长。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"木棉花歌 其五","p":"","d":"明代","a":"李云龙","c":["长林风起絮飞多，昨日朱颜鬓已皤。尽去尊前舞红袖，好风容易醉中过。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"鲜于能","c":["金山一拳石，石髻出溟涨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张在初观察席上分咏，余得蒲草","p":"卜算子","d":"清代","a":"潘飞声","c":["嫩绿点云根，雨后涵春气。戏谑金钱作小名，不是寒窗味。", "短剑剪微风，砚北闻香细。待洗寒泉白石盘，供养倪高士。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"南郊大礼诗","p":"","d":"宋代","a":"王禹偁","c":["彩城残月带微霜，版奏中严夜未央。", "三献欲终侵曙色，百神齐下散天香。", "珠旒微乱埙篪韵，迤燎轻笼剑佩光。", "此夕商山对何物，猿啼鸟哭树苍苍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清思诗五首 其一","p":"","d":"南北朝","a":"江淹","c":["赵后未至丽，阴妃非美极。情理傥可论，形有焉足识。", "帝女在河洲，晦映西海侧。阴阳无定光，杂错千万色。", "终岁如琼草，红华长翕赩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送钤辖馆使王公","p":"","d":"宋代","a":"姚涣","c":["家传勋力世能贤，四载坤维领帅权。南诏酋豪弥款附，西州士庶赖蕃宣。", "输忠感慨由诚府，接下恩勤自意筌。月夕过从多命席，花时酬唱旋成编。", "雅歌馀暇军容肃，陟状升闻帝愿延。驰驿遽趋三召节，执圭俄觐九重天。", "汉廷仪卫咸祗若，蜀郡朋僚共黯然。赐封定应留晷刻，畴庸当便进班联。", "圣神倚注期蕃锡，宥密崇高待九迁。下客尘劳遇知己，愿言攀附跂英躔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大衍易吟四十首","p":"","d":"宋代","a":"方回","c":["易乃一量秤，铢铢分重轻。", "百千亿万事，义理是权衡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"先父生日将归而雨","p":"","d":"当代","a":"卢青山","c":["天宇幂兮雨缤纷，飙风激兮搜丛林。瞻六合兮唯阴冥，惨吾怀兮阻吾程。", "言将归兮福寿阴，陵如鼓兮渊渚清。环屋竹兮绕渠衡，苔缀壁兮脊茅生。", "人虽去兮故物存，嗟秽草兮衣孤坟。望不得见兮徒辗转于吾心，仰而问兮天何以不仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游崆峒四绝 其四","p":"","d":"金朝","a":"赵秉文","c":["万松声里暮涛寒，尽在参云一望间。只欠悬流二千尺，天风吹下翠屏山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄少仪弟","p":"","d":"宋代","a":"秦观","c":["一隔音尘月屡迁，忽收来问涕潸然。", "栖迟册府吾如昨，流落江村汝可怜。", "梦里漫成池草句，愁来空诵棣华篇。", "卑飞暂尔无多恨，会有高风送上天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓雨","p":"","d":"宋代","a":"陆游","c":["东风吹雨送残春，冉冉年光次第新。", "君看枝头如许绿，争教桃李不成尘！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花　秋夜三章 其三","p":"","d":"当代","a":"卢青山","c":["我有魂兮离体起，独舞清秋，明月光华里。明月为裳光洗洗，江河为奏弦千里。", "地狱天堂皆幻拟，嗟我魂兮，毕竟归何地？生死山川长袖底，茫茫明月光无已。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢王拾遗见访兼寄篇什","p":"","d":"唐代","a":"齐己","c":["竹里安禅处，生涯一印灰。经年乞食过，昨日谏臣来。", "愧把黄梅偈，曾酬白雪才。因令识鸟迹，重叠在苍苔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题幽鸟","p":"","d":"明代","a":"张宁","c":["上苑花如锦，雕笼翡翠新。脩篁邻野树，啼鸟一般春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"史翁七十诗二首 其二","p":"","d":"明代","a":"尹台","c":["玉阳新阁绕千峦，秀挹仙霞卧可餐。紫壁度云移锦绣，青芝过雨长琅玕。", "金房定启千函秘，玉灶应成九转丹。黄发后车还拟载，钓璜入卜迓西磻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋兴和郑希大 其二","p":"","d":"明代","a":"黄衷","c":["空庭读易夜如年，秋潦仍荒种朮田。海鹤临霞终野逸，山鸡照水自华鲜。", "直修古道通延閤，欲趁回潮解钓船。君若有期先讯问，好怀多是菊花边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"近吟","p":"","d":"宋代","a":"卫宗武","c":["晚年打透利名关，十载尤欣老得閒。", "拟约绮园为隐侣，却愁无处觅商山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日偶成","p":"","d":"元代","a":"萨都剌","c":["踏马归来过早春，空阶已见草如茵。东风吹绿青溪柳，马上轻寒不著人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荒村","p":"","d":"明代","a":"韩上桂","c":["荒村馀落照，岛屿澹微明。病马嘶不得，哀蝉无限声。", "桑麻时雨过，橘柚绿烟萦。物理经行得，因之去住轻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天 晋城道中二阕 其一","p":"","d":"当代","a":"傅义","c":["不畏风尘白发侵，飞车横野复扪参。纵穿地脉几无间，才见天光忽又阴。", "山络绎，洞幽深。崖危径窄气萧森。凭栏偏爱观奇险，履险如夷最称心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南沙宿知微房奉忆","p":"","d":"明代","a":"邵宝","c":["信宿山中未得陪，老僧独为供茶杯。一时欠事庭无月，五里馀情野有梅。", "文会又从今日起，书评还待后人来。卧云字在南岩石，好谓知微莫遣苔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"均州乐二首","p":"","d":"明代","a":"器封","c":["临江贾人黄篾船，涴涴青油篙刺天。", "下船上岸买鱼酒，二八当垆夸数钱。", "烟萦罗幌春将晚，白日衔山不思返。", "珠帘红袖影傞俄，楼上明妆楼下波。", "沙棠树上娇春鸟，月出平江齐唱歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谨步陈唯生先生花甲寿原韵四章 其三","p":"","d":"清代","a":"薛昂若","c":["杖藜随处乐盘桓，更作风流王谢看。笔下生花堪并李，才高能识尚思韩。", "是翁矍铄多诗兴，惟颔仪容应问安。共向颍川开盛宴，琼筵醉酒却春寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自高梁桥泛舟过万寿寺至昆明湖之作","p":"","d":"清代","a":"弘历","c":["夹岸轻笼绿柳阴，进舟川路霁烟沈。有时送响新蝉急，无碍沿洄涨水深。", "古寺小年付僧领，西山秀色待人寻。近耽湖上风光好，雨后空明尽畅吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"叠前游山韵示诸生兼答介溪太宰","p":"","d":"明代","a":"湛若水","c":["暮春暮矣春事微，看花时复惜春晖。明年未卜今年健，十度相期九度违。", "山中闭户梅千发，都下移居燕一飞。自是明时久贪恋，拂衣争得赋来归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明陪祀西陵二首 其二","p":"","d":"明代","a":"程敏政","c":["已将微雨湿尘缨，更息寒风待礼成。万口共誇天气好，四山惟见月华明。", "寝园夜下更声促，辇道沙乾马足轻。一任朝陵常属我，新诗题遍永安城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"灵腑诸尘净","p":"南歌子","d":"元代","a":"王吉昌","c":["灵腑诸尘净，民山一气生。三田昼夜铁牛耕。鼓润风雷，金井长琼英。火力凭加减，冰肌应候烹。圆明方寸鬼神惊。悦畅仙童，饵讫恣飞行。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"清平乐 新都道中","p":"","d":"近代","a":"唐圭璋","c":["郊原平旷。竹树千家障。极目不逢山色朗。满路独轮车响。", "渐行渐远尘侵。归鸦密点寒林。向晚无人野渡，落霞红透波心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙 其十二 同纫兰四妹作，即呈雪兰大姊、蘅芳、蓉岑两妹，并怀顾羽素表妹，无锡王畹兰五妹","p":"","d":"清代","a":"杨芸","c":["记得酿寒过二月，更阑石叶香焦。闲将韵字带愁挑。", "寄情凭绿绮，缄怨付红绡。", "拾翠寻香怀旧侣，汀洲何处兰苕。天青海碧路迢迢。", "不应耽慧业，此恨几时消。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别吴而待 其二","p":"","d":"明代","a":"黎民表","c":["恋阙心仍在，还家路不迷。凄凉吊古意，疲马入青齐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题自怜待月湘帘下银烛烟多怕点镫诗意便面 其一","p":"","d":"清代","a":"锁瑞芝","c":["天风飒飒起银河，但觉帘阴次第过。曾记梨花时节雨，西窗剪烛夜寒多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九溪十八涧","p":"","d":"宋代","a":"周文璞","c":["九溪十八涧，冷见帝青苔。洗足僧书石，临流客放杯。", "案头松叶响，身畔野花开。百六辞歌吹，清游始一回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汉宫春（三和）","p":"","d":"宋代","a":"刘克庄","c":["酷爱名花，本不贪妖艳，惟赏幽姿。乌台旧案累汝，牵惹随司。冰层雪积，独伊家、点绛凝脂。应冷笑，海棠醉睡，牡丹未免丰肌。", "舞殿歌台此际，各新涂妆额，别画宫眉。那知有人淡泊，不识虫儿。春莺去也，玉参差、分付谁吹。空传得，暗香疏影，琐窗卷了还披。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双桥西溪昆仲别号","p":"","d":"明代","a":"张天赋","c":["溪有西兮便有东，桥非双建总难通。化龙川上桃花浪，吹面桥边杨柳风。", "莫讶齐驱无等第，应知济美共成功。月明鸡唱霜蹄早，驰骋天衢六合空。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏怀 其十三","p":"","d":"清代","a":"孙元衡","c":["修饰乃窥镜，容辉讵自然。托意匪膏沐，飞蓬良亦妍。", "黄鹄振六翮，素衣仪九天。骐骥释珠络，莽苍生云烟。", "如何性情事，与俗相因缘。坟典彰媚好，冠冕文拘挛。", "守真谅不察，脉脉向婵娟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送少年禅师二首","p":"","d":"唐代","a":"贯休","c":["秀眉青目树花衣，一钵随缘智不知。", "佛与轮王嫌不作，世间刚有个痴儿。", "万水千山一鹤飞，岂愁游子暮何之。", "古今此著无人会，王积新输更不疑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白鸠讴","p":"","d":"魏晋","a":"曹植","c":["班班者鸠。", "爰素其质。", "昔翔殷邦。", "今为魏出。", "朱目丹趾。", "灵姿诡类。", "载飞载鸣。", "彰我皇懿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇 题辅之叔“醉墨图”","p":"","d":"清代","a":"孙云凤","c":["座上春风，卷帘炉篆飘窗牖。娱清昼。墨花香透。滋味浓于酒。", "满纸淋漓，一试挥毫手。披图久。砚池波皱。腕底烟云走。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日平居奉寄崔伯易兼简朱元弼 其一","p":"","d":"宋代","a":"王令","c":["天风变春和，昼日差夏永。门阑闭无事，燕雀去益静。", "纷翻诗书帙，弃散懒收整。时来就枕卧，复可取窥省。", "心恬逐物闲，迹阔与世屏。鲜鲜南山暖，秀色在脩岭。", "苟嫌安坐慵，还可远游骋。自缘智能薄，反得闲暇幸。", "交朋久相远，疏懒欲谁警。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七月十日大雨晓霁登碧落堂","p":"","d":"宋代","a":"杨万里","c":["青天送归云，整如劳还师。颜行有喜色，厮役争奔随。", "晨曦映疏雨，宝灯贯银丝。落面何曾湿，洒空不胜微。", "老夫锐登山，半岭惊欲归。仰视得奇观，徙倚为久之。", "谁言李成巧，此画天下稀。却登碧落堂，四面天风吹。", "葛制忍秋寒，前夕酷暑时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"太常引","p":"","d":"宋代","a":"宋先生","c":["金丹只在自身中。真水火、炼成功。因遇吕仙公。识返本、还元祖宗。阳全阴尽，神光现处，认得自真容。名姓列仙宫。已跳出、乾坤世笼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"年年此夕东城见","p":"采桑子","d":"宋代","a":"晏几道","c":["年年此夕东城见，", "欢意匆匆。", "明日还重，", "却在楼台缥缈中。", "垂螺拂黛清歌女，", "曾唱相逢。", "秋月春风，", "醉枕香衾一岁同。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"次韵莘老初至汤泉","p":"","d":"宋代","a":"秦观","c":["夹路山重复，参天树老苍。一区成小市，数埒引温汤。", "洗沐同幽客，餔餐就梵坊。未输朝市子，斗酒得西凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵和王文明绝句漫兴十八首 其七","p":"","d":"元代","a":"刘基","c":["天边云气来须女，湖上轻雷起少男。一阵微凉疏雨过，满池莲蕊绿如簪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏春笋","p":"","d":"唐代","a":"杜甫","c":["无数春笋满林生，柴门密掩断行人。", "会须上番看成竹，客至从嗔不出迎。"],"tags":["咏物"],"z":"上番：乃川语。《猗觉寮杂记》：杜诗：“会须上番看成竹。”元诗：“飞舞先春雪，因依上番梅。”俱用上番字，则上番不独为竹也。韩退之《笋》诗：“且叹高无数，庸知上几番。”又作平声押。斩新、上番，皆唐人方言。独孤及待：“旧日霜毛一番新。”亦读去声。杨慎《丹铅录》番作筤引《易》苍筤竹为证。","y":"无数的春笋生满竹林，不仅封住了柴门还堵住了道路，那些踏着新竹来欣赏竹林的人，来到我这我都怒而不欢迎他们。","s":"","k":"诗"},
  {"t":"玲珑四犯 题画","p":"","d":"近代","a":"饶宗颐","c":["稊柳搴帘，有绣幕丛花，围住春艳。欲倩东君，貌出镜奁妆脸。", "还恐岸曲蘋风，又忍把、嫩条吹乱。更酿愁雾敛星换。", "前事几回曾见。", "画塘谁把鸳鸯荐。望疏窗、蕙葱兰茜。长绳试系西趖日，佳气舒心眼。", "才见打桨燕归，剪浪蕊，寒波万点。正拂云欲坠，风卷叶、频惊散。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿李阁老先生","p":"","d":"明代","a":"傅圭","c":["绮席春深泛紫霞，分明相府是仙家。调元正捧云中日，结实还看海上花。", "千载文光瞻北斗，九重恩渥叠黄麻。疏慵幸接龙门早，一曲南飞思未涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平坡","p":"","d":"明代","a":"何景明","c":["晚眺平坡上，苍茫万壑前。一僧行树杪，诸客到寒天。", "险骇将崩石，清怜乍坼泉。翠华公主塔，缥缈碧山巅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游宋皇陵二首 其一","p":"","d":"明代","a":"陶益","c":["郊原望望皆禾黍，寝庙萧萧哭杜宇。藓碑读罢俯閒阶，月明初照青枫树。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南歌子 其五","p":"","d":"当代","a":"程滨","c":["点雨淋头乍，游丝惹面频。珍珠额上自鳞沦。渐渐化为新泪渥檀唇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"癸酉九秋下浣菊宴赠诗十四首 其十一 赠周姻世长雪昆","p":"","d":"清代","a":"祝廷华","c":["江上新诗友，城西老布衣。订交能略分，共话每投机。", "品隽情尤介，文豪笔欲飞。濂溪遗泽远，道学懔尼微。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"以坡公君如大江日千里我如此水千山底为韵作","p":"","d":"宋代","a":"赵蕃","c":["游从二年中，离阔三百日。", "政自迹如疏，不妨心故密。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"竹林书屋","p":"","d":"明代","a":"张泰","c":["竹里巢栖隐，萧然君子居。清风蒋生径，古意邺侯书。", "凤宿寒灯外，芸香春笋馀。惟应过三益，著论辟玄虚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠谈阴阳者二首 其一","p":"","d":"宋代","a":"萧立之","c":["葬书丑唾窭与贱，只为人间觅贵饶。试问胡椒八百斛，何如陋巷一箪瓢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿陈唯生","p":"","d":"清代","a":"祝书根","c":["凭阶鞠𦜕敞华筵，虎瑟龙笙福禄骈。比算桑增株八百，曳珠客进履三千。", "充闾瑞气惊臣朔，累代清芬媲孟坚。人世期颐刚有半，难兄难弟此称贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苏武慢","p":"","d":"元代","a":"虞集","c":["一径通幽，画屏横翠，行到白云深处。世外蟠桃，井边佳橘，别有种萱瑶圃。", "檀板轻敲，素琴闲弄，奉献凤膏麟脯。舞翩翩、鹤发飘飘，仍是旧时仙母。", "君看取、华屋神仙，满堂金玉，此是蟪蛄朝暮。五色蓬莱，九秋雕鹗，别有出身之路。", "酒熟麻姑，云生巫峡，稽首洞天归去。任海波、清浅无时，何处绿窗云户。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五月九日甲子至月望庚午大雨水不已十首 其二","p":"","d":"宋代","a":"方回","c":["波浪冒原田，群鱼不自全。返常真足怪，行险绝堪怜。", "骤作乘时快，遄成失势颠。儿童拾鳗鳝，争著柳枝穿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和周公予呈向宰","p":"","d":"宋代","a":"王庭圭","c":["夜闻急雨洗氛埃，庆泽仍从天上回。寰海自应遵诏旨，管弦何用费诗催。", "东风渐著金丝柳，和气潜飞玉琯灰。遥想慈宁动新乐，禁门清晓拂云开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次东原先生与其甥魏公美画诗韵","p":"","d":"明代","a":"屠滽","c":["苍苍笔力似荆关，白发图书老不闲。未许羊昙乞西墅，画中分与旧溪山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海藏楼杂诗 其七","p":"","d":"清代","a":"郑孝胥","c":["幼时学为文，独喜柳子厚。《断刑》与《时令》，熟读常在口。", "近人尚桐城，其论深抑柳。阳湖实支派，相袭亦已久。", "柳文彼所轻，学柳更何有。奇人吾炜士，爱我忘其丑。", "咨嗟愧室辞，沈至信高手。子亦毗陵宗，胡不惮众诟？", "损名勿轻言，意子适被酒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"缘识","p":"","d":"宋代","a":"宋太宗","c":["时流求法界，问取本真诠。", "了悟空皆寂，心明海月圆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"使粤道出益阳雨后口占 其三","p":"","d":"明代","a":"黎民衷","c":["久客萧然万虑轻，殊方遥指使星明。山头杜宇声何急，翻动江南行乐情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梦中作游山绝句","p":"","d":"宋代","a":"陆游","c":["寺楼已断暮钟声，照佛琉璃一点明。", "不道溪深待船久，老僧惊怪太迟生。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"一犁春雨图","p":"","d":"宋代","a":"何异","c":["负郭先畴二顷余，饱看雨后著耕夫。", "软红尘里家山梦，却就君家阅画图。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绵州","p":"","d":"宋代","a":"汪元量","c":["绵州八月秋气深，芙蓉溪上花阴阴。", "使君唤船复载酒，书生快意仍长吟。", "击鼓吹笙欢客饮，脱巾露发看日沈。", "归来不知其所往，但见月高松树林。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和氅云见赠","p":"","d":"清代","a":"易顺鼎","c":["诗篇李峤真才子，飞鹤横汾感慨多。闽海泪枯唐日月，燕云心死宋山河。", "赤眉故国通天表，青眼高楼斫地歌。二百馀年应有此，先皇雨露在菁莪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过卢明府有赠","p":"","d":"唐代","a":"高适","c":["良吏不易得，古人今可传。静然本诸己，以此知其贤。", "我行挹高风，羡尔兼少年。胸怀豁清夜，史汉如流泉。", "明日复行春，逶迤出郊坛。登高见百里，桑野郁芊芊。", "时平俯鹊巢，岁熟多人烟。奸猾唯闭户，逃亡归种田。", "回轩自郭南，老幼满马前。皆贺蚕农至，而无徭役牵。", "君观黎庶心，抚之诚万全。何幸逢大道，愿言烹小鲜。", "能奏明廷主，一试武城弦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"龙游吴宰因劝农过寓居 其一","p":"","d":"宋代","a":"范浚","c":["令君剖剧久推贤，人谓贤如百里天。最绩已优恩已洽，讼堂无事日鸣弦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和黄农部尖叉韵 其一","p":"","d":"清代","a":"郑翰谟","c":["悄悄羁怀烛影纤，更听诗令戒申严。春风已啜醲膏粥，冬雪初消著水盐。", "塞北征辀尘满袖，巷南门幰树捎檐。巴音愧和峨洋曲，虚把瑶琴弄玉尖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"代拟无题七首","p":"","d":"当代","a":"钱钟书","c":["风里孤蓬不自由，住应无益况难留。", "勿勿得晤先忧别，汲汲为欢转赚愁。", "雪被冰床仍永夜，云阶月地忽新秋。", "此情徐甲凭传语，成骨成灰恐未休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送张法曹","p":"","d":"宋代","a":"宋祁","c":["驶骑柳枝鞭，春逵望雒廛。", "赋才宾右俊，掾诺府中贤。", "宫楯含樱密，王渠泛醳联。", "胜期资一笑，刑矢措周年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刁节推归江南此君辟孙并州幕府府罢遂弃官 其一","p":"","d":"宋代","a":"刘攽","c":["长平幕府可张罗，谁见当时宾客多。还有任安如砥柱，故山归卧恣颓波。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋山行客图","p":"","d":"明代","a":"朱诚泳","c":["凉生疏树雨初收，山气沾衣翠欲流。何物骑驴痴老子，摇鞭吟断一天秋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿迁道中 其二","p":"","d":"明代","a":"张穆","c":["小雨霏微野更青，湖田界出亩从横。馌耕健妇仍蓑笠，喜直朝晴又晚晴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨坐读史记忆子中兄茆堂已开北渠赋此奉呈三绝 其一","p":"","d":"明代","a":"刘崧","c":["中园风雨一茆茨，土壁沾濡叹地卑。昨日开渠北檐下，已通流水过南池。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和陶渊明饮酒二十首 其九","p":"","d":"宋代","a":"方回","c":["高台翳榛棘，荷锸冈路开。振衣陟云端，朗然豁秋怀。", "言念半死树，类我晚节乖。风雷劈半腹，叶落禽不栖。", "幸不为薪槱，烧之化尘泥。谓可材为琴，于调恐不谐。", "醉抱作此感，暝色南北迷。下山不可急，小僮扶我回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初夏","p":"","d":"宋代","a":"王镃","c":["杜鹃啼老万山红，天气于春便不同。", "半壁蕉云收暑雨，一帘絮雪扑晴风。", "燕巢子出雕梁暖，蚕茧蛾生翠箔空。", "闲却香车无采处，欲随簑笠看田翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"安福院二首","p":"","d":"宋代","a":"刘敞","c":["溪流婉转树蒙龙，复阁虚廊小径通。", "下马解鞍一长啸，便疑身已出尘中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吴江夜泊（三首）","p":"","d":"宋代","a":"周文","c":["愁人几点泪，不许秋风吹。", "吹入吴江里，江流无尽时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵无斁偶作二首","p":"","d":"宋代","a":"陈师道","c":["肩耸三峰峻，眉厖八字横。", "玄谈人绝倒，家法句新清。", "八俊先张子，诸公少贾生。", "已传乌鹊喜，欲听鶺鴒声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孟享仰瞻圣驾","p":"","d":"宋代","a":"邓克中","c":["辇路春风锦绣张，裁红剪绿斗芬芳。黄罗伞底瞻天表，万叠明霞捧太阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十三夜叠前韵","p":"","d":"明代","a":"程嘉燧","c":["云軿月驾要人收，合着亭台在上头。曳影轩窗含远瀑，行空阿阁俯高秋。", "招延风物争人胜，揽驻湖山放月流。何得更言官酝美，世间应笑鹤扬州。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"环佩重来轩为槐塘程文实赋 其二","p":"","d":"明代","a":"唐文凤","c":["何年斲就峄阳桐，律吕音谐指下工。相业当时勤燮理，心同虞舜鼓南风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"卜算子 谒友不遇","p":"","d":"元代","a":"王哲","c":["曩者见张公，索写词中信。王哲今朝故故来，甚没个人相近。回首跨清飚，随足云霞趁。却入全真复旧堂，把一点灵明认。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鼓浪屿宿陈秋园桐荫楼盖君昆仲奉母起居之所也","p":"","d":"近代","a":"潘受","c":["妻课茶经子酒经，梧桐长为荫园庭。夕阳楼接千山叶，大海波环一屿青。", "雨后板兴呼鹤去，云间藜杖送鸿冥。维舟来下陈蕃榻，高议金门傥许听。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题立斋天台图 其二","p":"","d":"宋代","a":"王柏","c":["出处于人不偶然，当时已报赤城缘。丹青有笔谁能画，圣则堂前月满川。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高士谦竹为崇安知县金怀赋四首 其二 晴","p":"","d":"明代","a":"陈琏","c":["闲歌淇澳步虚庭，一炷炉烟绕翠屏。试写潇湘秋半幅，砚池浮动墨花馨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"纪怀，赠李六户曹、崔二十功曹五十韵","p":"","d":"唐代","a":"元稹","c":["昔冠诸生首，初因三道征。公卿碧墀会，名姓白麻称。", "日月光遥射，烟霄志渐弘。荣班联锦绣，谏纸赐笺藤。", "便欲呈肝胆，何言犯股肱。椎埋冲斗剑，消碎莹壶冰。", "赤县才分务，青骢已迥乘。因骑度海鹘，拟杀蔽天鹏。", "缚虎声空壮，连鳌力未胜。风翻波竟蹙，山压势逾崩。", "僇辱徒相困，苍黄性不能。酣歌离岘顶，负气入江陵。", "华表当蟾魄，高楼挂玉绳。角声悲掉荡，城影暗棱层。", "军幕威容盛，官曹礼数兢。心虽出云鹤，身尚触笼鹰。", "竦足良甘分，排衙苦未曾。通名参将校，抵掌见亲朋。", "喣沫求涓滴，沧波怯斗升。荒居邻鬼魅，羸马步殑fF.", "白草堂檐短，黄梅雨气蒸。沾黏经汗席，飐闪尽油灯。", "夜怯餐肤蚋，朝烦拂面蝇。过从愁厌贱，专静畏猜仍。", "旅寓谁堪托，官联自可凭。甲科崔并骛，柱史李齐升。", "共展排空翼，俱遭激远矰.他乡元易感，同病转相矜。", "投分多然诺，忘言少爱憎。誓将探肺腑，耻更辨淄渑。", "会宿形骸远，论交意气增。一心吞渤澥，戮力拔嵩恒。", "语到磨圭角，疑消破弩症。吹嘘期指掌，患难许檐簦。", "鎩翮鸾栖棘，藏锋箭在弸。雪中方睹桂，木上莫施罾。", "且泛夤沿水，兼过被病僧。有时鞭款段，尽日醉懵僜.", "蹑屐看秧稻，敲船和采菱。叉鱼江火合，唤客谷神应。", "啸傲虽开口，幽忧复满膺。望云鳍拨剌，透匣色腾凌。", "每想潢池寇，犹稽赤族惩。夔龙劳算画，貔虎带威棱。", "逐鸟忠潜奋，悬旌意远凝。弢弓思彻札，绊骥闷牵縆.", "运甓调辛苦，闻鸡屡寝兴。闲随人兀兀，梦听鼓冬冬。", "班笔行看掷，黄陂莫漫澄。骐驎高阁上，须及壮时登。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏旱四首","p":"","d":"宋代","a":"刘克庄","c":["沟堪揭厉难车水，雨怕讥征不入城。", "沃野燥刚妨种艺，老农歌哭不成声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示周道士","p":"","d":"宋代","a":"白玉蟾","c":["人行秋色里，诗入画图中。", "笑指白云顶，猿啼第一峰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辇下春望","p":"","d":"宋代","a":"寇准","c":["独向东门凝目望，园林无处不啼莺。乡心已似杨花乱，归路那堪野草生。", "紫陌尽应趋胜地，红尘谁肯受闲名。年来却羡沧江叟，长在湖山听浪声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送同年伊翕庵中丞巡抚云南 其二","p":"","d":"清代","a":"王士禛","c":["柏台新命帝亲除，重译西南罢羽书。雒将朱鸢皆内属，越人黄屋竟何如。", "赐来天厩飞龙马，行避中丞赤棒车。荒服祇今劳睿虑，要令绝域化耕锄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"楚余生千里过访乞诗四绝以赠其行 其一","p":"","d":"明代","a":"胡应麟","c":["握手新知话未央，狂歌深夜舞鱼肠。兰陵百斛犹堪醉，莫指宜城忆故乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇（同前）","p":"","d":"宋代","a":"晁补之","c":["回雁风微，养花浓淡天容好。似春知道。吉梦佳辰到。", "共乐春台，携手蓬莱小。同倾祷。愿春不老。岁岁寻芳草。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿乔平章三首","p":"","d":"宋代","a":"程公许","c":["屋老当奈何，风雨撼四壁。", "主公志细营。所赖有匠石。", "度材林薮幽，计土帑廥积。", "心思妙规制，指授契绳尺。", "逮其万间具，夫岂一人力。", "柱天纪元功，眉寿永无极。", "周宣当中兴，拜手歌考室。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西历元日观西人操兵","p":"","d":"清代","a":"陈宝琛","c":["晓月尚挂户，趣起观操兵。千骑空市出，铠仗初阳明。", "今日西元日，岁例谁实程？整旅将司令，大豪以众并。", "亦如赴敌时，捆载随之行。隆隆台炮作，枪队连珠鸣。", "乐止忽雷动，欢呼群贺正。卫民国所事，众志宁非城？", "尚武乃有备，勖哉吾侨氓！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人第二体","p":"","d":"明代","a":"齐景云","c":["双涡红晕檀霞满。钿镜横波远。宿妆无奈是春前。", "刘郎洞口谢娘船。思无边。", "鹌鹑啄破赪桐叶。云掩圆蟾截。小楼回首绿烟迷。", "微风半夜揭珠帏。认郎归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇","p":"","d":"清代","a":"傅熊湘","c":["翠歇红销，高楼尽日伤凝睇。云山无际。天远迷烟水。", "屠狗无惊，谁识英雄意。成何计。宝刀空厉。掷向西风里。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题金廷标写意秋英十八种 其十二 翠菊","p":"","d":"清代","a":"弘历","c":["蓓蕾初舒翡翠英，绿蕉叶衬似铺琼。佛螺拟议非唐突，物物毗卢顶上行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蜀中寄李宗易宫论","p":"","d":"明代","a":"王廷相","c":["驱车西川道，幽胜一何偏。江源下裔徼，峡势蹴高天。", "我游形神适，宛宛飞云仙。鸣琴答山水，志兴良可宣。", "岁晏思故交，道拙怀高贤。君从九霄居，阿阁华景悬。", "养素回沕穆，陈力扶危颠。十载隔山海，宿心念鹓鸾。", "讵惜鱼锦字，慰此蹉跎年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二日野望作","p":"","d":"宋代","a":"林希逸","c":["麦垄高低一样青，淡云笼昼雨丝轻。梅花烂漫开将尽，松叶稀疏落又生。", "遥企钧天知梦断，欣闻玉陛庆熙成。人人尽说新年好，除夕无风岁旦晴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶寄林夫","p":"","d":"宋代","a":"沈辽","c":["南山雪未消，秋浦春太早。柳萼为谁开，梅花同我老。", "少年薄游意，落日晴空杳。林下寂无人，烟外啼幽鸟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送曾继先赴山阴路钤","p":"","d":"宋代","a":"陈傅良","c":["胡髯白尽犹强饭，髀肉添多未跨鞍。", "不向胡沙亲矢石，却来桥冢护衣冠。", "归舟自此长相背，荐墨于今尚未乾。", "只恐燕然他日事，独无名字可同刊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"麦","p":"","d":"清代","a":"弘历","c":["今年天惠均，春膏近远同。适以武功就，展谒驾言东。", "渔阳四境间，二麦皆芃芃。绿意含风新，生机饱露浓。", "屈指十三年，此景得未逢。饼饵或可期，仓箱讵易充。", "乐岁志云慰，忧民心曷穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄曾省之","p":"","d":"明代","a":"陈恭尹","c":["分居岭北南，异地幸同心。匪石能攻玉，如兰即断金。", "君从卜肆隐，予卧海门深。春别不曾送，秋风劳夜吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宋才夫作诗自言作县之况以冷官为可乐戏用韵答之","p":"","d":"宋代","a":"李流谦","c":["云霄自许当比肩，岂料坎壈逢针毡。求鱼乃欲从沮洳，吞舟见之定冁然。", "诸生但解笑便腹，好事谁肯与酒钱。吹寒固自乏暖律，使物又恨无神鞭。", "君方踏筵观艳舞，我正闭户甘草玄。閒忙亦复分苦乐，温醲淡泊无非缘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天台隐者","p":"","d":"宋代","a":"林景熙","c":["俗驾不曾到，瘦筇时复携。", "肺肝清涧饮，鬓发老岩栖。", "野巷犹鸡犬，春城自鼓鞞。", "未应人世外，别有武陵溪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"将发还乡示诸弟","p":"","d":"唐代","a":"张九龄","c":["岁阳亦颓止，林意日萧摵。云胡当此时，缅迈复为客。", "至爱孰能舍，名义来相迫。负德良不赀，输诚靡所惜。", "一木逢厦构，纤尘愿山益。无力主君恩，宁利客卿璧。", "去去荣归养，怃然叹行役。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"已亥杂诗 306","p":"","d":"清代","a":"龚自珍","c":["家园黄熟半林柑，抛向筠笼载两三。", "风雪迎裾好持赠，预教诗婢识江南。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赵师雄梅阴乍觉三首 其二","p":"","d":"明代","a":"黎景义","c":["奇缘疑梦转疑真，眼底梅花意底人。昨夜酒家疑隔世，此时林下祇孤身。", "石图疏影当琼枕，苔衬残英代锦茵。春色枝横自幽绝，依稀犹在对花神。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"广济城楼宴集追和云田宪副韵呈熊府尊时筠寇初平扳筑方就 其一","p":"","d":"明代","a":"符锡","c":["时危城守缮于年，童子能歌郡伯贤。累石层台云汉出，滨江飞槛凤洲连。", "委蛇退食开尊暇，徙倚晴空放睫便。反侧自堪清净理，淮阳几许借高眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"出郭望西山诸寺二首 其二","p":"","d":"明代","a":"胡应麟","c":["西山四百寺，寺寺金银台。莫言去天远，回首见蓬莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"霓裳中序第一 宋德寿宫芙蓉石在南榷署","p":"","d":"清代","a":"厉鹗","c":["墙阴拥翠浪。搔首繁华成俯仰。藤络苔皴草长，是亲见光尧，蓬莱无恙。", "香销玉葬。怕夜深、山鬼来往。凄凉处、奉华旧阁，记否捲帘赏。", "惆怅。疏蛬藏响。雨洗净、嶙峋十丈。芙蓉孤倚月幌。", "问点额宫梅，已归天上。冷衙蜂乍放。不照到、铜沟腻涨。", "青芜里、宣和金字，也是此情况。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿云开堂","p":"","d":"明代","a":"顾璘","c":["难逢魏母彩鸾车，聊试弥明石鼎茶。", "翠羽金支云缥缈，紫厓丹洞石", "<山含>", "岈。", "五峰黛色消晴雪，万木灵晖散晚霞。", "愿借双公玄鹤羽，月明骑上太清家。", "</山含>"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青山","p":"","d":"明代","a":"郑昆","c":["把酒对崔嵬，青山颜亦开。吾嗟不如女，曾见古人来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"静宜园二十八景诗 其五 璎珞岩","p":"","d":"清代","a":"弘历","c":["滴滴更潺潺，琴音大地间。东阳原有乐，月面却无山。", "忘耳听云梵，栖心揖黛鬟。饮光如悟此，不复破微颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"幽兰禅院柬西莲禅师","p":"","d":"清代","a":"陈谋道","c":["连云高阁郁峥嵘，俯接澄潭百尺盈。竹映帘前分晓色，泉流石畔起秋声。", "初闻仙梵空堂细，却听疏钟下界清。为爱当年飞锡地，中宵长对月华明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送襄阳成统制移建康","p":"","d":"宋代","a":"项安世","c":["日日梦长干，真成下碧湍。", "雍郊辞鹿隐，钟阜看龙蟠。", "百胜傅家学，三司践世官。", "谁知弓剑里，曾带腐儒酸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六言诗十首 其一","p":"","d":"两汉","a":"嵇康","c":["惟上古尧舜。二人功德齐均。不以天下私亲。高尚简朴慈顺。宁济四海蒸民。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"绮罗香","p":"","d":"清代","a":"郭则沄","c":["钿萼笼香，奁波漾梦，㡘外閒莺休妒。瘦损花魂，怕听四弦金缕。", "认心事、几曲阑干，斜阳影、暗留春住。记年时、手种垂杨，绿阴遮遍画楼路。", "兰成同是倦旅。愁说閒鸳旧约，江湖归去。冷鬓偎烟，换了酒怀琴绪。", "便殷勤、扶起蔫红，还担尽、夜来风雨。剩空阶、细拾香尘，断肠闻杜宇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮 扑蝶","p":"","d":"清代","a":"陆蓉佩","c":["红阑曲折通幽径。海棠带雨梨花病。蓦地见斜飞。轻轻纨扇挥。", "临风闲自弄。春去浑如梦。无力下阶行。林深何处寻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乐归田园十咏 其五 农人告余以春及至曷不委心任去留","p":"","d":"明代","a":"宗林","c":["闻得农夫说，春回畎亩间。舟车无枉迹，草木有荣颜。", "寻壑穿云去，径丘踏月还。百年宁几日，能不放心闲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无心","p":"","d":"宋代","a":"顾逢","c":["世态真堪笑，机深祸亦深。", "多谋还损己，有寿必无心。", "呕肺因诗苦，开怀遇酒斟。", "平生随造物，不暇问升沉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵王克明三首 其二","p":"","d":"明代","a":"林弼","c":["江岭孤臣抱寸忠，风雷何日起潜踪。海连辽碣八千里，山隔燕云百万重。", "近喜金滩涌鸂鶒，旧闻绿水泛芙蓉。自惭点额桃花浪，每羡神鱼作应龙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吕彦贞以诗见寄江舍次韵奉答 其二","p":"","d":"明代","a":"虞堪","c":["白石先生多逸情，寄来好句如弥明。空江落木秋正下，流水行云日自生。", "神人忽张洞庭乐，老将复捷燕山兵。雄深雅健何可得，我一把咏身如轻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"柬法忍","p":"","d":"近代","a":"苏曼殊","c":["来醉茎深露，胭脂画牡丹。", "落花深一尺，不用带蒲团。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七峰草堂移梅歌","p":"","d":"清代","a":"全祖望","c":["大江以北少梅花，相传降作杏六命。我疑陶山语未然，难缘橘户为左证。", "棱棱百花头上姿，肯逐黄尘易素性。迁之无道种无术，坐教嘉植困㱥𣩟。", "马郎兄弟双玉雪，魂与梅花同清净。有庄明瑟如篮田，有客看花满蒋径。", "暗香入梦意无厌，觅遍古欢穷绝嶝。秦淮大有槎牙种，十里江行足吟兴。", "园官小试移山手，飞度七峰疑不胫。寂寥小雪霜叶凋，峥嵘几点春牙劲。", "新寒未消九九期，徵风已动番番胜。乡心犹为石头悬，羁贯已随瓜步更。", "花王之富数花对，恰与今年梧叶称。昨闻连舟度东关，榷吏惊迓纷相侦。", "好事敢辞花税哆，佳话应为官阁咏。招邀更喜值同声，叩钵齐催诗思竞。", "我家勾馀东复东，宝岩千树苍云映。当归枨触鹪鹩枝，叉手樽前醉眼瞪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芳草","p":"","d":"唐代","a":"罗邺","c":["芳草和烟暖更青。", "闲门要路一时连。", "年年点简人间事。", "唯有春负不世情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日","p":"","d":"清代","a":"冒德娟","c":["芭蕉深绿映疏窗，高柳蝉鸣昼景长。闷卷珠帘看日影，鸳鸯相并立池塘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"城居夜坐四首 其一","p":"","d":"当代","a":"张月宇","c":["阴霾弥漫月昏昏，小隐城隅铁作门。二十八年身久蛰，千零一夜梦犹存。", "文章哭我蝇头字，粱稻怜谁犊鼻裈。待旦赁居肱垫枕，何时归卧晚香村。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"午睡","p":"","d":"清代","a":"戴亨","c":["熏风清枕簟，娇睡晕潮生。微笑朱唇启，应知梦里情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同徐监簿作水始冰","p":"","d":"宋代","a":"刘攽","c":["霜落岁将晏，风生水始冰。犹残夏虫怪，初比玉壶凝。", "气袭璇源洁，光摇宝鉴澄。涵虚同凛凛，履薄乍兢兢。", "鱼鳖悲潜伏，江湖息沸腾。淩阴如献纳，会是却炎蒸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再和天予二首 其二","p":"","d":"宋代","a":"吴芾","c":["中秋花月共徘徊，正喜相逢笑口开。君既不留吾亦去，何时又向此间来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和璞斋题岐南书舍","p":"","d":"明代","a":"朱浙","c":["小斋空坐思悠哉，心远乾坤景自开。忧国几馀华发在，逢人先觅菊花栽。", "宦囊两世惟书卷，尘事无端付酒杯。避俗底须方外去，杖藜随处破苍苔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晓枕不寐书所感三首 其二","p":"","d":"宋代","a":"周紫芝","c":["南市津头忆买船，花姑溪上钓晴烟。老来安得孤篷夜，横枕蓑衣听雨眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜子春至用前韵","p":"","d":"明代","a":"邵宝","c":["千里天台客，重来喜柰何。郡传一手劄，寺问两头陀。", "野史操无简，山人卧有蓑。隔年期故在，不放仲春过。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吊蝶","p":"","d":"宋代","a":"张至龙","c":["数日偎红翅力慵，化成长梦别春风。却怜蚁为埋香玉，舁入残花土穴中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"府君辞世一月忽焉入梦","p":"","d":"当代","a":"陈仁德","c":["遥看仿佛旧行装，仆仆风尘两鬓霜。梦里不知泉壤隔，倚门犹自话衷肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"义交堂","p":"","d":"明代","a":"钟芳","c":["丈夫慎所处，谊合志乃孚。丹漆有遗训，习染良不诬。", "哓哓竞声利，此道成榛芜。机阱隐歌笑，亲洽伤中疏。", "眷言薜氏堂，交衢通两都。博延岂不贵，所求在朋徒。", "郑贾匪我庐，蜀珍匪我居。开轩揖宾友，满座多钜儒。", "遗音启玄瑟，清辉照前除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"皂河化险为平","p":"","d":"清代","a":"张鹏翮","c":["高挂蒲帆巨浪中，青山如画水溶溶。势翻云汉飞霖雨，影息蛟龙靖北风。", "两岸桑麻随棹碧，一天皓月印潭空。欲寻当日封堆处，极目田禾翠色浓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐 天梅得里中钱氏所藏何猿叟致张诗舲手札，嘱题","p":"","d":"清代","a":"高燮","c":["东洲居士。妙语清无比。戏媵霜豪团扇底。十枝聊代精婢。", "寥寥三札留遗。楚弓楚得谁知。图卷游山盒子，羡他佳兴离披。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"太真 其一","p":"","d":"清代","a":"许南英","c":["舍身为遣六军行，掩面君王太不情！比翼鸟分连理折，负他有殿号「长生」！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽叶琼章甥女二首 其二","p":"","d":"明代","a":"沈媛","c":["十七龄来聚沫馀，芙蓉城冷待爰居。臂文朱缕他年识，祇恐天都署掌书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"邹谦所孝思堂","p":"","d":"明代","a":"杨士奇","c":["墓筑芜湖县，因之托数椽。却思严谴日，感泣更生年。", "十口今谁在，孤身秪自怜。朝朝松柏地，拜跽荐寒泉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖上","p":"","d":"宋代","a":"陈师道","c":["湖上难为别，梅梢已著春。", "林喧乌啄啄，风过水鳞鳞。", "缘有三年尽，情无一日亲。", "白头厌奔走，何地与为邻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送京运使赴召二首","p":"","d":"宋代","a":"赵蕃","c":["不官不恨落羇縻，正谓边头狱讼稀。", "但有胶胶还扰扰，略无是是与非非。", "诗书旧学浑忘却，梦寐衡祠放得归。", "邂逅两台俱趣召，莼鲈于此合知几。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"石湖草堂","p":"","d":"清代","a":"姚鼐","c":["昔为祠宇记，今访石湖园。烟水长如此，风流向古论。", "堂开悬石趾，潭隐曲岩门。满谷芳幽桂，虬枝谁与援。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"集句七言绝句诗 其十三","p":"","d":"明代","a":"孙蕡","c":["白袷玉郎寄桃叶，金鞍骏马呼小妾。翠眉蝉鬓生别离，南园绿草飞蝴蝶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"画梅（二首）","p":"","d":"明代","a":"竹庵禅师","c":["瑶台夕承月，玉砌晓凝霜。", "花映含章发，枝横禁御长。", "春风似相识，偏惜寿阳妆。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七月三十日祖母初度时年八十九","p":"","d":"明代","a":"杨基","c":["白发青瞳寿者身，每逢佳节话咸淳。", "百年未尽四千日，来岁还周九十春。", "迁客无家空望拜，孤臣有表竟谁陈。", "今朝风雨茅茨底，应对儿孙说远人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"信笔戒子种花木 其八","p":"","d":"宋代","a":"许及之","c":["买石为山任笑痴，痴翁真个似童儿。奇峰峭石勤收拾，莫使他年一篑亏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"厓山吊古 其三","p":"","d":"明代","a":"何治","c":["庙门高倚夕阳开，古木苍藤猿啸哀。金阙汴京何处所，慈元宫殿长蒿莱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观蜀鹃啼剧有感 其二","p":"","d":"明代","a":"吴伟业","c":["江关萧瑟片帆留，策马俄成万里游。失计未能全爱子，端居何用觅封侯。", "云山已断中宵梦，弦管犹开旧日楼。二月东风吹水调，鹡鸰原上使人愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水龙吟 春游即目赋得侍儿堪感路旁人","p":"","d":"清代","a":"陈维崧","c":["花间一辆雕轮，绣帏袅尽东风细。龙幡压角，翠钿㔩叶，流苏百琲。", "暗想其中，宫黄蕃锦，不过端丽。纵玉环丰艳，金堂娇贵，瑶池侣，休凝睇。", "忽见花枝徙倚。是谁家、穿帘燕子。忍当春冷，抛他幔后，坐他车尾。", "彩笔飘蓬，青衣沦贱，古来如此。料归时、浅导银灯，转那个，屏风底。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和姚燮喜潘丈迟归二章 其一","p":"","d":"清代","a":"潘德舆","c":["明越倚沧海，混茫元气间。高城独立处，傥见三神山。", "白日照金阙，天风吹佩环。琪花不可采，尘土上愁颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送顾台州","p":"","d":"明代","a":"邵宝","c":["君从西南来，复向东南去。会稽望九疑，愁云蔽江渚。", "禹穴阒无声，欲与神灵语。台州海冥冥，金城独高据。", "双旌动文星，共识君来处。君来何所将，东风共时雨。", "寄语台州人，君归愿无遽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有惠诗求酒者和答二首赠以两榼 其二","p":"","d":"宋代","a":"吕陶","c":["愁肠思得浊醪浇，浑似春苗旱欲焦。洗瓮已于坊禁碍，典琴谁向息钱饶。", "醒心未免嗟牢落，醉眼偏宜望泬寥。酩酊到来须画寝，信知毕卓胜边韶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吏隐堂","p":"","d":"宋代","a":"胡铨","c":["微风稍披冻，芳萌亦吐林。", "百鸟感春阳，钩辀弄其音。", "振策遵城曲，逍遥写烦襟。", "爱此堂下石，青润挺琅琳。", "中坳贮清泉，测之不盈簪。", "纤鳞候暖戏，寂历自浮沉。", "墨视澹忘虑，白日为移阴。", "人生本虚静，垢浊无自侵。", "忽为外物牵，至性不可寻。", "於焉得所监，一洗尘中心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春草斋遣兴","p":"","d":"清代","a":"谢蕙","c":["久甘冷澹作生涯，閒倚阑干感岁华。一架蔷薇高似屋，几丛芍药烂于霞。", "梵香缱绻思前哲，赌墅风流忆故家。我比张衡愁更甚，春衣人瘦饭难加。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冥会诗","p":"","d":"唐代","a":"宫嫔","c":["争不逢人话此身，此身长夜不知春。", "自从国破家亡后，陇上惟添芳草新。", "休说人间恨恋多，况逢佳客此相过。", "堂中纵有千般乐，争及阳春一曲歌。", "幽谷穷花似妾身，纵怀香艳吐无因。", "多情公子能相访，应解回风暂借春。", "恩情未足晓光催，数朵眠花未得开。", "却羡一双金扼臂，得随人世出将来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送马天禄给事赴云南佥事","p":"","d":"明代","a":"程敏政","c":["禁钟晓初歇，骑出城东门。惜君有远役，相携荐芳尊。", "君本琐闼彦，忠言动天阍。起居今十载，廷谢初蒙恩。", "西南万馀里，滇江浩沄沄。轺车足时雨，宪节明朝暾。", "丈夫挟壮气，抚此岁月奔。红芳漫春色，青松自霜根。", "迢遥古南服，慷慨扶风孙。行台知有道，后会须重论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"还李彀士雄卷","p":"","d":"宋代","a":"张舜民","c":["河汾之会，韩晋之津。", "在昔王马今何人，青衫木笏排风尘。", "面如桃花髭如银，长篇大字妙入神。", "关辅后辈谁等伦，四方仕宦足邅迍。", "归老阌乡玉涧滨，云为友兮山为邻。", "森森绿槊万霜筠，汩汩清涟飞两轮。", "亭上何所见，荆山早暮来相亲。", "斋中何所有，新旧歌诗千百首。", "细大搜罗万象劳，放开日月东西走。", "世上儿女徒纷纷，作者须教归老手。", "君不见古往今来富贵人，灿灿金章悬紫绶。", "金珠初入宠方深，骨肉未消名已朽。", "又不见李杜死来三百年，至今仰望如星斗。", "一联一句挂齿牙，便同金石垂长久。", "乃知皇天造万物，独於吾辈偏加厚。", "还翁诗卷翁细思，岂是生平都不偶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋十四日夜对月上南平主人","p":"","d":"唐代","a":"齐己","c":["今宵前夕皆堪玩，何必圆时始竭才。空说轮中有天子，", "不知何处是楼台。终忧明夜云遮却，且扫闲居坐看来。", "玉兔银蟾似多意，乍临棠树影裴回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿淮阴南楼酬常伯能","p":"","d":"唐代","a":"皇甫冉","c":["淮阴日落上南楼，乔木荒城古渡头。浦外野风初入户，", "窗中海月早知秋。沧波一望通千里，画角三声起百忧。", "伫立分宵绝来客，烦君步屐忽相求。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望家书","p":"","d":"清代","a":"李媞","c":["自离慈母膝，镜里鬓何如。难缩千程水，惟凭尺素书。", "苦无双鲤至，倏又产年馀。况是前番札，曾云病未除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"立春","p":"","d":"宋代","a":"陆游","c":["采花枝上宝旛新，看遍秦山楚水春。", "村舍不知时节换，傍檐百舌苦撩人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苏幕遮 李公实索慵轩词","p":"","d":"元代","a":"马钰","c":["不梳头，不洗面。馁在其中，吃饭心怀倦。无病闲眠身懒转。有客来寻，问著仍慵喘。不烧香，不礼念。落魄婪耽，酬了今生愿。日用不勤功怎见。紫诏来宣，大道无为显。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送僧东归","p":"","d":"宋代","a":"释文珦","c":["今朝送君处，草色如许新。", "后会既难定，别愁那易陈。", "分手限吴越，烟波渺无津。", "云山更重叠，归与何峰邻。", "凭人问消息，或恐非其真。", "不如早重来。勿使山猿嗔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李季允侍郎归蜀五绝用禅房花竹幽为韵 其三","p":"","d":"宋代","a":"刘宰","c":["淮海身如系，岷峨路去赊。相思冰雪里，却立嗅梅花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"纪先人旧游三首 其三","p":"","d":"明代","a":"薛瑄","c":["秖愿庭椿过百龄，宁知奄忽便摧零。旧游山水皆悲思，昔住园庐荩惨情。", "菽水有欢成昨梦，衣冠无计睹平生。孙儿指点经行处，清泪如泉散漫倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日书怀二首 其一","p":"","d":"宋代","a":"王炎","c":["杜门值春初，出门已春莫。子规日夜啼，为我诉春去。", "萋然草弥望，绿暗溪皋路。百尺游丝高，摇摇引心绪。", "归来坐窗底，有句不能吐。唤取黄奶来，且尝黑甜味。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李友路秀才赴举","p":"","d":"唐代","a":"刘禹锡","c":["谁怜相门子，不语望秋山。生长绮纨内，辛勤笔砚间。", "荣亲在名字，好学弃官班。伫俟明年桂，高堂开笑颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪纱 其二","p":"","d":"清代","a":"陈锐","c":["一掷年芳等急梭。欢愉时少别时多。相思如水不堪搓。", "倚去未妨松两鬓，啼来兀自紧双蛾。今宵愁极奈明何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天","p":"","d":"清代","a":"杨玉衔","c":["筋力登楼讵未知。山高何况入云微。虬龙许有随缘坐，猿鹤宁无入梦思。", "层嶂合，一节支。人方逸老我饥驱。打包行脚前生定，拄杖归来梦亦蘧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李员外院长分司东都","p":"","d":"唐代","a":"韩愈","c":["去年秋露下，羁旅逐东征。今岁春光动，驱驰别上京。", "饮中相顾色，送后独归情。两地无千里，因风数寄声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"泛浈江至脩仁水寻范云饮水赋诗处","p":"","d":"明代","a":"欧大任","c":["陆陟心苦艰，江行意超忽。扬舲恣击汰，理榜欣乘筏。", "昔闻范内史，于焉自怡悦。赋诗散郁陶，饮水辨清淈。", "今游属暮春，远放遵南粤。三枫睇已遥，五渡嗟应没。", "爰思雊雉驯，尚想甘棠茇。命驾税山椒，弭盖依林樾。", "明霞带远峦，瑞霭屯崇碣。樊薄粲朱樱，原陵苞绿蕨。", "感兹时物迁，惧尔芳馨歇。代更道岂殊，事往迹空揭。", "凄凄怀古吟，心赏不可越。鸱夷迥泛湖，子牟怅怀阙。", "采兰向中洲，眷此何由达。沿洄发棹讴，愉乐陶嘉月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阴廉宪见过","p":"","d":"明代","a":"欧大任","c":["滕王阁倚楚天长，秋宪相寻上短航。十载门徒文蜀郡，一时宾客杜当阳。", "匡床长啸鄱湖月，绣斧先飞粤海霜。归赴内台应独坐，建章春色望鹓行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戊戌初度二首","p":"","d":"明代","a":"袁宏道","c":["闲居心似夹冰鱼，雪里轮蹄亦自疏。", "研酒和来香泛帖，瓶花吹落湿沾书。", "艰深乍觉诗如谶，消散方知道是虚。", "一卷杂华繙未了，被人邀得过僧庐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"齐安行","p":"","d":"宋代","a":"张耒","c":["黄州楚国分三户，葛蔓为城当楼橹。", "江边市井数十家，城中平田无一步。", "土冈瘦竹青复黄，引水种稻官街旁。", "客樯朝集暮四散，夷言啁哳来湖湘。", "使君丽谯涂垩赭，门狭不能行两马。", "满城蛙噪乱更声，谷风谷谷黄鸦鸣。", "最愁三伏热如甑，北客十人八九病。", "百年生死向中州，千金莫作齐安游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂一百则 其九十八","p":"","d":"宋代","a":"释重显","c":["明珠在掌，有功者赏。胡汉不来，全无伎俩。伎俩既无，波旬失途。", "瞿昙瞿昙，识我也无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"易上","p":"","d":"清代","a":"姚燮","c":["击筑更谁歌，荒原落日多。舆图犹督亢，壮士失荆轲。", "莽莽关前树，萧萧易上波。无端千载下，有客为滂沱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送宁朔","p":"","d":"元代","a":"耶律铸","c":["说从薛烛授吹毛，从事孙吴与六韬。应策腾空调赤电，惊弦裂石试乌号。", "鼎鱼幕燕由西极，侵气游魂在北郊。击惰捣虚原有策，必须先直取窠巢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵方文敏秋兴五首 其一","p":"","d":"明代","a":"贝琼","c":["地拱皇陵松柏深，君王法驾几时临。汉宫甘露曾闻昔，周室丰年岂自今。", "太史已删金匮录，词臣应制凤台吟。忆陪仙仗千官入，春日新莺在柳阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄旧居邻友","p":"","d":"唐代","a":"齐己","c":["别后知何趣，搜奇少客同。几层山影下，万树雪声中。", "晚鼎烹茶绿，晨厨爨粟红。何时携卷出，世代有名公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八咏警戒 其五","p":"","d":"宋代","a":"吴处厚","c":["无私仍克己，克己又无私。一事兼修饰，终身在省思。", "公清多敛怨，高亢易招危。更切循卑退，方应履坦夷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寒云轻重色","p":"","d":"唐代","a":"张仲素","c":["佳期当可许，托思望云端。鳞影朝犹落，繁阴暮自寒。", "因风方袅袅，间石已漫漫。隐映看鸿度，霏微觉树攒。", "凝空多似黛，引素乍如纨。每向愁中览，含毫欲状难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"明月海棠图","p":"","d":"明代","a":"朱谏","c":["太液池边月欲坠，海棠花下杨妃醉。月照金闺春夜长，花近玉阑娇欲睡。", "东风淡荡沈香亭，花间恐有流莺鸣。玉笛声随落花去，月明不见牵牛星。", "玉人巳去春无主，御沟春暖空流水。旧时明月空自圆，花若含羞向谁语。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏贫士 其五","p":"","d":"魏晋","a":"陶渊明","c":["袁安困积雪，邈然不可干。", "阮公见钱入，即日弃其官。", "刍槁有常温，采莒足朝餐。", "岂不实辛苦，所惧非饥寒。", "贫富常交战，道胜无戚颜。", "至德冠邦闾，清节映西关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和酬入内赵供奉见赠","p":"","d":"宋代","a":"魏野","c":["出入宫闱侍从官，再过林下信温颜。", "朝天驻足因临水，驰馹迴头入望山。", "捧诏正当趋杜殿，寄诗那忽到松关。", "老来诗思尤枯竭，莫怪阳春不旋还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台城路 庚寅上巳丰城雅集，时玉树方闻震警","p":"","d":"当代","a":"王蛰堪","c":["一天花雨催春暮，魂销剑池诗酒。座上陈蕃，樽前孺子，神接兰亭时候。", "龙光射斗。尽箫客才人，曲星文宿。自古风流，漫将词笔话江右。", "京尘懒开倦眼，阴晴关冷暖，天意难叩。嫩约前盟，今鸿旧雨，泪惹相逢衫袖。", "霜毫看取。正韵逐尖叉，展缣题就。别有伤怀，劫边惊地吼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"燕京四时乐四首 其一","p":"","d":"明代","a":"王世贞","c":["城南韦曲春可怜，侯家铺埒黄金钱。即妨蹀𨇾要归去，十五搊筝杨柳烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪纱 次韩致尧韵","p":"","d":"清代","a":"吴湖帆","c":["酒晕双红烛影摇。恍然妩媚楚宫腰。漏迟无语暗心焦。", "明月侵阶情脉脉，湘帘簸梦思迢迢。枕香衾暖奈无憀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"中秋湖上看月","p":"","d":"明代","a":"虞堪","c":["楼台超有界，风月到无边。说幻难逃佛，凭虚已是仙。", "玄洲生碧草，净土出青莲。我爱杯中物，来随社里缘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题蒋溥雪中梅竹","p":"","d":"清代","a":"弘历","c":["楼雪檐晞暖未融，争春香色品量中。看来㡧里依筼绿，讶似盆间破萼红。", "即景适堪供静赏，传神应识有家风。三希重展添佳快，王氏风流若与同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长清道中二首 其二","p":"","d":"明代","a":"王樵","c":["我忆茅山下，营居碧树团。饱书堪万卷，睡日到三竿。", "有用心常乐，无挠梦亦安。何如风雪道，只跨旧征鞍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟行三章","p":"","d":"宋代","a":"刘学箕","c":["桂櫂兮兰桨，泝流兮沿回。", "天迦兮空明，湍激兮声哀。", "水落兮石出，路转兮溪回。", "鸥飞兮山净，鱼戏兮藻开。", "淹留兮何为，盍赋兮归来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"楼上","p":"","d":"清代","a":"洪亮吉","c":["楼上疏灯彻夜明，营前击柝断人行。宵严都尉亲巡栅，岁歉村农罕入城。", "岘首一书愁未报，淮南十月更孤征。霜寒不是无衣苦，凄瑟难为负米情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀故乡","p":"","d":"宋代","a":"释文珦","c":["家住潜溪云万里，别来四十九春风。", "无田种秫不归去，梦落山光水色中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八归 辛巳腊月十九日，郭筠仙“寿苏”集饮","p":"","d":"清代","a":"王闿运","c":["年年雅会，处处新诗，谁知暗里催老。散仙勘破人间世，付与将来好事，家家东道。", "湘上平安多福地，把海内、风流占了。更有峨眉归客。", "戏著雪鸿爪。借问寿苏故事，自覃溪去后，唯有杨家酒好。", "三年梦里，八仙局外，又见尊前一笑。想文章嬉骂，空洞胸怀可同调。", "且较量，红烛光中，绿梅花外，甚处得春早。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东平道中有感","p":"","d":"明代","a":"冯彬","c":["晓发东平道，淅沥风露秋。道旁有古坟，累累翳荆丘。", "翁仲互倾侧，隧路狐狸游。询之道上人，阅代公与侯。", "忆昔全盛时，赐葬承恩优。松楸蔽天日，碑板蟠龙虬。", "一朝陵谷变，名姓不可求。悠悠百年身，旦夕同蜉蝣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂七十八首","p":"","d":"宋代","a":"释正觉","c":["习习春风，丝丝春雨。", "一等沾濡，十方周普。", "甘草得之甜，黄连得之苦。", "天意发丛林，檐声闹窗户。", "古德尝云已不迷，等闲教坏人男女。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"青玉案","p":"","d":"明代","a":"杨慎","c":["盈盈春水桃根渡。问芳信、来何暮。青翰舟上，锦鸳波底，总是关情处。", "合欢新种中庭树。相思欲寄云南句。为问佳期何日许。", "飞鸿洲渚，流萤院宇。银汉双星渡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中过镇海寺访别庵上人","p":"","d":"清代","a":"吴瞻泰","c":["林樾散清阴，积翠沾凉露。濛濛光曦峰，下有化人住。", "绀宇新峥嵘，鸽王长布濩。锡飞自夔州，海角传杯渡。", "听法驯鱼龙，忘机狎鸥鹭。昨夜雨霏微，瀑洒寒泉树。", "濡足就支公，示我沧洲路。回径溜雨桥，瘦杖孤云去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠道省亲","p":"","d":"明代","a":"王恭","c":["独鸐下三天，吹笙度紫烟。道心飞鸟外，亲舍白云边。", "丹脉调香饭，霞衣拂寿筵。更教人代里，何处觅神仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江陵送僧还蜀","p":"","d":"明代","a":"宋登春","c":["烟树寒云楚水西，残瓢破衲独行迟。心无一事即相见，千里何须叹别离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花集句 其四十九","p":"","d":"宋代","a":"李龏","c":["暗香时复过窗纱，不是桃花与李花。试问花枝何处好，病来帘外是天涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"那呵滩 其六","p":"","d":"魏晋","a":"佚名","c":["百思缠中心，憔悴为所欢。与子结终始，折约在金兰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮酒十八","p":"","d":"当代","a":"添雪斋","c":["秦虢开夜宴，紫垣谁自得。长醉发中梦，呼圣众不惑。", "宣文郑卫饰，敖辟例充塞。鼎食金丹丸，上国并你国。", "鱼皮久足贵，新元冷幽默。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读史怀友","p":"","d":"宋代","a":"唐泾","c":["羞登广式议英雄，匣却吴钩弢却弓。", "幕下清谈王太尉，门前白马褚司空。", "一编袞斧风尘表，千古纲常天壤中。", "说与华阴扪虱老，何曾正朔在江东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送林光宇文学同高吴二茂才还闽四绝句 其四","p":"","d":"明代","a":"王世贞","c":["高子波澜自老成，吴郎神彩独纵横。他年并出延津剑，遥见星文动洛城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宋少府东溪泛舟","p":"","d":"唐代","a":"李频","c":["登岸还入舟，水禽惊笑语。晚叶低众色，湿云带繁暑。", "落日乘醉归，溪流复几许。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满庭芳","p":"","d":"元代","a":"王处一","c":["暂别东牟，西游登郡。万灵遥列金乡。无穷仙眷，空外总呈祥。", "休道蓬莱路远，诸真圣、都会芝阳。星坛下，凉天静夜，云宴礼虚皇。", "十方同法会，丹诚对圣，出罪行香。度九幽离苦，悉睹三光。", "见在俱蒙福祐，沾甘露、同免灾殃。逍遥乐，圆坛罢散，齐唱满庭芳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬金部王郎中省中春日见寄","p":"","d":"唐代","a":"卢纶","c":["南宫树色晓森森，虽有春光未有阴。鹤侣正疑芳景引，", "玉人那为簿书沈。山含瑞气偏当日，莺逐轻风不在林。", "更有阮郎迷路处，万株红树一溪深。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病客吟","p":"","d":"唐代","a":"孟郊","c":["主人夜呻吟，皆入妻子心。客子昼呻吟，徒为虫鸟音。", "妻子手中病，愁思不复深。僮仆手中病，忧危独难任。", "丈夫久漂泊，神气自然沉。况于滞疾中，何人免嘘eS.", "大海亦有涯，高山亦有岑。沉忧独无极，尘泪互盈襟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"景阳宫井","p":"","d":"宋代","a":"胡仲弓","c":["隋师已迫长江浒，玉树庭花曲未终。千古龙鸾有遗恨，胭脂井上至今红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过建宁县","p":"","d":"元代","a":"卢琦","c":["蓝舆度林杪，还向此中过。县古人家少，山深秋意多。", "民风原俭啬，官事只催科。赖有二三友，相从共啸歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春水","p":"","d":"清代","a":"黄邛","c":["春水门前过，落花天上来。竹竿丝袅袅，长倚钓鱼台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扬州三首","p":"","d":"唐代","a":"杜牧","c":["炀帝雷塘土，迷藏有旧楼。谁家唱水调，明月满扬州。", "骏马宜闲出，千金好旧游。喧阗醉年少，半脱紫茸裘。", "秋风放萤苑，春草斗鸡台。金络擎雕去，鸾环拾翠来。", "蜀船红锦重，越橐水沈堆。处处皆华表，淮王奈却回。", "街垂千步柳，霞映两重城。天碧台阁丽，风凉歌管清。", "纤腰间长袖，玉珮杂繁缨。拖轴诚为壮，豪华不可名。", "自是荒淫罪，何妨作帝京。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"台城路 题谢椒石观察小苏潭词后","p":"","d":"清代","a":"叶绍本","c":["一编艳制明于锦，羡煞仙才如许。禁苑文章，襜帷事业，都付檀槽金缕。", "铜驼俊侣。况公子西园，兰芽玉树。滴粉搓酥，就中多少断肠句。", "花间草堂谁数，爱风情宛转，歌翻白纻。十里横塘，一溪香雪，留得骚人且住。", "旧怀触迕。记赁庑皋桥，鸿泥前度。往事如云，乘香萦梦缕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忠厚吟","p":"","d":"宋代","a":"邵雍","c":["小人斯须，君子长久。", "斯须倾邪，长久忠厚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠医士刘怀川","p":"","d":"明代","a":"邝思诰","c":["几年修炼谢尘寰，大事因缘出世间。自养黄芽居紫府，人栽红杏遍青山。", "济生何用肱三折，不死全凭药九还。我亦云中曾煮石，逢君同得驻朱颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓言十首 其一","p":"","d":"明代","a":"胡奎","c":["客从海上来，探彼明月珠。下沈无底谷，不惜千金躯。", "得之骊龙颔，行险何其愚。君子保明哲，荣名安可趋。", "求鱼不投饵，待兔当守株。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵钱倅诸公睡香花四首 其二","p":"","d":"宋代","a":"陈造","c":["幽人睡为乡，长日踵纳息。天香唤醒然，颇复费诗力。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"平原道中见牧豕者","p":"","d":"明代","a":"尹嘉宾","c":["天门室宿郁如虹，海上萧条牧豕翁。", "会得平津开阁意，一竿寒日野田中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谒明祖孝陵","p":"","d":"清代","a":"周龙藻","c":["郁郁复苍苍，园陵气渺茫。城回江独涌，云散殿空凉。", "攒乱功初震，开基德倍昌。断蛇无剑化，铸鼎有弓藏。", "隧道悬钟鼓，明楼带阜冈。乌朝分早暮，芝产辨阴阳。", "象设规模壮，祠官礼数详。岂期休运厄，忽使寇氛攘。", "率土成猿鹤，弥天纵虎狼。燕京旋改玉，沧海遂栽桑。", "门欲罘罳坏，庭谁謦欬扬。中珰头总白。遗户业俱荒。", "亭破抛宫瓦，碑残压御墙。樵余松柏秃，烧后黍禾长。", "尚喜龙回驭，重闻骑捧香。烝尝修异世，肸蚃动今皇。", "登拜仪严肃，宣传语炜煌。共惊唐六典，犹重汉三章。", "故国游仍到，新亭感可忘。衣冠原庙尽，抔土何须惜，家居苦自亡。", "画难追贾、邓，史忍读宣、光。乍对铜驼泣，还凭石马伤，蒋山形胜在，落日半昏黄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十三绝句 其十","p":"","d":"明代","a":"王鏊","c":["三顾频繁亦未閒，金陵东下是金山。分明铁瓮头边路，载得贤人与共还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题仿石涛墨竹","p":"","d":"当代","a":"余菊庵","c":["石涛写竹本天才，我岂邯郸学步哉。偶尔兴来遏不住，淋漓泼墨写将来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游八关寺后池上","p":"","d":"宋代","a":"陈与义","c":["落日生春色，微澜动古池。", "柳林横绝野，藜杖去寻诗。", "不有今年谪，争成此段奇。", "殷勤雪颅老，随客转荒陂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"快活吟第三笔示诸儿","p":"","d":"宋代","a":"陈著","c":["小儿求我第三笔，醉中言语不择出。", "老怀空空无他肠，汝祖心事须当毕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"每日文渊阁閒思李翰林不知迁太学谁共坐论心","p":"","d":"明代","a":"杨士奇","c":["欲赠岁寒意，托之淇上竿。亭亭君子节，长似玉堂看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元方用韵寄若拙弟邀同赋元方将托若拙觅颜渊之五十亩故诗中见意","p":"","d":"宋代","a":"陈与义","c":["梦中与世极周流，错认三刀是得州。拟学耕田给公上，要为同社燕春秋。", "囊间已办青芒屦，桑间想闻黄栗留。傥有幽人咨出处，为言无况莫来休。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻边报贡虏有变","p":"","d":"明代","a":"陈万言","c":["我曾建节天雄军，赵魏良家负弩群。鸣弦跃马乐战斗，邯郸易水思前人。", "号召材官教五伐，愿言出塞护燕云。我官六月被移徙，上书幕府等空文。", "关西太史王槐野，文章纪述怀慇勤。三郡邦畿不设卫，豪雄寂寞为编民。", "上恬下熙博胜负，谁排阊阖一敷陈。穆皇践祚改元日，东夷西虏何纷纷。", "匈奴饮马潞河水，沧州一老射绝伦。掌中主客兵十万，不遗一矢徒逡巡。", "昨日报称虏远道，今朝槌岩鏖战频。东山张君真将种，饮血帐下期策勋。", "长驱跳堑冲虏阵，射雕先锋翳荆榛。橐驼人马相枕藉，傍岩百仞翻车轮。", "后军割级献枢府，皇恩犹贷贲军臣。诏从边外封京观，威震穹庐千万春。", "天生纠纠谭襄敏，都护横戈起七闽。遂拟筑台扼胡吭，累累相丽齿与唇。", "二十年来氛祲熄，谁云市马犬戎亲。偎予分竹都城下，谭公召饮酒数巡。", "抵掌高谈理燕蓟，我兵凭高战技新。书生借箸前画策，何不建置于西秦。", "公云马价入兵府，财力裕蓟应及邻。顺义虎视图西市，羌戎茶马沾皇仁。", "假虞伐虢乃其计，吾兵不守边城闉。遂致折将虏士女，西人洒泪空沾巾。", "明明天子见万里，求贤易将纷丝纶。吾友郑君负奇气，十年勋业动旒宸。", "一朝统驭连八镇，扯勒夫妇走恂恂。蹲刀衔土誓终服，外攘内治静边尘。", "杞人忧天斗西揭，安得长殳西海滨。粤南海上渔樵侣，欲作铙歌寄雁宾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和吴大史","p":"","d":"清代","a":"殷葆诚","c":["敢说同岑不异苔，尊前一揖笑颜开。方忻卿月常分照，讵料罡风又折回。", "白雪词高难续和，黄花秋好赋归来。他年双节移吴会，尽日看山再作陪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即事题小亭 其一","p":"","d":"明代","a":"王世贞","c":["过雨山城绿欲齐，一群娇鸟踏枝低。不知谢豹今何处，应在春明门外啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答殷尧藩赠罢泾源记室","p":"","d":"唐代","a":"沈亚之","c":["劳君辍雅话，听说事疆场。提笔从征虏，飞书始伏羌。", "河流辞马岭，节卧听龙骧。孤负平生剑，空怜射斗光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题谢娘秋影照 其三","p":"","d":"清代","a":"孙原湘","c":["秦淮昔梦散如尘，太傅池台宿草新。我是东山旧宾客，可堪重对卷中人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西湖十景册为唐饬轩题 其八 延祥清晓","p":"","d":"明代","a":"孙承恩","c":["日出烟霏开，湖上散清霁。采采芙蓉花，怀人渺何处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"巢云","p":"","d":"宋代","a":"李吕","c":["幽栖寄山隈，欣赏亦何有。", "时许巢白云，纷然入窗牖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和秀实别寄二篇 其二","p":"","d":"宋代","a":"王洋","c":["香火社闲棋度日，溪山伴静酒为年。碧霄鹤唳诗情远，湖院僧知茶梦圆。", "常喜春锄行佚老，每嫌棋路尚争先。平湖草岸经行好，后夜延缘刺钓船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"抵家后口占 其二","p":"","d":"清代","a":"胡煦","c":["日日亲知少送迎，不堪回首问平生。儿童老大髭须白，强半登堂说小名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题叶清甫绿波楼","p":"","d":"元代","a":"卢琦","c":["主人能拔俗，每自捲珠帘。野水春生浦，山云日傍檐。", "陶家唯酿酒，邺架尽悬签。相见波光好，秋来绿又添。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"莫君楚生以吾家绣谷老人药园诗稿见示用族祖瓯亭翁于京师重获瓶花斋旧藏丁卯集得长律三首韵酬之 其三","p":"","d":"清代","a":"吴昌绶","c":["掇拾丛残慰寂寥，短檠无寐倚寒宵。亡书积岁犹心恋，煮字长年笑腹枵。", "梦里奇编搜宛委，画中别业负渔樵。结邻幸复追皮陆，诗事同寻临顿桥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十一二用喜雪韵四首","p":"","d":"宋代","a":"吴潜","c":["只堪闭户著潜虚，欲作遨头畏简书。", "乍密乍稀云冻后，半融半落雨收初。", "封条正恐观梅错，渍谷犹疑学稼疎。", "却喜明朝春税驾，气苏{巢果换禺}{巢果换禺}与狙狙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂曲歌辞 其五","p":"","d":"唐代","a":"李廓","c":["遨游携艳妓，装束似男儿。杯酒逢花住，笙歌簇马吹。", "莺声催曲急，春色讶归迟。不以闻街鼓，华筵待月移。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行","p":"","d":"元代","a":"谭处端","c":["才见春花，又逢秋月。春花秋月何时彻。劝君速悟勿蹉跎，壶中别有佳时节。", "断爱超尘，当须猛烈。元阳固炼搜玄诀。神珠磨炼莫交昏，无来不去超生灭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重游玉屏山三著　并引 其一","p":"","d":"明代","a":"黄光宗","c":["二十馀年又一过，岩花犹对旧山河。重来尚作萧条客，四十登临感慨多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"官舍","p":"","d":"唐代","a":"白居易","c":["高树换新叶，阴阴覆地隅。何言太守宅，有似幽人居。", "太守卧其下，闲慵两有馀。起尝一瓯茗，行读一卷书。", "早梅结青实，残樱落红珠。稚女弄庭果，嬉戏牵人裾。", "是日晚弥静，巢禽下相呼。啧啧护儿鹊，哑哑母子乌。", "岂唯云鸟尔，吾亦引吾雏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海棠四首 其四","p":"","d":"宋代","a":"杨万里","c":["吾诗多为海棠哦，花意依前怨不多。已拆未开浑是韵，乍浓还淡总由它。", "留连春色能销底，请托东风定肯么。岂是少陵无句子，少陵未见欲如何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有怀前人","p":"","d":"宋代","a":"赵抃","c":["却忆东舟去若仙，江亭分袂忽经年。春风境上无多地，夜月湖中共一天。", "海阁坐观涛拥鹭，山堂吟听漏移莲。新诗往复交情见，巨集成来已百篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题自画赠王德中","p":"","d":"明代","a":"朱同","c":["月出城东头，团团上明镜。古树倚朱楼，栖乌惊未定。", "小星淡已无，大星远相映。草露发夜光，荷盘拭秋净。", "良朋喜同游，清赏寄高咏。安得白玉绳，为人系清影。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"口号","p":"","d":"清代","a":"周馨桂","c":["不树名场帜，悠悠已卅年。少惭班氏笔，老愧祖生鞭。", "远浦垂纶坐，空山枕石眠。闲来无一事，且以让时贤。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题相如题柱图","p":"","d":"明代","a":"谢迁","c":["凌云气槩欲何如，万里桥边驷马车。词赋偶缘杨得意，却将负弩诧乡闾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别陈县丞纶","p":"","d":"明代","a":"梁兰","c":["三载哦松间，一如下车初。政事岂不烦，才力自有馀。", "兹晨当弃去，轩盖盈交衢。父老谷中至，再拜倾酒壶。", "各言恒具瞻，莫若贤大夫。龙飞抚昌运，仁明迈唐虞。", "引领希重来，善保千金躯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月廿日邀同任伯卿施祓堂游曾氏园林归饮署斋即事 其二","p":"","d":"清代","a":"朱景英","c":["细路逶迤入，城南访辟疆。竹疏三径辟，树暗一扉藏。", "款客虚厨具，谭诗剩草堂。不妨留少选，幽意引春阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七夕宫词四首 其三","p":"","d":"明代","a":"何吾驺","c":["前殿初传乞巧词，月光如练印瑶池。常时一片悲秋思，未许牵牛织女知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题杨妃出浴图 其一","p":"","d":"清代","a":"陈肇兴","c":["玉貌花颜金步摇，一番澡洗倍夭娇。起来似不胜罗帔，倚定宫娥整翠翘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"《足荣杯》评审事毕偕诸公赴雷州颁奖车中有作","p":"","d":"当代","a":"熊东遨","c":["少借鸥盟意，同车向海行。诗多经眼录，水梦出山清。", "前路仍风雨，馀年减性情。嘤鸣破寥寂，只要两三声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽王端之","p":"","d":"明代","a":"程敏政","c":["君来古歙曾过我，寒日松梅话小轩。我到钱塘还访子，暖风花竹宴名园。", "笑谈追想如三宿，魂梦那知隔九原。哀些慰君君莫恨，紫霄雏凤待高鶱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花","p":"","d":"宋代","a":"张道洽","c":["孤芳嫌杀浑群芳，雪满山坳月满塘。", "韵士不随今世态，仙姝犹作古时妆。", "雪羞洁白常回避，春忌清高不主张。", "地僻何妨绝供给，饥来只用宴寒香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和贡觉除夕原韵 其二","p":"","d":"清代","a":"许南英","c":["岁晚看人忙不了，先生自在辑芸编。又亲风雅为羁客，曾咏霓裳会众仙。", "太息年光留不住，何来诗债苦相缠！效颦得句羞人后，他日骚坛愿执鞭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀往（二首）","p":"","d":"明代","a":"徐祯卿","c":["穴虫测序改，客鸟知时宴。", "严风振中野，凝霜薄飞观。", "褰裳启东户，河星出有灿。", "耿耿不遑寐，沉思遂回乱。", "何以终遥夕，明灯且濡翰。", "自我违之子，苑藻绝流玩。", "郢斤不存目，流俗耻垩墁。", "块处空堂中，谁为发言粲。", "感慨申微词，伫立倚长叹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湖州道中四首 其二 横山堂","p":"","d":"宋代","a":"孙觌","c":["苍云千亩荫平宽，露叶风枝绕舍寒。莫遣先生赋归去，且令小吏报平安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观雪二首 其二","p":"","d":"宋代","a":"杨万里","c":["坐看深来尺许强，偏于薄暮发寒光。半空舞倦居然懒，一点风来特地忙。", "落尽琼花天不惜，封它梅蕊玉无香。倩谁细撚成汤饼，换却人间烟火肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵题冷泉亭","p":"","d":"元代","a":"陈镒","c":["我游灵隐山，木落素秋景。廓然得遐观，万象分驰逞。", "古石啮水痕，寒山荡云影。投果拈白猿，扪萝陟苍岭。", "回憩泉上亭，载瀹山中茗。浊根已疏雪，至味方隽永。", "不知尘世中，有此清凉境。缅怀白使君，千载名不冷。", "摩挲石上诗，岁月发深省。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"嘉兴九日寄丹阳亲故","p":"","d":"唐代","a":"权德舆","c":["穷年路岐客，西望思茫茫。积水曾南渡，浮云失旧乡。", "海边寻别墅，愁里见重阳。草露荷衣冷，山风菊酒香。", "独谣看坠叶，远目遍秋光。更羡登攀处，烟花满练塘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丞相马挽章","p":"","d":"宋代","a":"黎廷瑞","c":["平生甚似洪文惠，暮景惜不如盘洲。纤儿何人竟误晋，大夫此日空非周。", "长夜漫漫不复旦，芳草凄凄其奈秋。遗书堕泪付千载，往从后轩云间游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄州周二选部居忧作此寄之君故以星变言事忤贵人见谪 其二","p":"","d":"明代","a":"王世贞","c":["占星疏草胜君房，匡鼎揶揄石显忙。今日中天蒙气尽，可能无意向明光。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古二十首 其十二","p":"","d":"宋代","a":"释了一","c":["礼佛无端撞赵州，却将知见作冤雠。如今四海平如掌，云自高飞水自流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"少年游 宫词，拟小山","p":"","d":"清代","a":"杨玉衔","c":["霓裳腰舞簇云罗。丝柳织莺梭。一片毡毹，钗摇钿坠，落比花多。", "有时太液恩波共，春宴付銮坡。昭阳天外，广寒宵半，缥缈闻歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送人游江南","p":"","d":"宋代","a":"晁冲之","c":["涌金门外断红尘，衣锦城边着白蘋。不到西湖看山色，定应未可作诗人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"瓜州阻风忆贾丈汉庭 其二","p":"","d":"清代","a":"缪公恩","c":["二十年前访荜门，春风携我锦春园。只今宿草无人问，何处冬青锁断魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"惠州西湖九咏苏堤 其一","p":"","d":"当代","a":"陈永正","c":["苏堤柳色界天青，丰乐桥边眼自明。最爱碧桃三月浪，轻烟如梦惠州城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登清风台谒夷齐庙","p":"","d":"清代","a":"萧惟豫","c":["我立永丰巅，首阳向我峙。遂之清风台，以访墨胎氏。", "郁郁松柏林，悠悠滦漆水。雨洗春色深，人入清风里。", "未食蕨与薇，安知肉食鄙。为顽与为廉，百年同一死。", "吁嗟黄虞人，在此不在彼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南山即事","p":"","d":"宋代","a":"胡宏","c":["南山崇崇几千丈，今晨忽被蛮烟蜑雾埋其高。安得万里飘风一吹散，见巍峨苍翠解我心郁陶。", "郁陶心匪他，为爱南山高。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江城子 方壹过冬","p":"","d":"元代","a":"尹志平","c":["严冬共喜小方壶。称幽居。论元初。话到三更，皆似觉清虚。万事有心求不得，凭象罔，获玄珠。一言了了性如如。乐无为。驾云车。朝拜高真，功满赴仙都。速悟人人俱有分，听予劝，莫痴愚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赭山","p":"","d":"清代","a":"嵇曾筠","c":["沧江括地维，瀛海包天根。赭山驾长虹，校与他山尊。", "秦王昔驱石，一一皆东奔。鞭此不为动，骨立余殷痕。", "祇今数千年，独喜岿然存。潮汐靡不由，终古相吐吞。", "伊余董蔬导，出入宜穷源。拿舟涉洪波，周历惊心魂。", "幸使井里安，夷险非所论。努力凌绝顶，列宿高可扪。", "大江自西来，潮势互飞翻。坡陀触潆洄，水石声相喧。", "于兹悟治理，扼要先蛟门。登顿跨龙脊，不觉烟岚昏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梧州归至龙门驿寄诸同志","p":"","d":"元代","a":"蓝智","c":["江转龙门一擢轻，归心不为杜鹃声。斜风细雨催离别，剩水残山管送迎。", "但使百蛮称镇静，久知四海望澄清。碧云日暮苍梧远，不尽怀人渺渺情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杏林","p":"","d":"明代","a":"王鏊","c":["陆家园里千株杏，处处花开不待春。种树由来还种德，枝头颗颗总含仁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书东寮壁","p":"","d":"明代","a":"吴与弼","c":["云卧东寮夜，寒装北返时。欲留他日迹，素壁更题诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇 寄兴","p":"","d":"明代","a":"曹溶","c":["斜掩红窗，影迷前日桃花路。送春三度，只有人如故。", "瘦减腰围，每被征衫诉。归心误，雨声深处，江上扁舟暮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"纳凉明","p":"","d":"宋代","a":"刘敞","c":["榻移随树影，杯侧见山岑。白鸟渴求水，玄蝉清噪林。", "道书无近语，天籁有遗音。向北新开径，行苔过竹阴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辛亥重九会安正堂","p":"","d":"宋代","a":"韩琦","c":["斯堂曾许占风光，须到重阳复命觞。坐上半非前岁客，杯中无改旧花香。", "初晴已过登高水，散虑宜趋自得场。唯有一时诗酒战，愿开强户振雄铓。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清河晓发","p":"","d":"清代","a":"金学莲","c":["城墙侵晓噪乌鸦，芦荻连天屋外斜。水落黄河全改岸，风晴白野半飞沙。", "车声绕路二三辆，酒店垂旗四五家。咫尺浊流犹待渡，褰裳依约上星查。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和微之药名劝酒","p":"","d":"宋代","a":"王安石","c":["赤车使者锦帐郎，从客珂马留闲坊。", "紫芝眉宇倾一坐，笑语但闻鸡舌香。", "药名劝酒诗实好，陟厘为我书数行。", "真珠的皪鸣槽床，金罂琥珀正可尝。", "史君子细看流光，莫惜觅醉衣淋浪。", "独醒至死诚可伤，欢华易尽悲酸早，人间没药能医老。", "寄言歌管众少年，趁取乌头未白前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题菊乡亭","p":"","d":"宋代","a":"陈杰","c":["晋朝徵士种菊处，满地苍云无古今。", "漫喜孤亭初结构，每怀高节此登临。", "南山日入输佳气，北阙天长驰寸心。", "瞻眺徘徊徒感慨，清风帘底坐鸣琴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南墅十二诗 其九 山阴溪曲","p":"","d":"元代","a":"廖大圭","c":["清溪流绕碧㠝岏，便作山阴一样看。今日戴公何处在，满船风雪不知寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荆渚中流，回望巫山，无复一点，戏成短歌","p":"","d":"宋代","a":"范成大","c":["千峰万峰巴峡里，不信人间有平地。", "渚宫回望水连天，却疑平地元无山。", "山川相迎复相送，转头变灭都如梦。", "归程万里今三千，几梦即到石湖边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金陵其二","p":"","d":"唐代","a":"李白","c":["地拥金陵势。", "城回江水流。", "当时百万户。", "夹道起朱楼。", "亡国生春草。", "离宫没古丘。", "空余後湖月。", "波上对江洲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"澳洲观感","p":"","d":"当代","a":"傅义","c":["南荒僻远岛，土著少而贫。与昔共驩辈，化如尧舜民。", "海风送恬梦，山木荫长春。猫犬承欢宠，依偎乐近人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三代门。又吟","p":"","d":"唐代","a":"周昙","c":["千妖万态逞妍姿，破国亡家更是谁。", "匡政必能除苟媚，去邪当断勿狐疑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游仙四首 其一","p":"","d":"明代","a":"郑学醇","c":["宫阙玲珑向晓开，有人云此是瑶台。梦中不记仙凡隔，听得鸾笙几奏回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日怀归","p":"扫花游","d":"宋代","a":"周密","c":["江蓠怨碧，早过了霜花，锦空洲渚。孤蛩暗语。正长安乱叶，万家砧杵。尘染秋衣，谁念西风倦旅。恨无据。怅望极归舟，天际烟树。", "心事曾细数。怕水叶沉红，梦云离去。情丝恨缕。倩回文为织，那时愁句。雁字无多，写得相思几许。暗凝伫。近重阳、满城风雨。"],"tags":["重阳节", "典故", "思念"],"z":"","y":"","s":"","k":"诗"},
  {"t":"田舍视穫夕归","p":"","d":"明代","a":"欧大任","c":["明农及兹日，谷口出荆扉。夜柝传餐去，秋场获稻归。", "黄鸡啼月早，紫蟹受霜肥。最是村砧急，天寒木叶飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沜东宴集值风雷大作","p":"","d":"明代","a":"王九思","c":["日暮俄吹万里风，西原牛马下巃嵷。震雷挟雨千峰黑，高岸飞花一涧红。", "扫兴顿教棋局散，停歌非为酒樽空。须臾玉宇还开霁，皓月留人意未穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自清华西行村落间殊胜平畴流水果园竹径骤作乡思","p":"","d":"明代","a":"陆深","c":["燕麦青青柿叶肥，江南回首正依依。千竿新竹消苍雪，一带遥山深翠微。", "閒任野禽啼樾坞，细分流水绕柴扉。那知身是乘骢客，疑向花前跨鹤归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵曾都曹喜雨","p":"","d":"宋代","a":"黄庭坚","c":["水旱国代有，人神理本通。", "偏雩祠小大，敢指蜺雌雄。", "地厌焚惔极，天回顾盼中。", "蛟龙起乖卧，星斗晦澄空。", "云挟雷声走，江翻电脚红。", "宠光归稼穑，滴沥在梧桐。", "詖讼犹相及，时霖恐未丰。", "洁斋蕲得岁，同病托诸公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送李青归南叶","p":"","d":"唐代","a":"李白","c":["伯阳仙家子，容色如青春。日月秘灵洞，云霞辞世人。", "化心养精魄，隐几窅天真。莫作千年别，归来城郭新。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵昌龄西园十咏 其七 杉","p":"","d":"宋代","a":"王十朋","c":["记得先人手自栽，森然千尺尽成材。翠丝结作思人树，它日儿孙岂忍摧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感事述怀，集杜二十首 其五","p":"","d":"清代","a":"陈肇兴","c":["乱离知又甚，留滞敢辞劳！壮惜身名晚，悲怜子女号。", "一旬半雷雨，八水散风涛。生死论交地，寸心铭佩牢。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"竹坡丘知府哭子以偈寄之","p":"","d":"宋代","a":"释居简","c":["绝杨合为扬雄叹，无子当于伯道哀。尚有曾元养曾子，少宽夫子哭颜回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题画","p":"","d":"清代","a":"杨光仪","c":["一篱秋色印寒沙，风味柴桑处士家。不耐骑驴城里去，屋南山下踏槐花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古意 其二","p":"","d":"明代","a":"屈大均","c":["风流水杨柳，宜水复宜风。莫即为花絮，飘飏西复东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过鲁港驿和贯酸斋题壁","p":"","d":"元代","a":"萨都剌","c":["吴姬水调新腔改，马上郎君好风采。玉郎一去春草深，谩有狂名满江海。", "歌诗呼酒江上亭，墨花飞雨江不晴。江风吹破蛾眉月，我亦东南西北征。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"毛贞夫参政别予笼一白鹤与丹书一函见遗即席戏成二首答之 其二","p":"","d":"明代","a":"孙一元","c":["半世徒誇万卷功，埋头今作蠹鱼虫。元知天上多文字，云篆烟书更不同。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感怀十首 其六","p":"","d":"当代","a":"崔荣江","c":["此身无骨重燕台，心与形骸并劫灰。浑璞曾经开璧玉，栋梁也许斫樗才。", "行藏悖世当多舛，白袷蒙尘自久哀。抽茧平生丝已乱，何机织就又重裁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梁园赏花四首 其一","p":"","d":"明代","a":"张弼","c":["鲜飙破阴阴复霁，柏屏槐盖凝花气。牡丹阑珊芍药芳，锦云遮花留青帝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"下摄市","p":"","d":"宋代","a":"乐雷发","c":["吟到湘潭一叶黄，贾胡踪迹正悲凉。", "抱琴沽酒异乡客，打鼓发船何郡郎。", "楚女越商相杂沓，淮盐浙楮自低昂。", "尘埃市井无人识，濯足江头望八荒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠友人游太学归东广","p":"","d":"明代","a":"黄廷用","c":["折柳怜春暮，调兰爱日长。燕云如点缀，粤树更微茫。", "双剑冲南斗，孤帆下夕阳。谈经曾壁水，梦寐圣宫墙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题李淩洲为陈雨三画美人纨扇","p":"","d":"清代","a":"许南英","c":["淩洲道人老曹掾，丘壑胸中千万变。从来名士悦倾城，道人下笔开生面。", "肥环瘦燕是前身，石上含香想旧因。莫是汉宫同伴妒，昨宵谪贬落风尘？", "陈子无端生艳羡，乞画蛾眉入纨扇。祗爱空中见色身，岂真肉髅堪系恋？", "自从小劫历沧桑，廿年自据一胡床。美眷如花间列屋，好龙竟似沈诸梁。", "我正与君反比例，乞图作佛书揭谛。忏除结习净尘根，寡过未能思强制。", "目中有色心中无，如君亦自非凡夫！情丝到处如罗网，谁脱人间地狱图？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭内 其二","p":"","d":"明代","a":"许相卿","c":["偕老旧盟废，半生清影单。好名吾独累，分谤子能贤。", "泪咽垂髫女，吞声执手言。间关句曲路，忆著便潸然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归梦","p":"","d":"清代","a":"吴之章","c":["东南归路将千里，高滩急峡石齿齿。昼夜狂澜吼雷霆，客子坠心惊不已。", "舴艋戒严旬有余，及至抵家差足喜。昨夜扁舟何太轻，乘风破浪独扬舲。", "出江入江须顷刻，依稀叱驭驾长鲸。式遏倒卷乱流争，瘴烟净尽天廓清。", "到门稚子欢前迎，入觐庭闱喜不胜。山妻呼酒酌中庭，庭下黄花照眼明。", "绿醅酷带寒香冽，酣饮闻鸡催晓月。西风半夜撼树巅，惊悟方知梦飞越。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"召伯水落","p":"","d":"宋代","a":"孔平仲","c":["朝落一寸水，暮落一寸水。卷水去入湖，更值南风起。", "舟行意虽急，滞碍乃如此。矗矗在吾前，千艘正衔尾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题进士郑良所藏画二首 其一 折梅枝","p":"","d":"明代","a":"邓林","c":["春到江南几许时，东风未报故人知。陇头便使何当发，欲折馨香寄一枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游青城山","p":"","d":"宋代","a":"杨可弼","c":["我笑羊叔子，岘首矜一生。", "又怪谢阿客，伐山觅峥嵘。", "岂如铜梁守，出门便赤城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送叶尚书奉祠二首 其二","p":"","d":"宋代","a":"刘克庄","c":["身于七邑最孤寒，每辱黄堂刮眼看。乍可郡无九年蓄，要令民受一分宽。", "公闲去伴种司谏，我懒思寻靖长官。曾出龙门称弟子，感知惟有寸心丹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日书怀","p":"","d":"明代","a":"王缜","c":["迟日轻风淑气融，柳花飞白小桃红。泛观万物全于我，细数三春半在公。", "修褉事阑知俗异，浴沂人远许谁同。年年东阁门墙里，一寸时光一寸功。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"移兰","p":"","d":"宋代","a":"释居简","c":["莸劣薰优只自强，寄林亦足称孤芳。故应纫佩成春服，不为无人閟国香。", "移傍瘦筠同雨露，怕随行苇践牛羊。客非九畹同心事，莫反离骚吊碧湘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二月朔于鳞招饮二首 其二","p":"","d":"明代","a":"许邦才","c":["城头柳色望成堆，随送春风入酒杯。知己百年谁好在，花边那忍独醒回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玄真院题画二首 其一","p":"","d":"明代","a":"张宁","c":["金阙琼楼虎豹关，蓬莱方丈五云间。登高一望秋无际，徐福楼船几日还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"钦和御制江东桥诗 其一","p":"","d":"明代","a":"释宗泐","c":["玉作阑干石作梁，银河清夜共辉光。经营自出天工妙，锼琢仍归匠者良。", "大驾亲临观气象，群臣载拜献词章。谁知千古不磨迹，地久天长转更彰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宋九青给谏将联诗社诗以商之三首 其三","p":"","d":"明代","a":"郭之奇","c":["移风真首务，观世本文心。历探情声始，返思得失林。", "欲求人尽我，不令古无今。一往同孤尚，千秋讵可禁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游潘墺魏都冶墓庵","p":"","d":"宋代","a":"舒岳祥","c":["弄日微阴驾笋舆，柴桑五子共携扶。", "云门钟鼓先朝赐，丞相门庭近日殊。", "绿树两行溪贯串，青峦百摺路萦纡。", "惟余守冢鹰窠在，采捕令严无牧刍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"简胡祭酒 其一","p":"","d":"明代","a":"杨士奇","c":["重阳醉后又三日，想见黄花绽始多。门巷深沈无俗客，高斋清坐养天和。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寡妇诗","p":"","d":"魏晋","a":"曹植","c":["高坟郁兮巍巍。", "松柏森兮成行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"塞上","p":"","d":"唐代","a":"曹松","c":["边寒来所阔，今日复明朝。河凌坚通马，胡云缺见雕。", "砂中程独泣，乡外隐谁招。回首若经岁，灵州生柳条。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宿","p":"","d":"宋代","a":"林季仲","c":["万壑千岩簇马蹄，羞将尘鬓照清溪。晚云带雨东风急，无数飞花过竹西。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"养心殿晚坐","p":"","d":"清代","a":"弘历","c":["园亭多水木，自是气清凉。宫禁翡翠瓦，五雉围红墙。", "夏候所弗宜，暖气蒸炎阳。朝仪讵可阙，适已宁云臧。", "兹来乃迥别，竟日爽风飏。立秋迟三日，律先报白藏。", "晨从郊外来，多稼云将黄。既欣望岁稔，且免筹边章。", "九州奏书达，云时若雨旸。诸凡皆顺吉，惟是敬不遑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和刘后村梅花百咏","p":"","d":"宋代","a":"方蒙仲","c":["雨霰潇潇天地宽，相看岛瘦与郊寒。", "埋腰立雪心良苦，拥鼻吟风事大难。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和柳子玉官舍十首之思山斋","p":"","d":"宋代","a":"黄庭坚","c":["吴儿心著吴山深，满目终南不开慰。", "有时蝉蜕书几边，梦到五湖千里外。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"广寒宫殿五云边","p":"太常引","d":"宋代","a":"汪元量","c":["广寒宫殿五云边。看天上、烛金莲。香袅御炉烟。拥彩仗、千官肃然。世间王母，月中仙子，花甲一周天。乐指沸华年，更福寿，千年万年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"象州道中二首 其一","p":"","d":"宋代","a":"李纲","c":["路入春山春日长，穿林渡水意徜徉。溪环石笋横舟小，风落林花扑面香。", "山鸟不知兴废恨，岭云自觉去来忙。炎荒景物随时好，何必深悲瘴疠乡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵学士兄春日谩成","p":"","d":"宋代","a":"李弥逊","c":["飘泊悲生事，人情翻手云，", "习闲真似懒，补拙谩知勤。", "老作渔樵计，梦观钟鼎动。", "成亏皆一戏，不复问斯文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谷雨江右诗社周年萍乡小石源雅集 其四 游孽龙洞有感其更名为义龙洞用进退格","p":"","d":"当代","a":"陈忠平","c":["一洞幽深鱼贯行，眼前顽石幻奇形。或为虾鳖依崖立，曾佐龙蛇倒海惊。", "过处阴风犹凛冽，当年恶迹渐零星。也无轻怪后来者，竟把妖邪冠义名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别陈子","p":"","d":"明代","a":"申佳允","c":["悠悠滏水梦，落落剡溪舟。竹乱连床雨，灯悬一榻秋。", "奚囊诗草黯，客舍墨香浮。前路谁知己，天涯破阮愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵晚香西兴","p":"","d":"清代","a":"缪祐孙","c":["鼓吹夕阳天，迎宾小驿船。云容垂远溆，人语隔秋烟。", "柝击长街肃，镫悬使馆圆。独欣前事在，郭李说登仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题欧阳炳文真止亭","p":"","d":"宋代","a":"刘才邵","c":["前浪与后浪，推引不自休。谁知桥下水，终古何曾流。", "喧寂两俱遣，已自非良谋。避喧趋寂者，岂免一处收。", "吾人识真际，不向中边求。聊复起小亭，对此竹桧幽。", "云烟互明灭，草木自春秋。诸法如露电，乾坤一浮沤。", "试看究竟处，还有起灭不。想当隐几时，萧然任天游。", "不同习枯禅，兀兀守一丘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张用宜丹房十咏 其八 丹灶","p":"","d":"明代","a":"徐庸","c":["炼就芙蓉丹，满灶春如海。我欲到君家，分来驻颜彩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水龙吟 和郑彦章韵","p":"","d":"元代","a":"王沂","c":["画檐疏雨才收，酒醒凝掩篷窗卧。薰炉火冷，余香犹在，拥衾清坐。", "点鬓霜明，窥人月小，短擎花堕。想吴山越水，楼台缥缈，应曾有，飞鸿过。", "寂寞文园病后，旧心情、苦无些个。多君调我，幽兰新句，纹笺玉唾。", "花落元都，鹤归华表，梦谁擎破。待莼鲈江上，高歌小梅，扣舷相和。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日郊行 其六","p":"","d":"清代","a":"弘历","c":["烟磴盘盘夹树斜，离宫邻是梵王家。桃花也解将迎意，对客先霏岭上霞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠枢上人","p":"","d":"宋代","a":"陈宓","c":["心期极乐三千界，世事怀安二十年。顾我未能从学道，祇将寂寞当幽禅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东坡八首，并叙 其二","p":"","d":"宋代","a":"苏轼","c":["荒田虽浪莽，高庳各有适。下隰种粳稌，东原莳枣栗。", "江南有蜀士，桑果已许乞。好竹不难栽，但恐鞭横逸。", "仍须卜佳处，规以安我室。家僮烧枯草，走报暗井出。", "一饱未敢期，瓢饮已可必。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊居","p":"","d":"明代","a":"朱硕熏","c":["结屋临溪水，悠然心自闲。泉分杯底月，云共枕前山。", "芳树经春合，幽禽薄暮还。邻人借渔钓，嗑尔款柴关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄丰叔良（二首）","p":"","d":"明代","a":"陶安","c":["阿咸九月到，寄我尺书看。", "尽日不释手，空江频倚栏。", "乡山微雨外，客梦一窗寒。", "遥想林泉胜，无忧寝食安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"胡家窝铺","p":"","d":"清代","a":"戴亨","c":["险溺胡家铺，行人莫不闻。地顽常带卤，山蠢不生云。", "草滑埋蛇穴，风腥过虎群。往来经此处，踯躅畏斜曛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古二十四首","p":"","d":"宋代","a":"释宗演","c":["今朝十月十五，有误诸人来此。", "山僧口似匾担，说禅烦拄杖子。", "一击忘所知，更不假修持。", "黑蛇当大路，狮子逞全威。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"用韵答游司直见寄","p":"","d":"宋代","a":"洪咨夔","c":["道在皇王帝霸间，古今同是一人寰。", "不愁垂白三千丈，独喜飞黄十二闲。", "晚桂荐花熏鼎古，寒松堕子茗瓯斑。", "山中风味无人会，赖得新诗起老顽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南斋竹三绝 其三","p":"","d":"宋代","a":"苏辙","c":["里中佳客旧孙陈，我自疏慵不见人。目倦细书长掩卷，心游法界四无邻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游灵岩山","p":"","d":"当代","a":"陈伟强","c":["吴王宫化梵王宫，古木森森落晚钟。凤屧不来香径冷，野蜂飞上玉芙蓉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过应山县吊杨忠烈公","p":"","d":"清代","a":"乔莱","c":["呜呼！有明神宗之季国卼臲，光宗继之更短折。维时先生官给事，顾命乃与大臣列。", "防微肩巨定大计，选侍移宫一朝决。再起中丞赴双阙，大柄已被阉人窃。", "干儿义孙满庙廊，二十四罪愤所切。赤县争高宦者祠，彤庭遍染中丞血。", "讵有婪赃杨大洪，舍人宁死心如铁。或言汉之厨顾洁其名，唐之牛李营其穴。", "宋之洛蜀明东林，党祸纷纷蹈覆辙。封疆已被门户误，遂讥先生太激烈。", "我谓此言殊不然，藉口保身附明哲。假使当年稍媕婀，张禹孔光更何别？", "君子岂能误国家，目为党人正气绝。呜呼！正气绝，国乃灭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吕城待闸得陈魏二生晤语","p":"","d":"宋代","a":"陈造","c":["吕城望奔牛，道里不作远。", "徙倚不容前，奈此河流浅。", "窘步客怀恶，痴坐仆夫倦。", "班荆得两生，晤语忘旦晚。", "文卷得细披，汤饼亦粗办。", "生须朋从乐，时亦慰连蹇。", "长吟行路难，回首偶耕原。", "卜邻傥君等，老我幸无怨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示学人三十首 其二十二","p":"","d":"明代","a":"释函可","c":["江海本无波，飙风不停吹。我心与境接，日夜纷交驰。", "若了心境幻，彼此不相知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其二","p":"","d":"宋代","a":"蒲宗孟","c":["圣名不敢居，民誉日益美。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送杜方伯入觐 其三","p":"","d":"明代","a":"霍与瑕","c":["暮春三月，东征孔棘。方伯维之，饷馈有绎。四月之夏，柘林为逆。", "薄于城下，民罹其贼。脂民肝骨，远迩躅踯。峨峨大舰，烧焚靡孑。", "方伯图之，毕举群策。以佐元老，驱除荡涤。是底嘉绩，危城以磐石。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戏方仁声四绝句 其三","p":"","d":"宋代","a":"叶梦得","c":["不惜囊钱信手空，荒田却拟望年丰。天公可是怜风月，判遣诗人一例穷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"斋居感兴二十首 其十二","p":"","d":"明代","a":"林光","c":["诸儒喜著述，兀兀研谬讹。至近而神驰，精彩日消磨。", "赋生本有涯，无涯将奈何。元首易丛脞，试听虞廷歌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"白纻歌九首 其一","p":"","d":"南北朝","a":"张率","c":["歌儿流唱声欲清。舞女趁节体自轻。歌舞并妙会人情。", "依弦度曲婉盈盈。扬蛾为态谁目成。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"史丞相生辰 其一","p":"","d":"宋代","a":"喻良能","c":["姓名久已覆金瓯，一品师臣德业优。黼扆尚询黄发旧，衮衣难伴赤松游。", "松筠劲节高三事，桃李浓阴遍九州。萧叶杨门端可继，只今衮衮富公侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"己亥腊月朔自匡庐之九江","p":"","d":"明代","a":"祁顺","c":["彭蠡通南北，开篷见万艘。雪消山翠重，水落石痕高。", "吴楚风烟阔，江湖岁月劳。往来吟思苦，赢得鬓刁骚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨后","p":"","d":"现代","a":"马一浮","c":["三伏炎蒸一雨收，应驱少昊早行秋。", "深山石上看飞瀑，多少鱼龙据下流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四月望再游西湖十首 其一","p":"","d":"宋代","a":"陈造","c":["前时小舫冒氛昏，重到轻桡破曲尘。湖面风烟饱姿态，一番到眼一番新。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"太庙灵芝产于仁宗皇帝英宗皇帝两室前楹芝上有文成王字臣叨陪政府得预荣观谨课成律诗二首 其一","p":"","d":"宋代","a":"张纲","c":["吾皇圣德绍先猷，清庙华芝屡降休。道盛百王神画验，祥开两室化功侔。", "牺尊影照彤云聚，藻棁光连瑞气浮。愿诏乐章歌伟迹，更从来岁荐郊丘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"简陆务观史君编修二首","p":"","d":"宋代","a":"杨万里","c":["闻道云间陆士龙，钓台绝顶啸清风。", "却将半掬催诗雨，洒入山村作岁丰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题刘真君祠","p":"","d":"宋代","a":"洪朋","c":["冠挂谢埃雾，云乘上杳冥。棠阴空五马，榆彩杂繁星。", "圜叶馀神界，华林隐翠屏。锦帏渺经纬，宝舄绝仪形。", "旧井金丹閟，层坛玉露零。千秋想灵气，何许仰天庭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"息虑轩诗","p":"","d":"宋代","a":"饶节","c":["雨暗藤经屋，春深草到门。客来非问字，鹤老不乘轩。", "花气翻诗思，松声撼醉魂。呼儿换香鼎，趺坐竟黄昏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题邓寨周氏小园","p":"","d":"宋代","a":"王之望","c":["径草荒春绿作堆，东风深入小园来。", "可怜几阵嫣香裹，立尽庭前数树梅。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题沈氏酒垆四首 其二","p":"","d":"清代","a":"蒋春霖","c":["玉钗金缕都抛却，烽火仓皇道路閒。自是何郎轻国事，教人愁听念家山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵宋尚书山居十五咏 其七 茶岩","p":"","d":"宋代","a":"方岳","c":["壑底云香不等雷，便携石鼎与俱来。鹁鸠唤得西溪雨，顿得春从齿颊回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"林均州招饮沧浪亭席上口占同席王杨两孝廉余门人东官黄于广","p":"","d":"明代","a":"叶春及","c":["路迷江汉百愁生，亭入沧浪一棹轻。鼓枻偶闻渔父唱，濯缨宁比使君清。", "层崖雨过芙蓉湿，曲岸烟开翡翠明。尘满素衣归未得，石泉空负故山盟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"漫书呈仲谋","p":"","d":"宋代","a":"黄庭坚","c":["漫来从宦著青衫，秣马何尝解辔衔。", "眼见人情如格五，心知外物等朝三。", "经时道上冲风雨，几日樽前得笑谈。", "赖有同僚慰羁旅，不然吾已过江南。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟中杂兴柬韩克和刘自牧王尚文宋广文十八首 其四","p":"","d":"明代","a":"薛瑄","c":["万家城郭通州市，十里帆樯潞水船。清晓登舻望京国，凤凰楼阁五云边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕","p":"","d":"元代","a":"刘诜","c":["疏雨孤灯夜，相看又岁除。江山犹寓客，亲友绝来书。", "新酒初堪酌，长愁未暂疏。艰难吾敢恨，百岁定何如。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再用韵三首贻文举训导 其三","p":"","d":"明代","a":"郑真","c":["皋比掌教本非才，苜蓿盘空几席埃。帝阙仰瞻三殿出，仙山遥望五云开。", "多烦上客公车过，共迓先生聘币来。藻頖生香冠佩集，锦篇新儗柏梁台。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"踏莎行　半梦庐饯新河分韵得燕字","p":"","d":"近代","a":"寇梦碧","c":["月底箫沉，梅边笛换，独将冷拍支残艳。新红翻作殿春花，旧巢犹有衔泥燕。", "饯梦杯深，题香烛短，白头惜别情无限。明朝准拟赋游仙，紫鸿双驾淩云汉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵弟观过黄山","p":"","d":"宋代","a":"陈著","c":["晓雨才收数点轻，江云未放十分晴。舟行曲港难为纤，峰有佳山莫问程。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东轩小室即事五首","p":"","d":"宋代","a":"曾几","c":["卷书坐东轩，有竹甚魁伟。", "清风过其间，戛戛鸣不已。", "写之以素琴，音节淡如水。", "不惜为人弹，临流须洗耳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和许太常道中家园成趣轩韵","p":"","d":"明代","a":"郭登","c":["君家三径几时开，千个长松绕屋栽。", "把钓每从溪上去，题诗还傍竹间来。", "梦阑石枕月相对，花落柴关风自推。", "有约频过寻贺老，莫教空棹酒船回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄蒋攸县砺二首","p":"","d":"宋代","a":"赵蕃","c":["君家三径开来久，不待弦歌始得资。", "傥欲赋归归便得，湘山越岭匪逶迟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟中杂兴 其十四","p":"","d":"明代","a":"王洪","c":["墟里郁相望，田家多荜门。牧豕向大泽，维舟来远村。", "麦苗沙上秀，烟火雨中昏。赖有同袍者，幽怀喜共言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别江陵王少府","p":"","d":"唐代","a":"张籍","c":["迢迢山上路，病客独行迟。况此分手处，当君失意时。", "寒林远路驿，晚烧过荒陂。别后空回首，相逢未有期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"甲午除夜","p":"","d":"元代","a":"元好问","c":["暗中人事忽推迁，坐守寒灰望复燃。", "已恨太官余曲饼，争教汉水入胶船？", "神功圣德三千牍，大定明昌五十年。", "甲子两周今日尽，空将衰泪洒吴天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚泊鸥潭","p":"","d":"明代","a":"韩日缵","c":["偶此泊鸥潭。矶头傍古岩。鸥群閒自戏，潭影净于蓝。", "远渚晴岚润，孤舟夕照衔。机忘相上下，狎尔羽毵毵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿冯北部","p":"","d":"宋代","a":"颜太初","c":["五百年终遘圣朝，相门何日降英髦。", "星杓影射金枢正，月魄光浮碧汉高。", "三世密传张颢印，贰车新得吕虔刀。", "他年善继良弓慕，金字重重有赐袍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪溪仙隐","p":"","d":"宋代","a":"楼钥","c":["君之生兮天之西，望雪山兮名之以雪溪。君之游兮海之湄，隐于雪窦兮杳然何归。", "子从其父兮孙访吾祖，子志不遂兮孙之心良苦。", "嗟嗟，阆中君兮弃家而远游，蹇胡为乎不久留。其遂蝉蜕尘埃而仙耶，其亦肥遁得道不死而隐于四窗之幽耶。", "扪萝以寻于烂平兮既不可见，莽白云之廿里兮欲进兮焉求。", "青棂兮实繁，莎罗兮花稠。鞠侯兮相与群，白鹇兮啸其俦。", "谓为远兮何景物之良是，谓在迩耶将径之何由。", "肖君像兮兹堂，谨奉尝兮良畴。君其来兮庶几其见之，君之不来兮徒相羊以夷犹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答兄平原诗","p":"","d":"魏晋","a":"陆云","c":["悠悠涂可极。", "别促怨会长。", "衔思恋行迈。", "兴言在临觞。", "南津有绝济。", "北渚无河梁。", "神往同逝感。", "形留悲参商。", "衡轨若殊迹。", "牵牛非服箱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"张迪功携诗见过次韵谢之二首","p":"","d":"宋代","a":"陈与义","c":["黄纸红旗意未阑，青衫俱不救饥寒。", "久荒三径未得返，偶有一钱何足看。", "世事岂能磨铁砚，诗盟聊吉歃铜盘。", "不嫌野外时迂盖，政要相从叩两端。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双雁儿","p":"","d":"清代","a":"汪东","c":["淙淙雪水溜阶渠。晓日淡，晚风粗。闭门閒读道家书。", "精中观，摄万珠。", "运行无极亦须臾。仗斗酒，到华胥。置身浑似邃皇初。", "任峥嵘，岁又除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"滇南胜境","p":"","d":"清代","a":"许湜","c":["振顿心神碎，林峦忽霁颜。天开松岭小，家近马蹄间。", "落日低平楚，飞鸦度远山。昨宵风雨客，黯淡宿黔关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋早出太平堤","p":"","d":"明代","a":"卢宁","c":["城外长堤散九皋，西风跨马看鸿毛。玄湖日破浪花出，钟阜烟晞气彩高。", "绿拥双林迷册府，清分三路入秋曹。化深南国无多讼，按辔逍遥拽锦袍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闺怨一百二十首 其一一七","p":"","d":"明代","a":"孙蕡","c":["春铅数日不曾施，贴翠涂黄只半时。为报小环休写月，且教留着澹双眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百二十三首 其七十七","p":"","d":"宋代","a":"释普度","c":["露滴滴，风凄凄。黄花香满路，何独在东篱。高低普应，步步相随。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"至第四铺二首","p":"","d":"宋代","a":"梅尧臣","c":["轻舟已过第四铺，忆著阳关末尾声。", "怊惆杜公行底急，白醪何处得同倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和介溪赏莲","p":"","d":"明代","a":"陆深","c":["雨气自天香冉冉，风光临水碧飔飔。移来玉井仙人掌，开傍金波太液池。", "本为怜芳衙散早，翻因解语酒行迟。新欢旧赏年华里，倚遍阑干有所思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"孟尝君度关图","p":"","d":"宋代","a":"郑思肖","c":["狐白裘边事若难，孟尝门下亦何颜。若无意智翻身去，半夜焉能度此关。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"望江南","p":"","d":"宋代","a":"黄公绍","c":["思晴好，春透海棠枝。刻惜许多过时了，可怜生是我来迟。不见软红时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"贤者之孝二百四十首 其一四八 许孜","p":"","d":"宋代","a":"林同","c":["能感猛鸷类，都无搏噬心。同游至鹿虎，共宿有鸠鹰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄史允叟","p":"","d":"元代","a":"袁桷","c":["故国王孙佩碧兰，春去凉月倚朱阑。", "玉箫曲趁莺声转，金鼎香随蝶梦残。", "碧沚波清堪把钓，黄尘风急倦弹冠。", "外家文采惟君在，笑我冰髭跨晓鞍。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朱明洞景八首 其六 种菊东篱","p":"","d":"明代","a":"卢龙云","c":["自爱篱边菊，餐英待晚芳。盈樽多秫酒，客坐但传觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚望","p":"","d":"元代","a":"周权","c":["帖帖平畴稻未黄，疏烟老树带秋光。山钟敲断前村雨，一两归鸦背夕阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"承田地曹见邀先至西湖保叔寺候任侍御张冬官偶赋","p":"","d":"明代","a":"林光","c":["肩舆轧轧傍湖弦，贪爱春光在客先。山色忽开心里景，湖波摇荡镜中天。", "梅花惯识林和靖，樽酒堪呼李谪仙。一勺山腰泉未试，迫人诗思满云烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"留别吴门诸子二首 其二","p":"","d":"清代","a":"严启煜","c":["背花宁待管弦终，归卧云林半亩宫。世外渔樵有真趣，山间鸡犬尽淳风。", "采松袖染秋岚碧，捣药窗留夜火红。他日皋桥明月里，故人应共念梁鸿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"汉光武庙","p":"","d":"宋代","a":"韩元吉","c":["涿郡渔阳此呼分，用兵诸将总如神。", "白头浪说关中事，邓禹当年已笑人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟中","p":"","d":"宋代","a":"李流谦","c":["帆风不饱橹声迟，正是波平月上时。", "今夜不知何处泊，买鱼枯酒犒舟师。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"建炎己酉十二月五日避乱鸽湖山十绝句 其六","p":"","d":"宋代","a":"王庭圭","c":["洞里花开透碧霄，溪横三绕赤栏桥。他年桥断人迷路，咫尺山源万里遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同坐客赋席牡丹酴醿海棠三首","p":"","d":"宋代","a":"李弥逊","c":["品题芳事有春工，姚魏风流胜浅红。", "莫傍沉香亭北看，只宜卮酒对山翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自和山房十咏 其三","p":"","d":"宋代","a":"李曾伯","c":["坡翁昔爱是山中，我以何人敢比踪。筑室买田居此了，闭门读易保吾终。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄吴少溪宫录七十 其三 寄送林太华民部报命北上","p":"","d":"明代","a":"于慎行","c":["倾盖长安意颇亲，山城重枉驻征轮。两河使节归仙吏，一代家声属世臣。", "路入五云关树晓，赋成双管禁林春。郎曹纵自多文雅，谁许青箱事可陈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"第一百六十七","p":"","d":"宋代","a":"文天祥","c":["阴风千里来，惊浪满吴楚。", "世事两茫茫，飘泊欲谁诉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"落花诗三十首 其七 七虞","p":"","d":"明代","a":"邓云霄","c":["石家别业洛城隅，昔日风光近有无。不见留欢围锦障，但闻如意碎珊瑚。", "香消谷口春泉冷，人堕楼头夜月孤。试过遗基望残景，数株芳树带平芜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵和梁才甫与曾叔夏喜雨","p":"","d":"宋代","a":"王安中","c":["金节经过玉帐开，初筵风雨烛花摧。凤凰池外浓云合，獬豸冠前爽气来。", "已洗郊原秋淡荡，不妨星月夜昭回。拾遗说尹村村到，盛看丰年社酒杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闲居 其五","p":"","d":"宋代","a":"释行海","c":["绕岸奇峰半没烟，满窗凉影竹涓涓。双鸠并睡枯桑上，一鹭闲行白水边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二十二日玉笥梦","p":"","d":"明代","a":"罗伦","c":["关山一只雁，霄汉两三峰。借问门前水，依然万折东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"醉乡","p":"","d":"明代","a":"陈献章","c":["管勾仙家碧酒春，醉乡今日属何人。天高地迥无人到，试就陶潜一问津。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自嘲","p":"","d":"明代","a":"林大春","c":["翠竹迎风舞，山童见客呼。如何清夜月，清兴半分无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"少游荆湘因有是题","p":"","d":"唐代","a":"沈佺期","c":["岘北焚蛟浦，巴东射雉田。岁时宜楚俗，耆旧在襄川。", "忆昨经过处，离今二十年。因君访生死，相识几人全。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏秦始皇兵马俑","p":"","d":"近代","a":"何满子","c":["六合已横扫，何须地下军。干戈区宇息，图匕梦魂惊。", "嗣子鹿迷马，遗尸臭杂腥。徒凭黔首力，奇迹世无伦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题东西二梁山三首","p":"","d":"宋代","a":"杨万里","c":["传道临春昔丽华，不从陈帝入隋家。", "独将亡国千年恨，留下双颦寄岸花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村居 其三","p":"","d":"清代","a":"董兆熊","c":["东冈有田舍，云是隐君门。障日借邻树，避人居远村。", "用悭囊讳涩，汲少井难浑。吾欲从之往，相依长子孙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夫人閤端午帖子 其二","p":"","d":"宋代","a":"胡宿","c":["天家饶物采，华节有光辉。明月裁歌扇，轻霞剪舞衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蝶恋花 其一 次韵少游二乔观书图","p":"","d":"清代","a":"王士禄","c":["倾鬓颓云肩亸玉。髹几光凝，双映修蛾绿。仿佛风光屏外足。", "摊书停却寻春躅。", "炉里双烟青断续。玉砌红帘，不似牵萝屋。公瑾伯符皆不俗。", "知无一事萦心曲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过济宁怀李白","p":"","d":"明代","a":"谢廷柱","c":["清风楼上客，独忆谪仙人。海岳元无恙，文章自有神。", "倾樽一吊古，搔首几迷津。忽动乘槎兴，飘然遍八垠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登湖光亭","p":"","d":"宋代","a":"韩维","c":["雪尽尘消径露沙，公家池馆似山家。", "翠痕满地初生草，红气通林夫放花。", "匝岸平波清照雁，压城危榭斗回鸦。", "自惭白首犹圭组，此地年年常物华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"古寺老松","p":"","d":"唐代","a":"齐己","c":["百岁禅师说，先师指此松。小年行道绕，早见偃枝重。", "月槛移孤影，秋亭卓一峰。终当因夜电，拏攫从云龙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春雪早朝和沈编校","p":"","d":"宋代","a":"刘攽","c":["晓寒初怪客衣重，隐约钟声长乐宫。出户万家横雪里，止车双阙秀云中。", "退朝禁柳迎人绿，寓直庭花向日红。纵使著书嘲尚白，会应华发兆非熊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"无事自遣","p":"","d":"近代","a":"宋辅仁","c":["独坐藤阴院，无聊自检书。瓮头新酒熟，问有客来无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"独漉篇","p":"","d":"明代","a":"赵南星","c":["独漉独漉，波腾鱼伏。", "鱼伏欲起，波腾不已。", "翩翩孤鸿，徘徊云汉。", "我欲折芦，为子周患。", "远望长林，林木有枝。", "客子无言，中心则悲。", "干将绣涩，时时自鸣。", "宵练在掌，过者不惊。", "猛虎入邑，其粮以人。", "劲弩櫜藏，请之鬼神。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂一百五十首 其一四八","p":"","d":"宋代","a":"释心月","c":["溪山送别出门日，云水相迎得路时。七佛轨仪持钵去，满船载得月明归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"发新安后途中寄卢中丞二首","p":"","d":"唐代","a":"赵嘏","c":["楼上风流庾使君，笙歌曾醉此中闻。", "目前已是陵阳路，回首丛山满眼云。", "晚树萧萧促织愁，风帘似水满床秋。", "千山不碍笙歌月，谁伴羊公上夜楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"归自东山","p":"","d":"清代","a":"缪公恩","c":["驱车入平陆，人在万山西。野旷飘风急，云昏落日低。", "孤烟横远坞，古渡锁寒溪。遥指高城近，疏镫树影迷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"亲友冯仪之运干挽章三首 其二","p":"","d":"宋代","a":"曹彦约","c":["有学关时用，无心与物驰。已称黄发老，犹似綵衣时。", "世道空机阱，襟期自坦夷。只今风月夜，犹足想清规。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵酬吴天彝太守惠笋","p":"","d":"明代","a":"谢迁","c":["急电催雷起蛰龙，龙孙无数湿云笼。渭川已在封疆外，嶰谷须归律吕中。", "玉版拟参开石路，锦绷初解散林风。分甘多谢清贫守，满荐春盘压晚菘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"碧落秋风吹玉树","p":"蝶恋花","d":"宋代","a":"晏几道","c":["碧落秋风吹玉树，", "翠节红旌，晚过银河路。", "休笑星机停弄杼，凤帏已在云深处。", "楼上金针穿绣缕，", "谁管天边，隔岁分飞苦。", "试等夜阑寻别绪，泪痕千点罗衣露。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"玉楼春 其二 八月宿姜真源宪使后院夜饮同小农汝旦作","p":"","d":"清代","a":"毛奇龄","c":["红蕖小幕开深槛。微雨乍收凉漏浅。酒淹垆火带霜吹，风搅浊油和烟剪。", "银船交泛明河转，玉树当轩共婉娈。夜深空忆广陵涛，水绕曲江知近远。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送蜀郡李掾","p":"","d":"唐代","a":"岑参","c":["饮酒俱未醉，一言聊赠君。功曹善为政，明主还应闻。", "夜宿剑门月，朝行巴水云。江城菊花发，满道香氛氲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"听罗道士琴 其二","p":"","d":"宋代","a":"文天祥","c":["吾闻泗滨磬，暗含角与徵。又闻天乐泉，净洗筝笛耳。", "如何碧一泓，乃此并二美。蓝田沧海意，请问玉溪子。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"潮春攻城解围志感 其三","p":"","d":"清代","a":"赖时辉","c":["义勇堪嘉锡县名，自前众志已成城。连攻不落惟斯邑，屡困能通赖众擎。", "更有褒忠乡媲美，尽多赏恤泽荣膺。重重浩劫疲奔命，谱入新诗老泪横。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"草阁","p":"","d":"清代","a":"申颋","c":["草阁著书罢，长林秋色闲。尘喧不到处，庭户若空山。", "片雨随风过，残云带鸟还。萧然无所事，双手纳怀闲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题齐安城楼","p":"","d":"唐代","a":"杜牧","c":["呜轧江楼角一声，微阳潋潋落寒汀。", "不用凭栏苦回首，故乡七十五长亭。"],"tags":["思乡"],"z":"","y":"","s":"","k":"诗"},
  {"t":"和梅花百咏诗 其二十一 别梅","p":"","d":"明代","a":"王夫之","c":["离筵及早酌屠苏，留看镫宵待得无。知有前期霜信后，小窗人奈雪侵须。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其一","p":"","d":"宋代","a":"范百禄","c":["携月入上清，一览无馀山。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题春江送别图","p":"","d":"元代","a":"郭钰","c":["君上孤舟妾上楼，望中烟雨意中愁。江波若会离情苦，一夜东风水倒流。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"崧高诗为九江赵使君寿","p":"","d":"宋代","a":"杨冠卿","c":["柔惠且直，小心翼翼。", "王亲命之，南国是式。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"铁珊瑚","p":"","d":"清代","a":"吴德功","c":["铁树生苍古，槎枒数尺高。枝柯盘柱砥，骨干类珊瑚。", "屈曲叉文笔，崚嶒击唾壶。陶镕逢世用，沧海网遗珠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答杨式公","p":"","d":"明代","a":"成鹫","c":["红尘紫陌偶相期，蹑屐登龙快所思。山径有云归路晚，市门斜日下楼迟。", "漫劳轩盖遥相问，暂寄茅堂只在兹。他日幽栖还有计，千峰平处一峰奇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"黄去非先生以四川县令内升比部主事进京相晤话旧感成长句","p":"","d":"清代","a":"敦敏","c":["百里何能滞祖鞭，徵书群识汝南贤。剑关远自七千里，燕市重逢十四年。", "清级曹纲新紫绶，遗编蠹简旧青毡。虎门绛帐遥回首，深愧传经负郑玄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和施通判以诗惠茶","p":"","d":"宋代","a":"王庭圭","c":["綵笔题誇北苑春，南来草木始称珍。江湖风味极不浅，翰墨篇章老更新。", "落日清吟招恶客，此时佳境属闲人。惭无好语酬高咏，东望云山意莫陈。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"卓牌儿 夏日咏闺人斗叶子","p":"","d":"清代","a":"陈维崧","c":["遥窥两重门，群掩映、凝烟碧幌。卐字槅底，凭肩语笑，冰纹廊后，亸鬟沈想。", "风流小南唐，金叶子、描鸾小样。斑几滑笏玲珑，蜡笺纤脆轻盈，打来偏响。", "七红四赏。更花戳、京城新创。兰闺似掌。俨楚汉情状。", "赢得帘西红鹦鹉，也隔屏山注望。私讲。笑粉装刘项。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天（番禺齐安郡王席上赠故人）","p":"","d":"宋代","a":"向子諲","c":["台埭初逢两妙年。瑶林玉树倚风前。疏梅影里春同醉，红芰香中月一船。", "长怅恨，短因缘。空余胡蝶梦相连。谁知瘴雨蛮烟地，重上襄王玳瑁筵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"新湾","p":"","d":"宋代","a":"刘子翚","c":["苒苒寒生水面烟，吴歌唱罢月微偏。", "停桡又向湾前宿，一夜西风浪打船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读备遗录","p":"","d":"明代","a":"郑善夫","c":["神尧无信史，谁纪革除年。龙虎风云上，山河涕泪边。", "夷齐偏守死，王魏总知权。三复春秋传，微词今不传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"都梁八首 其七","p":"","d":"宋代","a":"陈造","c":["向来经世蕴，每作负山驰。鬓发不留黑，京尘惭旧缁。", "生涯黄卷在，心事白鸥知。回首林泉癖，穷吾不为诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵尧明贡院诗","p":"","d":"宋代","a":"吕本中","c":["忍穷不能归，强饭亦良计。东风频报春，草木可次第。", "厌为龙头缩，宁作龟尾曳。从来翰墨场，即有闻见滞。", "譬如已耕田，更欲深种艺。或蒙卤莽报，未肯即卖弃。", "不闻太仓粟，亦校毫发细。王卿固倦游，秽浊有蝉蜕。", "声名动时人，我实托末契。泥涂倒屐齿，尘埃涴衣裌。", "要为无用用，乃作不事事。下马旧战场，午日在庭戺。", "向来槁木枝，忽有红绿缀。来非偶然住，去亦无所诣。", "聚蚊著瓯中，得听此鹤唳。窗前有馀馥，胜韵入松桂。", "扁舟下淮南，闾里思少憩。熟观昔所历，请与居士戏。", "江湖要同归，不假木兰枻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高宗皇帝挽词五首","p":"","d":"宋代","a":"宋孝宗","c":["草昧千龄旦，飚回九县尘。", "皇天开我宋，丹极下真人。", "指顾山河定，欢呼历数新。", "断鳌重立极，更与物为春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长安杂诗十首 其七","p":"","d":"元代","a":"王祎","c":["群经载圣道，昭揭如日星。秦火一何烈，烧燔灭其形。", "汉儒事掇拾，区区补残零。虽然有遗阙，其功亦已宏。", "唐世尚文学，君臣益留情。琬琰刻文字，后先十三经。", "谓兹金石坚，不与竹帛并。自从东都后，此刻最为精。", "罗列黉舍内，奎壁映晶莹。我言金与石，有时亦销崩。", "有形必有弊，斯理讵难徵。安知圣人道，所托非所凭。", "天地其终始，猗欤罔能名。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"元会二首","p":"","d":"明代","a":"严嵩","c":["正元钟鼓动长安，率土朝天若会湍。瑞气先浮百子殿，晴光欲上五辛盘。", "梅风应律韶年丽，蔀屋迎阳圣泽宽。先向御帘陈贺表，缪司邦礼备春官。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"德孺五丈和之字诗韵难而愈工辄复和成可发一","p":"","d":"宋代","a":"黄庭坚","c":["且然聊尔耳，得也自知之。", "独笑真成梦，狂歌或似诗。", "照滩禽郭索，烧野得伊尼。", "早晚来同醉，僧窗卧虎皮。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"醉吟","p":"","d":"宋代","a":"戴复古","c":["一狂兼一懒，穷到白头年。", "客路偏耽酒，诗囊不贮钱。", "吟边忘世故，醉里乐吾天。", "不答诸公问，何如孟浩然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙 天安门诗抄","p":"","d":"当代","a":"佚名","c":["哭别亲人泪未消，山精出洞变人妖，", "装腔作势调门高。", "有意重研擒鬼法，无心轻信狗皮膏，", "留神拭泪认花招。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"史记引逸诗","p":"","d":"先秦","a":"佚名","c":["得人者兴。", "失人者崩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"后秋兴八首中秋十九日，暂回村庄而作 其八","p":"","d":"明代","a":"钱谦益","c":["孤篷信宿且逶迤，白水柴门返故陂。丹桂月舒新结子，苍梧云护旧封枝。", "歌阑长夜秋方盛，语到胥闾日每移。小饮折花重剪烛，参旗长并酒旗垂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谨次功成短项翁佳篇之韵","p":"","d":"宋代","a":"钟孝国","c":["君不见中山毛颖生，纂录百氏编群经。", "又不见革华祖都尉，殿上承恩举足耳。", "二物名誉由韩公，无乃衮褒俱中理。", "君家酒罍依图书，短项独喜觞吾儒。", "我加翁名乃率尔，诸公过听欢有馀。", "翁名称意仰来前，再拜不愿封酒泉。", "倾怀解贾吟笔勇，注想只愁客杯乾。", "主人冥心通与穷，从渠自引琉璃钟。", "醉中琢句千古废，醒后逢人四海空。", "林间日日吹春风，孛窣愿卜重相逢。", "长江小艇新雨后，一杯相属会稽翁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"琉球难夷遭风到境加意抚恤照例护送诗以纪事","p":"","d":"清代","a":"董正官","c":["得生众命赖渔船，恭顺中山天亦怜。破艇底能漂海上，大龟屿恰属兰边。", "馆餐仰体怀柔远，额手欣看顶礼虔。此与琉球深夙契，前年护送又今年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题三山天庆观 其二","p":"","d":"宋代","a":"白玉蟾","c":["紫琼飞清都，翠云护绛阙。不见有星辰，俯视但日月。", "下世二千年，不敢向人说。吾已成金丹，留下飞仙诀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"调云岑","p":"","d":"宋代","a":"郑清之","c":["佛法方当恶剧时，偃溪笑裹袖钳锤。", "不教管领千云衲，打彻头关更问谁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪纱二首 其一 答子退","p":"","d":"近代","a":"林散之","c":["退墨零笺笔不停，寒窗辛苦十年灯，此中消息得天能。", "用色由来如用墨，生枯燥湿验虚灵，炼成炉火自纯青。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次临封八景韵 其七 景星夜月","p":"","d":"明代","a":"蒙尧佐","c":["星名古寺遗踪远，月挂空山分外明。竹影却疑蟠影动，松声时带磬声清。", "光分郊野昏如画，照彻浅崖险亦平。谁使传灯来此处，清辉今已彻专城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春词","p":"","d":"唐代","a":"李建勋","c":["日高闲步下堂阶，细草春莎没绣鞋。", "折得玫瑰花一朵，凭君簪向凤凰钗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别秀亭五首 其一","p":"","d":"宋代","a":"方回","c":["秀亭亭上果何似，两水万山图画开。霜入川原疏草木，烟销城市出楼台。", "半空鹭点客愁破，何许笛吹诗句来。异日梦魂应历历，醉僧同此藉莓苔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鲁桥热","p":"","d":"明代","a":"陆深","c":["赤日行空正当午，老夫畏热如畏虎。计程归路三千七，值我行年六十五。", "昨过任城旧酒楼，山川信美非吾土。仲宣太白俱仙才，安得并载黄龙浦。", "此日池塘杨柳风，此时庭院芭蕉雨。牙缃架插馀万卷，衮钺心传破千古。", "满座时看羽扇摇，半酣起拂吴钩舞。已约清风成故人，更须霖雨歌明主。", "回瞻殿阁忆微凉，却向园庐依茂树。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送蔡季良","p":"","d":"元代","a":"曹伯启","c":["盛世官规量材职，逢掖仍须肆刀笔。猥予南北阅人多，彼此技能相得失。", "江东复一季良出，姓字相闻不相识。同事同星几研亲，得觇干局无俦匹。", "简书衮衮笑谈了，政事优优儒道饰。忽惊奏最觐天庭，万里秋风动颜色。", "英雄不下儿女泪，著脚云衢先努力。除书消息待春开，何处豺狼当屏迹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游墺门宿普济禅院赠云胜师","p":"","d":"明代","a":"成鹫","c":["珠林遥隔水云村，百里寻僧日欲昏。行逐鲛人趁番市，渐闻鴃舌杂华言。", "山钟近接三巴寺，海气晴分十字门。到处不妨吾道在，岛夷今识法王尊。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史一百三十首 其一一九 沈光文","p":"","d":"近代","a":"连横","c":["扁舟东海去，文献启台湾。诗礼传荒服，番黎拜杏坛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"慈圣光献皇后挽辞七首 其四","p":"","d":"宋代","a":"苏颂","c":["越从景祐至元丰，俪极坤仪四纪中。复辟先朝尊启母，助勤熙旦广尧聪。", "深居高拱收渊默，盛德成功绝比隆。太史方修长信注，续诗应首二南风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵高子勉十首","p":"","d":"宋代","a":"黄庭坚","c":["沙上步微暖，思君剩欲招。", "蒌蒿穿雪动，杨柳索春饶。", "枉驾时逢出，新诗若见撩。", "樽前远湖树，来饮莫辞遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丹元子步天歌 其五 北方七宿","p":"","d":"唐代","a":"王希明","c":["危，三星不直旧先知。危上五黑号人星，人畔三五杵臼形。", "人上七乌号车府，府上天钩九黄晶。钩上五鸦字造父，危下四星号坟墓。", "墓下四星斜虚梁，十个天钱梁下黄。墓傍两星能盖屋，身著黑衣危下宿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祝英台近","p":"","d":"宋代","a":"葛长庚","c":["月如酥，天似玉，长啸弄孤影。十二楼台，昨梦暗寻省。自怜露满衣襟，风吹毛发，浑无寐、寒宵漏永。", "捧香鼎。翻起一片龙涎，梅花对人冷。庭户冰清，何处鹤声警。少时烛暗梧窗，烟生苔砌，晓钟动。忽然心醒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送进士陈峣往睦州谒冯郎中","p":"","d":"唐代","a":"章孝标","c":["孤帆几日程，投刺水边城。倚棹逢春老，登筵见月生。", "饮酣杯有浪，棋散漏无声。太守怜才者，从容礼不轻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凤凰山","p":"","d":"宋代","a":"温革","c":["惯作山林客，聊游戏剧场。", "栗花收作烛，柏子采为香。", "且放高情适，都无俗事妨。", "人间正扰扰，只得叩空王。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙巳邵武建宁夜坐书呈诸公","p":"","d":"宋代","a":"陈普","c":["敬身天不宽曾子，白眼人当杀嗣宗。", "林下脱巾仍露脚，青云白石肯相容。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渊明祠","p":"","d":"明代","a":"宋濂","c":["官航晚泊浔阳郭，把酒长怀靖节贤。", "折腰竟辞彭泽米，攒眉宁种远公莲。", "归来松菊开三径，老去柴桑受一廛。", "晋代衣冠谁避世，刘家社稷自书年。", "虽云富贵非吾愿，已有清高独尔伟。", "千载令人吊遗迹，好山青立县门前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江门夜泊","p":"","d":"明代","a":"邱云霄","c":["城抱江流急，沙回浪势安。烟云归树暝，风雪酿梅寒。", "客梦随更转，溪声入夜残。渔翁相傍宿，应笑欲弹冠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夫人阁四首","p":"春贴子词","d":"宋代","a":"司马光","c":["圣主终朝勤万机，燕居专事养希夷。", "千门永书春岑寂，不用车前插竹枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬朱适园访见诗","p":"","d":"宋代","a":"潘玙","c":["曾同山友过江湄，何处清游晚未归。", "沽酒□羊来好语，开笼放鹤在何时。", "云方卷叶收春雨，柳未吹花点客衣。", "京洛相逢宜少驻，东风杖屦好追随。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"冬至斋宫二首 其一","p":"","d":"清代","a":"胤禛","c":["晨曦炯炯洁斋宫，一缕炉烟散绮栊。暖气潜回葭琯律，早梅先绽玉阶风。", "中孚默契天人理，来复明彰造化功。漫道书云成故事，精禋惟藉寸心通。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"同元复初饮许仲文别墅","p":"","d":"元代","a":"张养浩","c":["晓日楼台海市仙，春风歌吹酒家天。五云分彩来琼岛，两鹤联飞下玉田。", "流水故将尘隔断，好花都被雨开全。人生佳处无何国，钟鼎山林恐未然。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清明","p":"","d":"清代","a":"黄文琛","c":["淡淡湖风弄雨丝，纸灰飞上绿杨枝。三年不过归元寺，肠断清明上冢时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中呈石末公","p":"","d":"明代","a":"刘基","c":["去年三冬暖不雨，今年孟春寒有余。", "大云垂垂压宇宙，密雪兖兖飘庭除。", "安排白水与泛舸，酝酿青泥容没车。", "辛苦陌头杨柳树，含颦等待大阳舒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"连日祷雨犹未应也数语漫述皇恐之意呈簿尉","p":"","d":"宋代","a":"虞俦","c":["小儿曼倩儘狂奸，试掉雷车与破悭。", "慰我农民须早计，怜渠岁事颇相关。", "斋盂并日浑忘味，诗债如山只欠还。", "谢令冥顽推不去世，毫丝无补亦胡颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得时人不识予心乐","p":"","d":"清代","a":"玄烨","c":["恩波遍布首邦畿，爱此佳时绿尚微。血耗养衰心益壮，神烦物扰体无违。", "暮年筋骨犹能强，半世忧劳幸免非。老惯豫游山水处，傍人那得识天机。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南归杂诗 其六 黄浦江","p":"","d":"近代","a":"孙玄常","c":["黄浦今犹昔，朝朝送远人。淩波人不见，波上岂留痕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"村居即事","p":"","d":"宋代","a":"刘雪崖","c":["数声鸡犬自相闻，借得茅庐住水濆。", "梅欲黄时常是雨，稻才青处便如云。", "忧时每欢朝廷远，学稼方知畎亩勤。", "若使徵书到岩谷，北山又恐动移文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"风竹","p":"","d":"明代","a":"唐璧","c":["琅玕亭亭耸高节，飒遝凉飙舞苍雪。未从天上制箫韶，且向人间洗炎热。", "千崖万壑寒飕飕，五月六月疑清秋。凤鸾欲下栖不稳，飘然飞上青云头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋得山水图长歌赠潘太守瑞徵","p":"","d":"明代","a":"谢榛","c":["华岳上逼层霄，可窥星斗之真迹。黄河来自西极，长送昆崙之正脉。", "绮霞彩虹灿一色，枫林岂让柿叶赤。光映石岩好登陟，眼中胜景谁尽得。", "薄暮翠岚藏秀月又黑，姑射仙子夜游信能识。天与元精豁胸臆，后园独种蟠桃核。", "仙果熟时未敢食，欲献圣皇咀味跻寿域。汾水朝宗流不息，上方龙剑到手除荆棘。", "更刬长安路平通，万国直臣共佐唐虞德。渔樵各生计，官吏不虚职，澶州正对燕京北。", "欲命良工写此图，高挂不出乎半间之壁。主人坐赏最珍惜，神游中宵乘彼苍凉片月白。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题豫章宋德父游湘诗卷","p":"","d":"宋代","a":"乐雷发","c":["醉呼仙叟共浮湘，稛载风烟满锦囊，", "名似浦云山雨起，诗连沅芷沣兰香。", "好吟秋月招元结，莫赋朝云恼楚襄。", "吴巨老仙今寂寞，行人还解识珩璜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山中即事","p":"","d":"明代","a":"薛始亨","c":["石径无泥滓，雨过一渠清。返照摇庭宇，寒烟起槛楹。", "废书人宴坐，得食鹤徐行。借问经秋事，萧萧竹籁鸣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"众鸟","p":"","d":"宋代","a":"王令","c":["鸦鸦枝上鸣，欲下飞复屡。", "忽投群辈先，以我弃肉去。", "群鸟起争攫，既失反亲慕。", "饿鸱盘且下，欲夺进复惧。", "群鹊何轩轩，聚噪如骂怒。", "鸠鸽恨不逮，回旋自号呼。", "庭雀审细微，知非已能预。", "跳梁暮堂下，不舍稗粒顾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"王季海求父宣义挽词二首 其二","p":"","d":"宋代","a":"苏籀","c":["里仁巾几寂，遗懿满瞻听。济美圭璋质，流芳琬琰铭。", "纸灰霏似雪，巷泣洒将冰。念念存伽释，超超拔九冥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"后天易吟三十首","p":"","d":"宋代","a":"方回","c":["始屯终未济，世故信多艰。", "维坎刚中吉，周旋险难间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送大行李浔江使齐归省 其五","p":"","d":"明代","a":"黄廷用","c":["三月青门柳色新，西郊相送转情亲。知君使节经过地，楚水吴山俱是春。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再用韵题翠壁","p":"","d":"宋代","a":"朱熹","c":["孤亭一目尽天涯，俯瞰烟村八九家。翠壁何年悬布水，绿阴经雨堕危花。", "杖藜徙倚凝春望，觅句淹留到晚衙。珍重诗翁莫相恼，枯肠搅断鬓丝华。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"客中夜坐","p":"","d":"明代","a":"袁凯","c":["落叶萧萧淮水长，故园归路更微茫。", "一声新雁三更雨，何处行人不断肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题卢五旧居","p":"","d":"唐代","a":"李颀","c":["物在人亡无见期，闲庭系马不胜悲。窗前绿竹生空地，", "门外青山如旧时。怅望秋天鸣坠叶，巑岏枯柳宿寒鸱。", "忆君泪落东流水，岁岁花开知为谁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"常宁寺","p":"","d":"清代","a":"弘历","c":["兰若静朝晖，苔侵碑篆古。泠泠水到阶，落落松当户。", "龙鳞俨欲张，虬枝自撑拄。谯邑多古迹，爱此琳宫宇。", "依稀梵呗声，彷佛天花雨。意香参即离，静室坐久许。", "适然获常宁，顿忘安心所。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日壁墩和杜牧之韵 其一","p":"","d":"明代","a":"贺一弘","c":["近野高林鸟倦飞，远村烟火隔川微。随风霜叶飘还堕，映水岩云静自归。", "浊酒登台怜子美，澄江如练忆玄晖。何人早出樊笼外，千仞冈头独振衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登九成台","p":"","d":"明代","a":"乌斯道","c":["重华不见独登台，台倚孤城日月开。似听箫韶千载上，虚疑凤鸟九霄来。", "乱山北起迷烟树，双涧南流浸绿苔。回首苍梧天咫尺，南巡曾带跸尘回。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙十首 其七 成都和友人","p":"","d":"近代","a":"唐圭璋","c":["消尽芸香写尽词。日长人懒似游丝。一襟幽怨只天知。", "和寡不思温旧曲，寒深谁复问添业。斩来病骨亦支离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山中漫题","p":"","d":"明代","a":"蓝智","c":["读书期有用，闭户耻无能。", "落叶空山雨，疏钟独夜灯。", "人称樗里子，住近石门僧。", "静坐观诗妙，须参最上乘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"五色鹦鹉黄鹦鹉并是圣母所驯各赋 其一","p":"","d":"明代","a":"徐渭","c":["白燕往时呈翰苑，锦鹦今日贡宸居。万年枝上栖偏丽，百鸟图中态未如。", "豢养固知天意在，语言长得圣颜舒。何因五色鲜成染，自是娲皇炼石馀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"席上题黄莺","p":"","d":"明代","a":"李江","c":["满眼柔香嫩绿时，东风和雨柳丝丝。一梭便是经纶术，半舌还应律吕奇。", "振翅出于幽谷处，着身飞上打头枝。平生不爱多言语，一叫春风天下知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赋萧爽檐蔔戏岩叟","p":"","d":"宋代","a":"陈文蔚","c":["且喜花时雨不妨，凭阑闲与细平间。", "一池交映月添白，六出同妍雪逊香。", "素有书痴缘病懒，不知诗兴为渠忙。", "道人雅好惟清供，却恐花神索酒觞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 病中作","p":"","d":"清代","a":"奭良","c":["荆棘余生，忧来百端，病亦戏予。忆髫年羸弱，时亲药裹，名场毷氉，空逐公车。", "门荫除官，牵丝黄绶，窃禄东都十载余。因风便，便频登启事，渐即康衢。", "乘边竞重储胥。愧曲突徙薪计尚疏。笑鸥波浩荡，几同传舍，蠹鱼纠结，又校官书。", "少也多愁，老而善病，七十光阴过隙驹。酸甜味，倘逢人巧算，细与乘除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"前汉书十七首 其十二 梅福","p":"","d":"明代","a":"郑学醇","c":["为官岂择南州尉，轺传空劳疏屡陈。天路冥冥鸿鹄远，不忍长作市门人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有网友名青藤葫芦者其人诙谐喜谈禅以诗调之","p":"","d":"当代","a":"李梦唐","c":["细牵飞蔓粗缠藤，点染青皮随意风。大道说来句句小，文章都在两圆中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"诗一首","p":"","d":"宋代","a":"本之","c":["一篙春水滑无声，一叶轻舟过短亭。", "飞蔼晚楼迷紫翠，夕阳孤塔认丹青。", "怀人远折三花树，何日相携双玉瓶。", "欲唤渔郎问风色，凫鹥飞处酒初醒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沙湖道中","p":"","d":"元代","a":"许有壬","c":["城居如坐井，出郭始知春。草色才翻烧，禽声便可人。", "远山来逦迤，羸马去逡巡。唤醒三年梦，东华足软尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双溪","p":"","d":"宋代","a":"范成大","c":["冷风骚骚木叶低，洞渊阻深生怪奇。", "碧琳双涧黑无底，中有玉龙相对飞。", "雷轰雪卷入林樾，化为一龙潭底没。", "摩尼斗罢四山空，时有宝光岩下发。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵僧自文见赠四首","p":"","d":"宋代","a":"方回","c":["莫诧横磨剑，宁为没字碑。", "问花惊兔麦，赋药护羊蓍。", "今我都无事，非公不作诗。", "夜窗各坚坐，两地月明知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"楞枷山房二绝","p":"","d":"宋代","a":"洪咨夔","c":["风标劲似聂政姊，笔力健如曹大家。", "此手始能为此竹，对渠枯森老槎牙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"述愤一十七首弘治乙丑年四月作是时坐劾寿宁侯逮诏狱 其十","p":"","d":"明代","a":"李梦阳","c":["青青庙中槐，交交一双禽。为巢育其儿，结构良苦辛。", "一朝惊弹罗，移栖向高林。我行适见之，叹息空弥襟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"祀五帝于明堂乐歌十一首 其二 高明乐","p":"","d":"隋代","a":"佚名","c":["祖德光，国图昌。祗上帝，礼四方。辟紫宫，动华阙。龙虎奋，风云发。", "飞朱雀，从玄武。携日月，带雷雨。耀宇内，溢区中。眷帝道，感皇风。", "帝道康，皇风扇。粢盛列，椒醑荐。神且宁，会五精。归福禄，幸闾亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丁稚璜宫保丈节署燕集谈次及山陕近事感赋 其一","p":"","d":"清代","a":"张百熙","c":["觥觥宫保秉壮猷，森列兵卫拥八驺。开轩坐我为我语，鲁酒不解苍生忧。", "去年山东多难民，今年山西人食人。安得输粮太原道，五百万人同一饱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"草书歌","p":"","d":"清代","a":"铁保","c":["苍颉不识篆，虫鸟开天荒。史籀不识楷，古法遗钟王。", "圣人作书祖造物，天地不得留微茫。草书有名理，盛自汉与唐。", "杜度埒崔瑗，狂素阶颠张。心法授受纵奇变，牢笼百态惊愚盲。", "譬如彼苍铸万类，物具一体无相妨。飞潜动植各有势，短长肥瘦谁能量。", "又如将军坐帷幄，运筹百万网在纲。韩信兵多多益善，指挥方位争趋跄。", "方其执笔时，意静神飞扬。洪炉火激迸列缺，晶盘冰滑流珠芒。", "苍鹰盘云缩爪甲，奇石攫壁春硠硠。阴阳姤接作向背，子母孕化交纵横。", "枯槎百围卧瀚海，女萝千丈萦扶桑。忽然墨冷笔华涩，陡接渤澥波澜狂。", "书成不快意，大叫周回廊。举头天尺五，云物相低昂。", "欲碾太山为研石，欲抉东海为墨庄。凌铄大块写生态，睥睨云汉摹天章。", "二十八宿走且僵，帝女大笑挥霞觞。丈夫师古但师意，安能描头画脚忍与朽骨争媸嫱。", "我歌草书歌未央，飘风骤雨来虚堂。依稀不晓神灵意，莫向蛟龙攫处藏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谒二祖","p":"","d":"明代","a":"孙继皋","c":["古殿依晴嶂，慈云对夕禅。衲从初祖授，灯自上方悬。", "大法还谁悟，真空不可传。惟馀洞中雪，寂历洒诸天。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠淳于公归养","p":"","d":"宋代","a":"朱台符","c":["通籍悬车不待车，彩衣归去奉晨昏。", "倚门且慰慈亲望，恋阙空衔圣主恩。", "天上芝泥新诰敕，海边芜没旧田园。", "会须引退追高躅，宦路悠悠岂足论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"立春晓起","p":"","d":"清代","a":"姚燮","c":["桑曦照帏室，尘薄散宿昏。引杯试春酌，盎然得微醺。", "众荄藐含绿，生理足内存。妷霭在空阔，触处寓欢欣。", "化尔沈愤气，还诸浩荡仁。行歌满衢市，谁非羲皇民？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂九十三首 其四十三","p":"","d":"宋代","a":"释梵琮","c":["求道如求雨，乾枯日夜愁。忽然风雨至，万壑尽争流。", "直得天下万物沾润，三井龙王出头。云南如劈箭，云北似倾湫。", "激石怒雷吼，翻空雪浪浮。忽然风雨息，平地一时休。", "衲僧家，骑个水牯牛。多快活，百无忧。健即行，困即歇。", "布袋头，亲解结。钉打钉，铁打铁。寒道寒，热道热。此是诸佛心宗，亦名单提妙诀。", "七峰峰顶滑如苔，寒山拾得相拖拽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词","p":"","d":"宋代","a":"张公庠","c":["萱草初长花未开，共知青帝领春回。", "珠帘卷上琼钩稳，不碍薰风满殿来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"大本堂（二首）","p":"","d":"明代","a":"魏观","c":["六斋帝子联龙衮，三岛神仙列雁行。", "绣毂青鸾金羽盖，锦鞯白马紫游缰。", "御沟细柳云生暖，禁御飞花雨送凉。", "郑国书闻能一一，玉炉清昼为分香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偶题云边","p":"","d":"宋代","a":"刘宰","c":["桃花山下水流长，花不长开水自香。", "此地正须招隐上，山庵聊复对崇罔。", "屏帏缭绕竹千个，旌纛森岩柏两行。", "士会不生今已矣，不妨閒处且徜徉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"伏蒙知县县尉二寮友以夏旱得雨赓石徂徕喜雨韵见贶不可虚辱复嗣其韵书谢仍命儿曹同赋","p":"","d":"宋代","a":"王之道","c":["绿槐阴外听蝉吟，节过分龙夏已深。千里亢阳忧岁旱，一时甘雨快人心。", "养禾不害连朝曀，沃暑应容数日霖。多谢同寮怜老拙，双南佳句竞铿金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题清远峡飞来寺","p":"","d":"明代","a":"汪广洋","c":["峡里金银佛寺开，老僧传是昔飞来。菩提子落云间石，薝卜香飘月下台。", "江涌灵源通海峤，山横古翠接蓬莱。愿询往事观碑刻，閒向松阴扫绿苔。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻叶初秀才东归","p":"","d":"宋代","a":"林逋","c":["高鸿多北向，极目雨余天。", "春满吴山树，人登汴水船。", "吟生千里月，醉尽一囊钱。", "肯便怀乡邑，时清复少年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书灵隐上人册","p":"","d":"明代","a":"李之世","c":["秋叶与秋云，的的当阶坠。家僮误扫叶，惊散秋云去。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春夜过银锭桥在禁城外北海子","p":"","d":"明代","a":"胡直","c":["都城佳丽地，春夜喜重经。巨浸通银汉，长桥挂碧汀。", "云移千树月，冰坼半湖星。缥缈闻仙吹，祈坛近苑亭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"玉麟堂会诸司观牡丹酴醾三绝 其一","p":"","d":"宋代","a":"范成大","c":["东风微峭护馀春，红紫香中酒自温。不用忙催银烛上，酴醾如雪照黄昏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻郭怡有诗未及见因赋此以寄恨","p":"","d":"元代","a":"郭钰","c":["一襟老泪点苍苔，谁信愁肠日九回。豪杰虚名多自误，弟兄急难竟谁来。", "桥分溪路桃花落，门闭山房燕语哀。祸福情知相倚伏，浮云蔽日几时开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东轩","p":"","d":"元代","a":"吴讷","c":["孤客凭危正惘然，江南春尽落花天。海门黑送千艘雨，城郭青炊万灶烟。", "烧药金炉犹伏火，射潮铁箭久离弦。伍员白马今何在？几处荒台野鹿眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雨中桃花","p":"","d":"明代","a":"李昌祺","c":["霢霂过芳园，枝枝积泪痕。色怜开处淡，香爱坠时闻。", "采倦蜂须湿，衔多鸟咮芬。东风解人意，吹片到衡门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菜根吟","p":"","d":"当代","a":"陈振家","c":["层云萦郁隐青林，听彼好禽鸣木阴。松骨咬崖如铁铸，藤筋陷壁绕峰深。", "寂寥不改丘岩志，闲静渐忘湖海心。翻觉贫穷倍亲切，从兹喜作菜根吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游春十二首 其五","p":"","d":"唐代","a":"姚合","c":["疏顽无异事，随例但添年。旧历藏深箧，新衣薄絮绵。", "暖风浑酒色，晴日畅琴弦。同伴无辞困，游春贵在先。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵邢敦夫秋怀十首","p":"","d":"宋代","a":"秦观","c":["蝮蛇初螫手，壮士断其腕。", "岂不悲毁伤，所恤在躯干。", "西羌沙卤地，置戍或烦汉。", "鸡肋不足云，阿瞒妙思算。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偕诸年丈游清凉台 其一","p":"","d":"明代","a":"李孙宸","c":["未尽登临意，相携上玉台。云山千嶂合，井里万家开。", "日落寒原迥，风生暮壑哀。迟回江月上，似涌夜珠来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谁园即事八首 其四","p":"","d":"近代","a":"张瑞玑","c":["作意东皇雨露新，山花野草亦精神。狂来诗酒无馀子，老去须眉几故人。", "花谱树经书好趣，雨蓑雪笠画中身。樽前莫话前朝事，京洛衣冠付劫尘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和王宣义买菊栽二首 其一","p":"","d":"宋代","a":"毛滂","c":["秋风有好色，寄在菊花团。弛担知新主，临池得细看。", "金房迎日秀，玉露作香寒。独负东篱意，年来漉酒乾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵龄叟招石秀叔","p":"","d":"宋代","a":"陈著","c":["久知难久别，飞约到柴门。", "唤起雨窗困，踏开岚径昏。", "世情忙外看，交道淡中存。", "何日巳公屋，新诗得共论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"沁园春 次韵林南金赋愁","p":"","d":"宋代","a":"陈人杰","c":["抚剑悲歌，纵有杜康，可能解忧。为修名不立，此身易老，古心自许，与世多尤。平子诗中，庾生赋里，满目江山无限愁。关情处，是闻鸡半夜，击楫中流。澹烟衰草连秋。听鸣鴂声声相应酬。叹霸才重耳，泥涂在楚，雄心元德，岁月依刘。梦落莼边，神游菊外，已分他年专一丘。长安道，且身如王粲，时复登楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天","p":"","d":"元代","a":"张翥","c":["一曲吴歌酒半酣。声声字字是江南。书凭仙苑青鸾递，花助妆楼粉蝶衔。", "飞燕瘦，宝儿憨。已妍还慧更岩岩。无因剪得湘江水，与蘸春云作舞衫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"文宣王及其弟子赞 其六十三","p":"","d":"宋代","a":"赵构","c":["侁侁申周，四科与俦。逸驾文圃，鼓枻儒流。冠佩既燕，言动允休。", "邵陵得封，可想清修。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢崇上人惠新茶","p":"","d":"宋代","a":"曹勋","c":["春入闽溪草木香，灵芽一夕一丝长。", "上人自是春风手，分与闲人齿颊芳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽孟侍郎鉴","p":"","d":"明代","a":"何乔新","c":["华胄承驺鲁，宏才迈俊英。麟经曾擅业，虎榜蚤登名。", "英荡风声远，黄门地位清。含香趋琐闼，拥笏导霓旌。", "奏对承殊渥，超迁位列卿。朔方劳转饷，南海藉治兵。", "区脱狼烟息，沧溟蜃雾晴。赐归蒙圣眷，徵起惬舆情。", "勋业追先哲，威仪式后生。白鸡俄入梦，黄阁竟辞荣。", "当宁嗟杨绾，同朝惜孔明。芳声垂汗简，懋绩纪桓楹。", "旧业荒烟暝，新阡宿草萦。临风歌楚些，悽怆泪沾缨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"观音岩","p":"","d":"清代","a":"郑世元","c":["粤山山山奇，兹岩益奇绝。嵌空有神功，壁立淬寒铁。", "晻㫲山精藏，灵秀真宰泄。赤日万古阴，江雾昼常结。", "飞楼骑危驾，石隙透微穴。拾级如盘螺，堂隍忽开列。", "僧梵响出云，钟乳倒垂雪。南罗罗浮佳，北与大庾别。", "目谋觏斯奇，殊使羁心悦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄华山司空图二首 其二","p":"","d":"唐代","a":"虚中","c":["逍遥短褐成，一剑动精灵。白昼梦仙岛，清晨礼道经。", "黍苗侵野径，桑椹污闲庭。肯要为邻者，西南太华青。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"许云村舟过勾溪欲访溪翁为帆急不相见而去寄诗致其情溪翁和答有见嘲意予为作二绝句解之 其一","p":"","d":"明代","a":"朱朴","c":["结交头白总忘年，相见无因事偶然。绝胜当时风雪夜，到门空返剡溪船。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花集句 其二○一","p":"","d":"宋代","a":"李龏","c":["渔舸汀鸿外，霜天似水清。更无花上月，新句与谁评。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和王褒咏摘花","p":"","d":"南北朝","a":"宇文毓","c":["玉椀承花落，花落椀中芳。酒浮花不没，花含酒更香。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"抛球乐 中秋荔湾待月","p":"","d":"清代","a":"陈洵","c":["罨画溪流叠翠屏。晚罨颦黛自然生。闻香露叶清吟地，摇梦风灯旧霸城。", "佳约无端暗，水调依稀最有情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洛阳桥","p":"","d":"清代","a":"林朝崧","c":["横天渴虹长万尺，下饮沧江化为石。鞭之叱之成此桥，桐城太守莆中客。", "往时欲渡川无梁，行人海葬蛟蜺宅。自从天堑变康庄，无复风涛阻形役。", "我生飘泊一飞鸿，缘在重留雪泥迹。手摩苔藓读遗碑，百五十字凝古色。", "碑中空记倡义人，岁久谁能识王实？将军下海语荒唐，流俗相传偏啧啧。", "古人利济同一心，或传或否堪太息！沈吟此事意难平，斜凭危栏日将夕。", "汀洲橹唱催人归，几阵松风洒巾帻。匆匆作诗别江神，何日重来看潮汐？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海棠","p":"","d":"宋代","a":"姜特立","c":["绚丽繁霞綵，荧煌瑞锦堆。夜深疑睡去，日暖怕慵来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄兄玉老","p":"","d":"宋代","a":"储泳","c":["雷阳路迢递，回首亦关心。", "重别因轻诺，远行多近吟。", "客怀秋色早，归梦岭云深。", "莫以书无益，人来惜万金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"敬题吕曜初先生画像 其二","p":"","d":"清代","a":"林朝崧","c":["岂有儒生怀侠骨，几闻草野报皇恩。壮君独抱匡时志，令我思招入海魂。", "养士郇厨传食谱，娱亲莱采舞梨园。一衿断送当年惜，馀庆谁知在子孙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词 其四十九","p":"","d":"宋代","a":"王仲修","c":["楼台雪霁晓阴阴，珠网屏风御幄深。和气先春宫掖暖，凤钗不用辟寒金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虎牢关","p":"","d":"清代","a":"陈见智","c":["百战成皋地，中原第一关。大河回九曲，少室互重山。", "风雨崤函外，人烟巩洛间。往来凭眺处，回首已苍颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"甘州　和晋如","p":"","d":"当代","a":"刘斯翰","c":["共沙鸥片片逐潮来，水阁又秋风。正天涯流落，梦回搔首，月地朦胧。", "最恨悠悠玉笛，吹断水犹东。谁寄香山叶，亲付冥鸿。", "梦断京华春夜，听鼓楼岑寂，檐滴初融。把纤纤寒玉，呵罢意还慵。", "忍图南、伊人抛撇；却相思、泪堕满江红。回阑倚，珠娘歌里，拍遍玲珑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清静经","p":"","d":"宋代","a":"白玉蟾","c":["大地山河一卷经，拈来题目甚分明。", "山花野草皆谈说，蠢动含灵侧耳听。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"芙蓉楼送辛渐二首","p":"","d":"唐代","a":"王昌龄","c":["寒雨连天夜入吴，平明送客楚山孤。", "洛阳亲友如相问，一片冰心在玉壶。", "丹阳城南秋海阴，丹阳城北楚云深。", "高楼送客不能醉，寂寂寒江明月心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵赵司理山甫","p":"","d":"元代","a":"杨弘道","c":["身喜沾皇化，心惭赞老成。青衫初借著，白发已潜生。", "会计唯期当，康宁未暇营。如何清夜梦，常绕大堤行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读浮休诗有感","p":"","d":"宋代","a":"廖行之","c":["二十年间儿女諠，糟糠勤苦不堪论。", "如今八载君身后，儿已登科又长孙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赴南都登太岳二首 其一","p":"","d":"明代","a":"杨巍","c":["驻马登东岳，凭高辨四溟。始知人世小，不断此山青。", "楼阁秋孤出，川原昼杳冥。将寻孙复隐，忽忘有严程。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"颂古四十五首","p":"","d":"宋代","a":"释慧远","c":["饶君舌拄梵天，我也令行一半。", "赵州头戴草鞵，也是新繁轹鑽。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"勉诸生习小学四首 其二","p":"","d":"明代","a":"林光","c":["搜穷经传几年馀，谁把神明信此书。除却寻常伦理外，更将何事称为儒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"妙智寺","p":"","d":"宋代","a":"陈白","c":["八重峰顶望群山，百谷东流去不还。", "惟有右军遗迹在，月波时落墨池间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂咏一百首 其二十二 婴臼","p":"","d":"宋代","a":"刘克庄","c":["贤矣两家臣，存孤极苦辛。后来有曹马，亦是受遗人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏无住观中物四首 其四 朱鱼","p":"","d":"明代","a":"王世贞","c":["猩红数点媚清泠，暖藻香萍度此生。莫向江湖贪广阔，近来鱼网大纵横。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游木渎钱氏园三章 其一","p":"","d":"清代","a":"姚燮","c":["妙构极自然，疑非人意造。颇嫌短晷催，未容恣探讨。", "云缛廊有苔，露酽径多草。绮石如美人，坐阅万花老。", "百绺枯藤缠，疑尔青鬓槁。潭镜千尺泓，残荷一茎袅。", "遂使静止天，玉芬溢龙脑。何以蜻蛉红，但媚水阴蓼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘主簿许饷苦笋未至 其一","p":"","d":"宋代","a":"周紫芝","c":["苦竹冈头竹似云，刘郎何事不挥斤。杯盘倘使同吴俗，荼荠谁能作楚文。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三月再还家","p":"","d":"宋代","a":"蔡襄","c":["晓树乡关路，春衣使者轺。", "江眠闻落霰，野饭掇新苗。", "入里威稜减，宁亲喜气饶。", "勤勤父师教，民病若为消。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双峰寺","p":"","d":"清代","a":"弘历","c":["度壑穿林才片刻，双峰一榻恰怡神。回头拟向如来问，彼此伊谁是主宾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清平乐 其十一","p":"","d":"清代","a":"吴湖帆","c":["敷文尽去。隽语无嫌絮。醉意狂情禁不住。争似谁家深处。", "窗前月色微昏。更阑悄掩重门。正好相倾肺腑，胜于真个销魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"悼周镐 其二","p":"","d":"明代","a":"陈献章","c":["一双玉树出东溟，岂意先随晓露倾。三十六年惟一女，老夫垂泪写铭旌。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"都城初秋和赵京府","p":"","d":"宋代","a":"朱浚","c":["从来美玉价连城，结佩乘风十二京。", "携上峥嵘今有约，好留彩笔调清平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喜省中王秀才至","p":"","d":"明代","a":"陶益","c":["入港趋潮急，随风觉棹轻。乍疑诸客舫，欣见一儒生。", "剑气妆残雨，书囊推画城。岂徒通世务，还有下帷情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送刘少尹赴兴州经历三首 其三","p":"","d":"明代","a":"卢楠","c":["大府元戎骑，长驱引万群。共迎刘记室，喜得郤参军。", "燕月排弓影，边霜缀铠文。知君娴庙略，一啸洒天氛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游方山宿李道士房","p":"","d":"唐代","a":"徐铉","c":["从来未面李先生，借我西窗卧月明。", "二十三家同愿识，素骡何日暂还城。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夜游宫","p":"","d":"清代","a":"文廷式","c":["疏雨困眠孤馆。薄衾冷、漏签时断。湿羽投林鸟已倦。", "敛秋心，白云岩，黄槲岘。", "瑟瑟湘波远。动吟思、楚歌声怨。浊酒深杯且自劝。", "渺关河，意难忘，君试忖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重过独乐寺","p":"","d":"清代","a":"弘历","c":["山郡寒烟里，祗园粉堞边。禅房有花木，向日记留连。", "颓废嗟如是，施檀亦偶然。邑民似相识，瞥眼十馀年。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怀仙桥","p":"","d":"宋代","a":"林表民","c":["晴雷书夜激奔湍，涧草岩花亦耐寒。", "刘阮茫茫空仰止，恐乘风月一鞭鸾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四月出关道中感赋","p":"","d":"清代","a":"陈曾寿","c":["次第看花已作尘，出关烟景似初春。东风又绿先畴土，血染谁哀让畔人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"依韵和范景仁内翰","p":"","d":"宋代","a":"王圭","c":["门前车马走尘埃，偶到东园眼暂开。鳌岭凤池人去后，不知载酒又谁来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"扶沟知县周职方录示白鹤宫苏才翁子美赠黄道","p":"","d":"宋代","a":"欧阳修","c":["能棋好饮一道士，醉墨狂吟二谪仙。", "道士不闻乘白鹤，谪仙今已揜黄泉。", "古来豪杰皆如此，谁拂尘埃为惘然。", "华发郎官才调美，更将新句续遗篇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"拟东武曲二首","p":"","d":"宋代","a":"宋祁","c":["我家世世山西士，二十期门从天子。", "始随骠骑破祁连，晚逐楼船下{特寺換羊}水。", "汉北雰雰飞雪暗，海中跕跕翔鸢坠。", "归来武库祭蚩尤，得从甘泉参豹尾。", "何意一朝兵后期，簿责侵诬属军吏。", "黄金纳赎为庶人，白首还家事田里。", "结发从军七十战，利镞金痍犹可记。", "龙钟虽入玉关门，止呵还遇灞陵尉。", "不及金张藉旧勋，七叶华貂长富贵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"槃隐","p":"","d":"宋代","a":"释居简","c":["考得幽栖地，怡然胜美除。未归已彭泽，不梦亦华胥。", "绿绕清分远，红稀碧间疏。渔樵莫争席，不是野人居。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山中杂诗","p":"","d":"明代","a":"罗洪先","c":["问我家何在，山深多白云。", "岩前泉溜下，对语不相闻。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"禾熟三首 其二","p":"","d":"宋代","a":"孔平仲","c":["丰年气象慰人心，鸟雀啾嘲亦好音。玉食儿郎岂知此，田家粒粒是黄金。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次颐伯韵","p":"","d":"近代","a":"章以荣","c":["旧国烽烟里，新亭涕泪中。山河犹失色，未敢厌兵戎。", "且莫悲商老，应须问塞翁。谁将戢羽翼，一举会高风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句 其二","p":"","d":"宋代","a":"吴涛","c":["窗间常作三独坐，琴上时弹一再行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"建炎庚戌溃兵狂襄汉寒食阻趋光作拜扫追慕痛","p":"","d":"宋代","a":"张嵲","c":["上庸寒食已无花，山木青青吐嫩芽。", "此日伤心九原路，想无鸡犬只鸣鸦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山楼对雨却寄京国诸同人","p":"","d":"清代","a":"李锴","c":["古情脉脉终何极，老鬓萧萧不耐秋。八月关河横暮色，四山风雨入危楼。", "残书过眼愁深解，荒稼侵寒任晚收。好我故人休系念，知吾身世付虚舟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天（时夫人寿）","p":"","d":"宋代","a":"崔敦礼","c":["本是瑶台月里仙。笑麾鸾鹤住人间。蟠桃一熟三千岁，剩对春风日月闲。", "缡绶结，彩衣斑。孙枝相应傍门阑。年年同上长生酒，得见沧溟几度干。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"感事四首 其二","p":"","d":"近代","a":"连横","c":["拒楚宾秦计早成，竞传韩魏是同盟。已闻古佛生天竺，复见蚩尤出汉城。", "南极一星朝北斗，东风万里接西溟。烂柯山上傍观懒，胜负纷纷判此枰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"附：李助为章武赋","p":"","d":"唐代","a":"李助","c":["石沈辽海阔，剑别楚天长。会合知无日，离心满夕阳。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"登黄鹤楼作（有序）","p":"","d":"明代","a":"林章","c":["望里山川是楚乡，美人何处水茫茫。", "祢衡作客留江夏，赵壹辞家出汉阳。", "鹤去未知芳草暗，雁来先觉白云凉。", "倚楼无限西风意，堪与千秋一断肠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵申泮宫直宿早秋四首 其一","p":"","d":"宋代","a":"傅察","c":["新秋爽气溢长空，弦诵低昂月映栊。济济青衿成鲁变，洋洋泮水咏洙风。", "群儒篆刻空章句，百氏纷纭赖折中。何日拔才空冀北，如今高誉满山东。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"见花","p":"","d":"明代","a":"黄淮","c":["乞得花枝洒泪看，满怀愁绪万千端。故园亦有繁桃李，门掩东风暮雨寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"戴宾有意山书屋谈次偶成时宾有举子","p":"","d":"清代","a":"马凤翥","c":["意山书屋我曾过，无句堪题邵子窝。卖赋近闻车辙满，乞钱常致酒材多。", "檐前绿竹添新笋，石上盘根长旧柯。莫笑客为汤饼至，携尊高唱待如何。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"别樊时中廉使","p":"","d":"元代","a":"余阙","c":["光禄桥西惜解携，春星欲傍露盘低。自来官柳多离思，更著城乌在上啼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"惜红衣 神武门残荷，和茧庐","p":"","d":"清代","a":"周岸登","c":["草长红心，鹃啼恨魄，梦残凝碧。寸藕长丝，娟娟露桥北。", "金仙泪洒，曾惯听、枯鱼泉泣。沾臆。露佩水裳，哭秋风归客。", "湘灵鼓瑟。哀怨如闻，宫沟送潮汐。余姿婉娈自惜。", "映寒日。冷入粉云凉翠，不似井华颜色。怕坠房欹盖，犹怯薄铅偷滴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋怀 其七","p":"","d":"明代","a":"王邦畿","c":["剑术雌雄自有神，负恩元是报恩人。辘轳暗转银床晓，輘轹轻移玉宇春。", "不信丹丘为有种，须知黄道即良因。蓬山多少名仙籍，曾把云旗向北辰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八声甘州 客有言西江近事者感而赋此","p":"","d":"清代","a":"陈维崧","c":["说西江、近事最销魂，啼断竹林猿。叹灌婴城下，章江门外，玉碎珠残。", "争拥红妆北去，何日遂生还。寂寞词人句，南浦西山。", "谁向长生宫殿，对君王试鼓，别鹄离鸾。怕未终此曲，先已惨天颜。", "只小姑、端然未去，伴彭郎、烟水月明间。终古是，银涛雪浪，雾鬓风鬟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"举第四子阿豫 其二","p":"","d":"明代","a":"屈大均","c":["花褓人争送，欢生满月时。月娥金粟种，天帝玉兰枝。", "上有三兄小，中多一母私。羽毛成立日，吾已杖朝期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和王巩见寄三首 其一","p":"","d":"宋代","a":"苏辙","c":["南迁春及秋，江湖未云半。逮此归路长，始悟行日远。", "幽忧脱沉痼，清梦惊婉娩。行行逢故人，笑语杂悲泫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙未除夕为稽古诸传未竣漫吟五律 其一","p":"","d":"明代","a":"郭之奇","c":["岁云暮矣暮怀多，老病相从似小苛。蒿目千秋供探索，抽思一管付编摩。", "禹阴夙继无终食，汤日新铭有寤歌。此际骊珠凭独采，人间驹隙漫相过。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"游石钟山寄匡云上人","p":"","d":"明代","a":"邝露","c":["钟山窍奇石，金奏蕴璠玙。微波媾灵牝，噌吰含龙鱼。", "神涛窥日母，鳀壑潜灵居。天声谢人巧，习坎均吹嘘。", "流目桑钦传，钟情伯翳书。弱龄敦夙好，岁晏孰华余。", "是时秋月中，初对惟匡庐。何渠山中人，白社过篮舆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"信士画真请赞 其六","p":"","d":"宋代","a":"释印肃","c":["易尽世间颜色，普庵顶相奚为。等大虚空一体，雾露云霞表衣。", "眼观不见，耳听不知。惺惺不昧，了了何亏。自解拈花知起处，冷笑达磨更西归。", "用晦隐显无劳失，亘古亘今也大奇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹧鸪天","p":"","d":"宋代","a":"刘学箕","c":["梦绕天涯去意浓。客愁春恨两匆匆。绿波初涨桃花浪，画鹢轻随柳絮风。", "无笔力，判虚空。关山千里两心同。鱼书雁字都休问，只看啼痕翠袖红。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"隆中遇雨","p":"","d":"明代","a":"林光","c":["隆中留胜迹，冒雨我能来。树洗层层翠，溪喧滚滚雷。", "草深诸葛庙，云罩简王台。安得长风扫，阴霾拨未开。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"与群公分地赋诗得京口","p":"","d":"明代","a":"郑经","c":["京口瓜州指顾间，春风几度到钟山。迷离绿遍江南地，千里怀人去不还。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日出池上","p":"","d":"宋代","a":"宋庠","c":["节候春虽往，年华暑未残。", "莲香开佛座，竹老退刘冠。", "戏渚藏頳尾，鸣皋濯素翰。", "堇葵红不一，蒲稗绿多端。", "宜物心无对，深根气自完。", "功名俱画饼，虚玷拥旄官。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重过泰山 其一","p":"","d":"明代","a":"葛昕","c":["几年今复过名山，石磴苔深鸟道宽。万壑行云千里树，尘寰俯瞰倚危栏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"萧寺寻僧图","p":"","d":"明代","a":"谢晋","c":["极目萧山寺，岧峣在越溪。风传钟远近，云接树高低。", "别去情无己，重寻路不迷。何时乘老兴，登眺策青藜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋雨","p":"","d":"宋代","a":"陆游","c":["吾庐多美荫，最茂楸与梧。", "百鸟集其间，下上更鸣呼。", "秋风忽动地，摇落日日疏。", "何如涧底松，终岁无荣枯？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"章靖冯公哀词","p":"","d":"宋代","a":"宋祁","c":["华殿推名学，南宫重亚卿。", "心无二何佞，身有两龚清。", "归沐宾綦鲜，幽通笔思精。", "邦人为公恨，不见相承平。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杏花天 寿杨经历七十一","p":"","d":"明代","a":"史鉴","c":["杏花开遍东风里。爱春色、年年相似。仙翁试把朱颜比。不是等閒桃李。", "借问胡麻和石髓。怎能比、子孙甘旨。古来七十人能几。过了从头数起。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵俞仲基对雨二首 其一","p":"","d":"明代","a":"董纪","c":["田家信五行，甲子只祈晴。柱础俄先润，天瓢忽屡倾。", "水声寒汨汨，云气白英英。缩手防揫敛，农人奈此情。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"松石行窝","p":"","d":"明代","a":"张宁","c":["静老山林故有期，行轩移凿是何时。阴连绝壁云孤峭，枝压浮峰雨半欹。", "十载风霜寒士节，万间梁础大方姿。陶潜已去元章远，岁晏斋空只自怡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"松江金泽寺四首 其二","p":"","d":"明代","a":"唐顺之","c":["三江抱处势如环，野客探奇住不还。一望楼台疑海上，稍闻鸡犬觉人间。", "幸无渔父知名姓，且与山僧共闭关。自笑归来张季子，春时莼叶未堪攀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高宗纯皇帝御制平定两金川凯歌三十章乾隆四十一年 其二十四","p":"","d":"清代","a":"弘历","c":["准部回城定五年，金川小寇亦如前。嘉予将士久敌忾，不觉对之增恻焉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"昌溪水","p":"","d":"宋代","a":"杜如篪","c":["险绝昌溪水，如何亦问津。", "命分毫发地，利役古今人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海音诗","p":"","d":"清代","a":"刘家谋","c":["迎年饯腊事休论，爆竹声中欲断魂。争得城西黄太学，一囊夜半忽敲门。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长须国驸马咏妻","p":"","d":"唐代","a":"长须国驸马","c":["花无叶不妍，女无须亦丑。丈人试遣惣无，未必不如惣有。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送默然上人归天台","p":"","d":"宋代","a":"王镃","c":["孤云不定心，持缽度寒林。", "野饭青蒲洁，秋程黄叶深。", "海风潮水发，山雨晓烟沉。", "归到石桥日，应看瀑布吟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病中初见梅花驰送季申枢密并以二绝","p":"","d":"宋代","a":"李弥逊","c":["病眼逢药不忍窥，飞奴走送已嫌迟。", "定知着意怜纤瘦，不放春心落别枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"抵平彝","p":"","d":"清代","a":"戴絅孙","c":["未肯因人热，宵长拥敝裘。寒风支酒力，旧雨絮乡愁。", "垒石山为障，清溪水自流。帝京今万里，新纪少年游。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"七鲲身","p":"","d":"清代","a":"钱琦","c":["海中有鲲夜化鹏，将飞似堕忽伏蹲。浸作千年老云根，分排玉立如弟昆。", "蛟宫千丈姿雄跨，鳄浪万里供馋吞。壮气已作长虹吐，远势欲挟孤鸾骞。", "如砥狂澜留柱石，时挝天鼓殷雷门。左控安平右鹿耳，襟带众汇如缭垣。", "当年蛙龟争雄处，犀甲百万齐云屯。一声海吼白骨枯，潮头战血交流浑。", "自从归我版图后，恬波息浪清乾坤。升平大业垂万古，异域往往叨殊恩。", "祇今穷崖绝壑地，已成紫蟹黄鱼村。我来正值三月暮，裌衣习习春风温。", "他山可望不可即，远见一片苍烟痕。天地沧桑本变幻，古今兴废如朝昏。", "况复浮生一泡影，忍令岁月逐尘奔。眼中俗客难为论，黯然默默销神魂。", "安得如尔息健翮，坐受晚露与朝暾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"四威仪","p":"","d":"宋代","a":"释师范","c":["山中坐，习闲成懒惰。", "少献花，但见猿偷果。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题西村陈氏所藏高待诏水墨四幅 其二","p":"","d":"明代","a":"王恭","c":["春水重林旧草庐，半村残雨带归渔。空山不是无猿鹤，惆怅何人更隐居。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"逢道者","p":"","d":"唐代","a":"张蠙","c":["纵意出山无远近，还如孤鹤在空虚。昔年亲种树皆老，", "此世相逢人自疏。野叶细苞深洞药，岩萝闲束古仙书。", "只寻隐迹归何处，方说烟霞不定居。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"张嵲","c":["此堂纵逐人俱废，亦有阳冰篆字存。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"郊庙歌辞。释奠文宣王乐章。舒和","p":"","d":"唐代","a":"佚名","c":["隼集龟开昭圣烈，龙蹲凤跱肃神仪。", "尊儒敬业宏图阐，纬武经文盛德施。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"阆州","p":"","d":"宋代","a":"汪元量","c":["阆州城南海棠溪，客子不可无新诗。正嫌风搅浪花碎，更被雨冲云叶垂。", "野鸥出没底心性，山禽飞舞犹威仪。江南或问阆州景，锦屏山水天下奇。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"苏幕遮","p":"","d":"元代","a":"王哲","c":["道无言，禅没说。两道白光，唯许红霞设。真玉山头常摆拽。", "泼滟滟兮，返照灵峰雪。", "愈玲珑，元皎洁。射透晴空，莹莹神光别。到此玄玄玄妙彻。", "一朵金花，里面金丹结。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"晚至平望驿欲行阻风有怀吴中所知","p":"","d":"明代","a":"梁以蘅","c":["江云漠漠水迢迢，去越孤舟逐浪摇。微月尚堪乘晚棹，回风故遣息寒桡。", "正思吴地人方迩，为问枫桥路岂遥。此夜客肠翻欲结，高栖几处莫吹箫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"董逃行","p":"","d":"宋代","a":"陆游","c":["汉末盗贼如牛毛，千戈万槊更相鏖。", "两都宫殿摩云高，坐见霜露生蓬蒿。", "渠魁赫赫起临洮，僵尸自照脐中膏。", "危难继作如崩涛，王朝荒秽谁复薅？踰城散走坠空壕，扶老将幼山中号。", "昔者群枉根株牢，众愤不能损秋毫；谁知此乱亦不遭，名虽放斥实遁逃。", "平民踣死声嗷嗷，今兹受祸乃我曹！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题余芳谷左右修竹图","p":"","d":"清代","a":"安伟","c":["爱竹能留客，无君不可居。相亲思德茂，得意左心虚。", "坐啸谐清韵，行吟动翠裾。请看佳士照，左右尽林于。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏禹","p":"","d":"宋代","a":"王十朋","c":["洪流浩浩浸寰区，民杂蛇龙鸟兽居。长叹当时微帝力，苍生今日尽为鱼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"舟行青溪道中入歙十二首 其十一","p":"","d":"宋代","a":"方回","c":["蕨拳欲动茗抽芽，节近清明路近家。五日缓行三百里，夹溪随处有桃花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辰玉应试留都赋此赠之兼赠孟孺 其一","p":"","d":"明代","a":"王世贞","c":["欲识操觚业，为之无以为。熟若转丸蜣，专则抱卵鸡。", "灵台仅一寸，武火安所施。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽戴彦诚通判三首 其三","p":"","d":"宋代","a":"刘才邵","c":["贾鵩由来忌，应曾为废书。始终归有数，善庆岂无馀。", "贤嗣真兰玉，令名惊里闾。他年定通显，跃马从金舆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南天门揽胜轩作","p":"","d":"清代","a":"弘历","c":["盘纡石路陟嶙峋，揽胜还欣回出尘。何必森严卫虎豹，居然尺五俯星辰。", "云轩峰岭延遥近，梵宇香花悦静真。大士如如无色相，却看历历往来人。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"以诗句咏梅 十年花送诗人老","p":"","d":"宋代","a":"方蒙仲","c":["花老几人来，人老花常少。安得似花人，年年陪一笑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和散木韵 其六","p":"","d":"明代","a":"袁宏道","c":["落叶蔽秋矶，残霞雨洗晖。弹花蝉虎匿，掠竹水鹰飞。", "白足遗棕屦，青娥送道衣。庖童觅鲙去，兼买紫姜归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"三花斛三首右兰花","p":"","d":"宋代","a":"杨万里","c":["雪径偷开浅碧花，永根乱吐小红芽。", "生无桃李春风面，名在山林处士家。", "政坐国香到朝市，不容霜节老云霞。", "江蓠圃蕙非吾耦，付与骚人定等差。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"行香子 七夕","p":"","d":"清代","a":"许德蘋","c":["阶下秋蛩。井畔疏桐。正今宵牛女情浓。经年别绪，愁诉重重。", "料星桥南，星桥北，喜相逢。", "人间乞巧，好陈瓜果，也怜他离恨无穷。银湾斜转，砧杵声中。", "剩一炉烟，一钩月，一帘风。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"积翠楼","p":"","d":"宋代","a":"危和","c":["著我高远堂，恍若非人世。一榻卧白云，清寒不成寐。", "松竹四山秋，飕飕惊客耳。谁在隔窗中，朱弦写流水。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江雨来","p":"","d":"明代","a":"邵宝","c":["西津渡头江雨来，雨点入江江水回。云飞逐风沙走石，咫尺不见东冈台。", "台树丛丛还可望，台上看江更奔放。明朝拟下鄱阳船，月色浮江水微浪。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"乙巳岁郊天后作","p":"","d":"宋代","a":"魏野","c":["万物尽熙熙，郊天礼毕时，", "安边文教远，过海赦书迟。", "南牧虽无也，东封合有之。", "茅堂自歌咏，何必向丹墀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春尽日","p":"","d":"宋代","a":"赵蕃","c":["山密风蟠木，檐疏雨著窗。", "拥衣憎旧絮，酌酒爱新缸。", "放意初无累，冥观久已降。", "一春今日尽，归梦渺三江。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"闻二十八日之报喜而成诗七首 其四","p":"","d":"宋代","a":"朱熹","c":["渡淮诸将已争驰，兔脱鹰扬不会期。杀尽残胡方反旆，里闾元未有人知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"赵湘","c":["十度花残一觉眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丹霞舍利塔","p":"","d":"明代","a":"释函是","c":["心光彻内外，如珠入五色。珠与色无性，非离亦非即。", "非即超形骸，非离浃营卫。月在千波中，波波摇青霁。", "凡圣唯一心，湛昏成二谛。示生死涅槃，而实无坚脆。", "脆以别生死，坚光表性义。本从心生色，迷色乃有二。", "蚌含明月珠，体合百骸粹。领纳镜中像，想即妙观智。", "流注皆真常，分别非明记。如是五蕴身，与法身何异。", "秖因一念迷，情生分秽净。净秽悟由心，当念绝邪正。", "佛以此智證，法化无同别。示现别中同，同中别自晰。", "光耀百千年，福被我遗教。神光触金轮，仰瞻如梦觉。", "栖贤发瑰异，感激当其运。移光照岭南，慈曜无远近。", "佛子学聚沙，燔土紫金斓。崔巍海螺巅，晶晶逼霄汉。", "举目道与会，布发形俱泮。见闻起遐情，究此未来际。", "念念尽圆明，身与心毋戾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有赠 其四 黎益之、杨永权","p":"","d":"当代","a":"刘斯奋","c":["才人珠海说黎杨，三日谈诗未举觞。何不放舟兵气夜，红醪浓注一湖霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"区民部熊孝廉赵山人雨后同集旅寓","p":"","d":"明代","a":"李孙宸","c":["雨过庭前长绿苔，青尊旬日未曾开。偶逢南国高人集，便挟西山爽气来。", "懒性自知难和世，宦情真冷不然灰。周南留滞吾今似，深愧龙门一代才。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄酬致政赵少师五首 其五","p":"","d":"宋代","a":"赵抃","c":["天台雁荡去寻真，往复秋冬过七旬。不是君恩山岳重，肯教归作自由身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄滕县李奉议","p":"","d":"宋代","a":"陈师道","c":["滕大夫伯阳父孙，烹小鲜治大国原。", "一得何用五千言，弛灾决狱人不冤。", "盛气走讼畏讨论，终岁敛吏不到门。", "子弟无赖皆西奔，外吏畏惧过乃尊。", "踵门父老如云屯，拊髀跳踉走儿孙。", "绛幡翠节歌呗喧，画盆戴顶烟如焚。", "绣褾彩轴箱帕繁，曲躬叉手前致言。", "畜眼未见耳不闻，暮年何以答此恩，", "请诵华严寿我君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘德明彦集祝弟以夏云多奇峰为韵赋诗戏成五绝 其一","p":"","d":"宋代","a":"朱熹","c":["出山几何时，归来便长夏。端居心不怡，散策长林下。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"海陵岁暮 其一","p":"","d":"宋代","a":"孙应时","c":["地气长江北，云容古戍边。层冰明薄日，积雪了穷年。", "乡远劳羁梦，官閒足晏眠。客来相劳苦，不责坐无毡。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蠡湖行","p":"","d":"明代","a":"王鉴","c":["山苍苍，水泱泱，湖天一钓青茫茫。云是范蠡扁舟之归路，湖田绿雨，两岸浸垂杨。", "千丝万丝蘸波面，年年逝水随流光。老渔醉不醒，醒起满船霜。", "霜风叫寒鹰，一字横吴江。沼吴人去鸥拍拍，天澹云闲几狂客。", "狂客大笑何为乎，夫差一醉亡其国。又复感慨贤豪闲，范蠡归来欲谋食。", "彼诚不必登西山而采蕨薇，亦奚不先严陵而坐磐石。", "噫嘻乎，千金或可谋，幼子亦可惜。积财不散天厌之，山亦欲崩海亦溢。", "我歌蠡湖行，声与秋云翔。秋云无定忽变灭，水底分明见湖月。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"小字","p":"","d":"清代","a":"孙原湘","c":["谢公最小女偏怜，小字呼来定绛仙。一月回悬珠树朗，百花都让玉梅妍。", "疗饥自喜忘并日，消渴何辞为损年。每向画眉窗下见，匡庐只在镜台前。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠湘南易淑南 其二","p":"","d":"清代","a":"李锴","c":["怀香何处问芳荪，文藻风流宋玉存。万里惊波漂断梗，不堪摇落赋招魂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"旅兴 其四十四","p":"","d":"元代","a":"刘基","c":["日落天气凉，逍遥步庭墀。蟋蟀巳在宇，鸿雁来何迟。", "少壮轻远游，衰老伤别离。念我亲与友，各在天一涯。", "音容两契阔，悲欢绝相知。铩羽怀旧林，葺繗思故池。", "百年能几何，逝者无还期。俛仰增感叹，有怀当语谁。", "殷勤托宵梦，聊用慰所思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"唱到阳关第四声","p":"一剪梅","d":"宋代","a":"刘仙伦","c":["唱到阳关第四声。香带轻分。罗带轻分。杏花时节雨纷纷。山绕孤村。水绕孤村。", "更没心情共酒尊。春衫香满，空有啼痕。一般离思两销魂。马上黄昏。楼上黄昏。"],"tags":["离别", "无奈"],"z":"","y":"笔写“唱到阳关第四声”，即唱到“劝君更尽一杯酒”既没有写情，也没有写景，而情与景近在眼前：景是离别之景，情是伤离别之情。没有直接写出，却让人接下来就有一种“西出阳关无故人”的离愁别绪。“罗带”本指丝织的衣带，在此则指将要远行之人，“香带”指送行的女子。“香”字写出了女子衣衫的特点，也让人想到的女子温婉贤淑。二人即将分离，“轻”字写出了双方复杂的心理，仿佛不敢又不忍触碰别离这一话题，然而启程的时间却已经到了。“杏花时节雨纷纷”点明了时间为春天，天还下着淅淅沥沥的雨，让人想到那首“清明时节雨纷纷，路上行人欲断魂”现在同样的季节，同样的天气，游子也将成为那路上的行人，孤独，落寞，伤感。两","s":"","k":"词"},
  {"t":"清湘城西飞来峰 其二","p":"","d":"宋代","a":"曾丰","c":["三处飞来一样奇，佛无所择我何辞。重轻较到毫釐处，鸣雁行中此白眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄长乐尉廖声玉","p":"","d":"明代","a":"成鹫","c":["吏隐如君得自然，多生曾结衲僧缘。春风怅别同为客，故国言归老此禅。", "前路一投孤店宿，居人尽说长官贤。自从识得齐昌尉，始信梅生是人仙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"每见村农野老不识不知天然自得孝弟发于至性朴诚不事文辞故美其实而取先进之意赋七言一律","p":"","d":"清代","a":"玄烨","c":["昼夜徬徨利禄间，奚如鄙里野人閒。诗书不解穷通事，名姓无闻士宦班。", "孔颜乐处箪瓢在，孝弟真情稚子关。可笑文章少实据，空将浮伪玷青纶。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"听蓼庵处士弹汉宫秋","p":"","d":"清代","a":"吕师濂","c":["雪云垂幕风飕飂，天荒地老客倦游。多君开手抚玉轸，凄清弹出《汉宫秋》。", "初如洞庭下木叶，复如滟滪泻寒流。得无酒徒击别筑，得无嫠妇泣孤舟。", "又疑猿啼向空谷，又疑雁叫落高楼。借问此曲声何悲，令我忽忆国破时。", "先帝有琴曰翔凤，玉熙宫里常携随。时当中秋开夕宴，袁妃敛衽弹《关雎》。", "意静指闲人月下，商流羽激声云飞。星河斜度仙人掌，鸾鹤齐鸣百子池。", "玉槃进酒葡萄暖，一挥再鼓天颜怡。须臾寇盗肆窃发，衣宵食旰筹征伐。", "无复重闻《金缕衣》，何曾还对丝桐月。翔凤无端霹雳鸣，朱弦一一如刀截。", "至尊惨澹竟攒眉，宫妾惊惶群吐舌。事在甲申春之初，传其说者中涓吴。", "不道三月十九日，乾翻坤陷龙鼎湖。峄阳之桐识治乱，八音遏密钟虚换。", "金枝玉叶坐彫残，凤尾谁怜应出爨。吾民从此忆薰风，师旷师襄逐断蓬。", "臣本恨人闻苦调，依稀泪带甲申红。翔凤而今安在哉，手琴囊锁亦休开。", "亟须满饮三百杯，将愁遣去无使来。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"洞仙歌 其一 念台先生海天旭日砚，裔孙海门绘图，属题","p":"","d":"清代","a":"奭良","c":["韩陵片石，去名贤未远。且做人閒鼎彝看。忒煞坚、耐他磨了还磨，谁比似、只玉带遥遥作伴。", "留传都有意，付与云礽，慷慨乘城伴危难。拂拭莫开帘，咫尺图中，海波沸、日光幽黯。", "属木石、吴儿莫轻题，怕青针穿时，素笺难浣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪沙（席上别王巨济。先是，两姬免冠，王夺两秩，继以章罢）","p":"","d":"宋代","a":"洪适","c":["丹桂飘香已四番。杖藜携手自今难。黯然离恨满江干。", "壁上两冠元是谶，花前双韵几时弹。中秋后夜与谁看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"天仙子","p":"","d":"清代","a":"张振","c":["画阁雕栏春暗渡。行来罗袜苍苔护。日长人倦不胜情，香满炷。", "风吹幕。啼莺却在花深处。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"对酒","p":"","d":"明代","a":"薛蕙","c":["畏涂有千虑，劳生无寸隙。", "唯余对酒时，暂作伸眉客。", "妖姬杂睇笑，欢友连衿舄。", "相逢判一醉，钱刀非所惜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"凉州词二首 其一","p":"","d":"明代","a":"邓云霄","c":["城高楼角近旄头，边月胡风早送秋。不信凉州多猛将，还听稚子说封侯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桂州 其四","p":"","d":"宋代","a":"陶弼","c":["旧策扫开浪泊雾，新诗装就桂林春。相离水色秋前老，独秀岚光霁后匀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十四日 其一","p":"","d":"宋代","a":"韩淲","c":["淡淡春晴晚，窗前燕子飞。酒杯谁共饮，诗笔自孤挥。", "上冢家山远，下湖仙苑稀。空多冶游者，扶醉赶门归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"清江引 其二","p":"","d":"明代","a":"孙承恩","c":["篷窗雨来人未寝。早已知寒信。暂借酒留春，无奈霜堆鬓。", "兰缸幽幽频落烬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春游与谢都尉二首 其一","p":"","d":"明代","a":"张元凯","c":["柳市裁春服，花郊费酒钱。家贫不事事，行乐自年年。", "黄鸟催提榼，青衣佐刺船。未须投逆旅，芳草正堪眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春晴","p":"","d":"唐代","a":"任翻","c":["楚国多春雨，柴门喜晚晴。幽人临水坐，好鸟隔花鸣。", "野色临空阔，江流接海平。门前到溪路，今夜月分明。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送人之蜀郡守","p":"","d":"明代","a":"王称","c":["闻道蚕丛国，西连汉陇平。三年怀紫袖，万里慰苍生。", "夜月巴川静，秋风锦水清。请看霜锷试，莫使雪山倾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"失题","p":"","d":"魏晋","a":"佚名","c":["鹓彼鸣鹣。在严山之唫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史 其三","p":"","d":"宋代","a":"孙应时","c":["拊髀平生志八区，暮年家国付夷吾。谁言子女能相豢，可笑周郎浅丈夫。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"求酒赵评事","p":"","d":"宋代","a":"赵崇滋","c":["半老情怀睡不能，小檐霜月当寒灯。无人来问相如渴，敲碎梅花一夜冰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春日怀京华诸友","p":"","d":"明代","a":"郑善夫","c":["闻说神龙起，群贤一网提。中原刑白马，南国且黄鹂。", "夜楫谁同击，春江他自迷。无能逐公子，锡宴上林西。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"早出小东门至藕渠镇","p":"","d":"清代","a":"方仁渊","c":["晨起驾柔橹，宿雾犹冥冥。晓日冲波白，遥山带郭青。", "鱼盐喧小市，鹜雁聚寒汀。自笑谋生拙，孤舟未敢停。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"暗室","p":"","d":"宋代","a":"丘葵","c":["一几善恶未分时，善本无为莫伪为。", "暗室休言人不见，此心才动鬼神知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"己酉新春二首","p":"","d":"明代","a":"吴梦旸","c":["自拟今春怀抱开，林扉时复扫荒苔。", "沙头鸥鸟休飞去，野外梅花许折来。", "多少误人空识字，从容留客不衔杯。", "题书遍问诸名胜，肯入庐山般若台。¤"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"茶园别朱伯言郭公葵","p":"","d":"元代","a":"刘基","c":["细水吹烟送客舟，离情恰似水东流。此时对酒难为乐，何处寻春可纵游。", "去雨来云天渺渺，轻蜂乱蝶日悠悠。绝怜短发无聊赖，一夜如丝白满头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"歧路行","p":"","d":"清代","a":"陆寅","c":["出门竟何之，东西南北皆路歧。仆夫执辔马踯躅，骊歌一声声最悲。", "道傍桃李似惜别，飞花故扑金屈卮。人生目前贵适意，不如还逐屠沽儿。", "兄袁盎，弟灌夫，相逢自负高阳徒，樗蒱百万能呼卢。", "朝金张，暮许史，拔剑欲为知己死，眼前谁是严仲子？"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宝应朱公曾乞蒲团于僧润归榇江州润乃买舟赴葬挂树而去","p":"","d":"明代","a":"盛时泰","c":["生前曾与结幽期，身后冥交独有师。为挂蒲团思往日，因弹锡杖忆当时。", "泪随雪片应难尽，情断风灯总自持。法力护来还不灭，年年慧树长新枝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"雪中独行湖上三首 其三","p":"","d":"近代","a":"李冰若","c":["孤山处处屐曾经，最爱林家放鹤亭。休问梅花开也未，雪中乍见柳条青。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"喻邦相即署中建楼题曰信美索诗为赋四绝 其一","p":"","d":"明代","a":"胡应麟","c":["胡床明月坐高秋，碧瓦朱甍大海头。十二危阑宾从满，一时传作庾公楼。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吊赤水李先生","p":"","d":"唐代","a":"徐夤","c":["三年悲过隙，一室类销冰。妻病入仙观，子穷随岳僧。", "荒丘寒有雨，古屋夜无灯。往日清猷著，金门几欲征。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花十绝句","p":"","d":"宋代","a":"赵蕃","c":["十里荆溪溪上梅，故人几日寄诗来。", "相应载酒裴回次，忆我去年同此杯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"菩萨蛮","p":"","d":"近代","a":"饶宗颐","c":["带愁眉萼阑干曲。春风吹上裙腰绿。去水木兰舟。分愁压翠楼。", "黄衫催马发。楼下花如雪。花雪莫分看。昨宵风雨寒。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题张雪湖吴山煖暧","p":"","d":"宋代","a":"释居简","c":["山藏晻霭树藏云，十驾难追欲去春。鳞砌古愁千万绪，因君开卷又重新。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂二百零五首","p":"","d":"宋代","a":"释正觉","c":["不问维摩经，看底甚麽经，", "大千卷出破尘情。水中盐味，", "色里胶青，机前有路妙难名。", "才形言像迢然去，又是泥团换眼睛。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"荆轲山","p":"","d":"清代","a":"弘历","c":["白云红叶遮横峦，策骑忽过荆轲山。燕南自古多义侠，至今遗迹犹班班。", "嬴秦久矣失其鹿，何须怒臂誇燕丹。吁嗟世多耳食流，传闻傅会葬衣冠。", "持短入长空有术，投鼠忌器垂大闲。由来尺八不足恃，衍水匿迹馀悲叹。", "秋风九月拂征鞍，想像萧萧易水寒。当时壮士不复返，安得若斧留山巅。", "徒令千秋吊古人，恨不终从鞠武言。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"水调歌头","p":"","d":"宋代","a":"陈敷","c":["明月双溪上，胜景号金华。当年此夕，多少鸾凤杂云霞。共拥飘摇倦伯，来作人间英杰，王谢旧名家。纶綍妙文采，帷幄富忠嘉。", "圣天子，形梦寐。眷尤加。麒麟烟上早晚，丹陛听宣麻。鼎袖无穷勋业，岁岁薰风日永，萱秀北堂花。潋滟绮筵酒，寿算等胡沙。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"九日期登大慈恩寺阁不果寄献吉","p":"","d":"明代","a":"徐祯卿","c":["怅忆青莲宇，今朝黄菊开。遥知远公笑，不见白衣来。", "窈窕人天阁，峥嵘日月回。山川纷楚望，城阙动秋哀。", "岘首羊公石，淮阴戏马台。风烟那可即，逸兴杳难裁。", "强负登楼作，虚传落帽才。此时遥独酌，念尔重悠哉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虞美人","p":"","d":"宋代","a":"冯时行","c":["芳菲不是浑无据。只是春收取。都将酝造晚风光。百尺瑶台、吹下半天香。", "多愁多病疏慵意。也被香扶起。微吟小酌送花飞。更拼小屏幽梦、到开时。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"省中二首 其二","p":"","d":"宋代","a":"王安石","c":["大梁春雪满城泥，一马常瞻落日归。身世自知还自笑，悠悠三十九年非。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠寻贤赵相士","p":"","d":"宋代","a":"王柏","c":["赤脚佯聋术有神，贤才未必要贤寻。", "寻贤牌子非贤物，自是君王坐右箴。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"桐柏山黄法师斋","p":"","d":"宋代","a":"高似孙","c":["羽人归丹丘，轻房冒苍顶。", "云飞北斗坛，瀑洗洪崖井。", "三更火交坎，八十雪垂领。", "深香熨玉斧，淑气回丹鼎。", "彼空此亦无，物动我自静。", "灼知乔松辈，元涉义老境。", "一来受清涤，内悟开微儆。", "请添无为香，上有萧台景。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"金菊对芙蓉 抵家","p":"","d":"清代","a":"赵熙","c":["雁外青山，马头黄叶，嘉州两日三荣。算程程归梦，节节离声。", "菊花催老悲秋客，误几人、身后诗名。一鞭残照，中原北望，前世西清。", "无策消遣馀生。集锦江耆旧，各各渊明。唱迷阳旧曲，有恨谁听。", "行装一卸鸦先喜，向枝头、如唤樵青。寸心遥夜，屋梁月落，山火寒星。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"病起","p":"念奴娇","d":"清代","a":"黄之隽","c":["屏低六扇，耐朝来、惯度药炉烟影。著背寒生帘不捲，阴雪瓦棱犹剩。", "炙炭才红，呵毫未黑，懒趣唯耽静。谁来寻伴，小窗天气初暝。", "同是千里依人，柔情绕指，为惜天涯病。流水年光如梦里，孤负灯前人醒。", "串断喉珠，字消心篆，绣被多时冷。笑拈图画，一团梅竹相映。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"寓舍偶题","p":"","d":"明代","a":"甘瑾","c":["四海戎麾满，中原汗马疲。", "龙蛇伤纪岁，麟凤叹非时。", "土贡包茅废，边防羽檄驰。", "杜陵忧国念，蒦闷强裁诗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"点绛唇 闺思","p":"","d":"元代","a":"王寂","c":["疏雨池塘，一番雨过香成阵。海榴红褪。燕语低相问。冰簟纱ε，玉骨凉生润。沈烟喷。日长人困。枕破斜红晕。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"庐山道中 其三","p":"","d":"宋代","a":"李彭","c":["三年不饮虎溪水，一笑来尝鹰爪芽。岑寂仲堪谈易地，祇馀苍藓藉残花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"落花五十首 其二","p":"","d":"明代","a":"沈周","c":["飘飘荡荡复悠悠，树底追寻到树头。赵武泥涂知辱雨，秦宫脂粉惜随流。", "痴情恋酒粘红袖，急意穿帘泊玉钩。欲拾残芳捣为药，伤春难疗个中愁。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"京口阻雨","p":"","d":"清代","a":"林寿图","c":["苍然寒色暮烟横，跕跕飞鸢与水平。三日塔铃呼断渡，一江帆叶贴依城。", "远钟自出南朝寺，晓角如鏖北府兵。破费千钱京口酒，醉看高浪驾长鲸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南天窝授竹影题用徐天池香烟韵七首 其五","p":"","d":"明代","a":"王夫之","c":["凭阑觌面不相知，邂逅晴窗瞥见时。浅黛斜分临晓镜，落花轻惹上蛛丝。", "萍开绿水鱼情得，叶坠幽光鸟梦奇。活色暗香难举似，浮沤目醉共清嬉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"江行杂咏十首 其六","p":"","d":"明代","a":"江源","c":["路长寄书少，水涸归舟迟。渔子团栾乐，焉知人别离。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"重阳","p":"","d":"元代","a":"王懋德","c":["拂却京尘理去舟，閒云千里水悠悠。醉来欲落龙山帽，犹恐黄花笑白头。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题沈周写生二十四种 其十二 葱","p":"","d":"清代","a":"弘历","c":["岭久传西域，盘仍佐五辛。巳知根似玉，谁辨下生银。", "标倩含朝露，纽芽报早春。可怜洛阳狱，陆续独思亲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"亲戚小集","p":"","d":"宋代","a":"范成大","c":["避湿违寒不出门，一冬未省正冠巾。", "月从雪后皆奇夜，天向梅边有别春。", "秉烛登临空语旧，拥炉情味莫怀新。", "荣华势利输人惯，赢得尊前现在身。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"镫下","p":"","d":"清代","a":"陈梓","c":["积阴镫下焰，独坐冷添衣。江阔书难度，峰高梦不归。", "耳听寒食近，发为故园稀。莫是愁城恼，多缘酒力微。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寿王仲锡臬宪 其十四","p":"","d":"明代","a":"释今无","c":["智珠抛掷古皇前，精白为心自永年。不羡阆风餐石脑，邦之司直足人传。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"长相思 无题","p":"","d":"明代","a":"史鉴","c":["花满枝。蝶满枝。客舍恹恹卧病时。愁闻春鸟啼。", "为相思。苦相思。相别常多相见稀。缠绵无了期。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浣溪纱","p":"","d":"清代","a":"吕碧城","c":["风籁鸣哀起翠条，撩人心绪涨秋潮，仙源回望转无聊。", "去去莫教重顾影，行行何必更停桡，愁山怨水一身遥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"六合别俞邦诚","p":"","d":"明代","a":"庄昶","c":["孤舟一雨带秋开，何处弓旌万里来。已分深山甘朽木，岂知优诏起非才。", "人间百事添霜鬓，老去虚名愧钓台。把手欲将离别句，不胜千古送秋怀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"灵芝观上人房植紫竹一本覆屋其上以庇朝日顾","p":"","d":"宋代","a":"毛滂","c":["阶前紫玉似人长，可怪龙孙久未骧。", "第放烟梢出檐去，此君初不畏风霜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红 其五 赠潘原白兼题新居，五叠前韵","p":"","d":"清代","a":"董元恺","c":["烂漫才华，惊人句、潘江涌出。尽少年、狂歌作达，外疏中密。", "红粉一生三妇艳，黄庭五色千枝笔。更清泉、白石寓经纶，谁堪匹。", "楹与桷，施丹漆。亭与阁，凌云日。恰满樽桑落，堆盘芋栗。", "招隐小山俱是桂，高吟药圃宁须术。人诸君、击剑复弹棋，纵横术。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"日本谣十二首 其五","p":"","d":"近代","a":"郁达夫","c":["名隶昭阳供奉班，宫词巧制念家山。劫来源氏人争说，曾使君王一破颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽杨子美侍郎 其一","p":"","d":"宋代","a":"孙应时","c":["游刃刀无缺，韬光玉自温。世途犹砥柱，士论亦龙门。", "仁者宜三寿，天乎遽九原。老成周雅叹，此事更谁论。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过秦楼 寄秦都御史屿湖","p":"","d":"明代","a":"夏言","c":["徐孺亭边，滕王阁畔，旧识中丞开府。燕雀春闲，鱼龙夜静，白昼满城箫鼓。", "时看节钺临戎，宫墙较士，笑谈樽俎。有邦人报道，十郡兵销，九江度虎。", "望故园、宝泽楼成，琼恩堂启，轮奂翚飞百堵。仰荷皇恩，钦承帝敕，经画有烦地主。", "庐阜风烟，灵峰云气，壮观大江今古。今非才遭际，合家岂堪霖雨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"八月二十二日嘉州大阅","p":"","d":"宋代","a":"陆游","c":["陌上弓刀拥寓公，水边旌旆卷秋风。", "书生又试戎衣窄，山郡新添画角雄。", "早事枢庭虚画策，晚游幕府媿无功。", "草间鼠辈何劳磔，要挽天河洗洛嵩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"挽胡团王先生诗 其二","p":"","d":"宋代","a":"韩淲","c":["著述钦成说，叮咛忆绪言。不期捐几杖，无复贲丘园。", "行旐村前路，丰碑屋外原。形容惭识浅，相挽只馨吞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渔父词","p":"","d":"宋代","a":"王庭圭","c":["冥冥江雨湿蓑衣，夜上高岩宿翠微。梦断一声烟草绿，遥闻款乃扣舷归。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"满江红","p":"","d":"宋代","a":"卢炳","c":["碧眼真仙，算元住、蓬莱宫里。记当日、等闲跨鹤，人间游戏。要把忠勋扶帝业，更将姓字联宗系。拥朱轮、特地为民来，诗书帅。", "千里地，都和气。十万户，生欢喜。祝黄堂眉寿，歌谣鼎沸。莫惜春醅供燕豆，便承芝检朝天陛。看云屏、隔坐并貂蝉，双清贵。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"朱太史元价以巧夕后五日社集斋头时沴异弥数旬矣是夕雨月交飞阴晴递换诸同好皆有愁霖之赋余得短律二章 其一","p":"","d":"明代","a":"张萱","c":["星联杓极北，天漏日华东。下马歌匏叶，逢人问菊藭。", "雷声犹破块，蟾影却吹风。变幻由来事，阴晴一瞬中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"石门","p":"","d":"元代","a":"元好问","c":["两崖横绝倚山垠，草径低迷未可分。", "潭影乍从明处见，竹香偏向静中闻。", "石林万古不知暑，茅屋四邻惟有云。", "曳杖行歌羡樵叟，此生何计得随君。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"歌","p":"","d":"南北朝","a":"江淹","c":["芳洲之草行谷暮。", "桂水之波不可渡。", "绝世独立兮报君子之一顾。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上外祖李竹坡先生致尚宝政二十四韵","p":"","d":"明代","a":"王慎中","c":["国运开贞泰，今王礼旧耆。颁旌招野伏，惊代擅雄姿。", "邦俊推公望，朝章属令仪。丘樊驰束帛，海峤动纶丝。", "玉署初移宠，金扉后命贻。西垣瞻日殿，内阙切云司。", "雨露青冥润，弁缨象纬疑。秪言翔岳鷟，讵意曳涂龟。", "道大经徇禄，几先果避时。竟忘魏阙眷，不废考槃词。", "临组惟三揖，封章恳一辞。皇心揆赤悃，温诏下彤墀。", "计决群贤早，名高一代垂。沧波薄赤绂，黄发狎青鹥。", "栖谷情自得，还山迹信追。直嗤少室出，谁赋北山移。", "茑户琴书暇，筠庄岁月迟。江天疏远目，花鸟怯新诗。", "傲世南阳蠖，寻仙绮里芝。瑶兰湘畹纫，玉树谢庭枝。", "峻节元齐杜，养真亦寻雌。登龙汉士慕，歌凤楚狂悲。", "尚想篇翰接，终虚几杖随。因风敷此曲，遥望碧云涯。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"彭府君夫人罗氏挽诗 其一","p":"","d":"宋代","a":"李弥逊","c":["擢秀芝兰畹，来嫔诗礼庭。好羞贫更洁，寿发短犹青。", "秦号封方宠，蓬瀛驾不停。天风助哀怨，吹雨湿丹铭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"辛卯重阳前一日风雨","p":"","d":"当代","a":"傅义","c":["正愁风雨近重阳，日课难维千步强。多谢天公犹恤老，教将斗室作康庄。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠别查韬荒 其九","p":"","d":"明代","a":"屈大均","c":["岂敢多求友，交君已不孤。谗言从贝锦，清鉴自冰壶。", "菡萏双峰出，云霞一气敷。繇来不离别，有道在虚无。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"示同志","p":"","d":"宋代","a":"刘克庄","c":["旋入洛中新保社，稍增汾曲旧田庐。", "市朝幸免髠钳我，尸祝何烦俎豆予。", "静看芭蕉身不实，健忘椰子腹无书。", "故人远致郫筒饷，待约邻翁共破除。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"湘中四咏 其三 鹧鸪","p":"","d":"明代","a":"杨基","c":["湘江两岸无茅宇，湘竹阴阴覆江渚。春来未听一声莺，只有鹧鸪啼暮雨。", "怜渠亦是他乡客，苦向人啼行不得。纵教行得也消魂，那个行人不头白。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"饮仲诚㭨瓢","p":"","d":"元代","a":"刘因","c":["君家瓠落无所容，江湖谁辨平生胸。海南佳气久郁塞，滟滪似喜今相逢。", "前年对酒面发红，今年对酒气如虹。江山万古骚人国，跬步便与华胥通。", "河间古儒病我枸，闻我一饮喜气浓。平生得意南湖张，此意颇与河间同。", "太古洼尊老无底，一朝倾倒何由供。醉乡千年有此客，鸟歌蝶舞春濛濛。", "醉翁之意不在酒，宛如琴意非丝桐。太和风境无酩酊，洛阳楼阁高玲珑。", "泠然仙驭一杯水，眼中渺渺无极翁。西家伯伦瞽且聋，东家醉死王无功。", "酒中醒境渠未识，冰壶秋月昆崙峰。举杯唤月来胸中，人间白日浮云空。", "五岭山高云几重，朱崖灭没南飞鸿。玄鹤翩翩渺何许？操瓢径访眉山公。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"琐窗寒 空闺","p":"","d":"清代","a":"姚燮","c":["绿又阴阴，重帘静窣，奈无人个。蟏尘罥网，尚飐几丝绒唾。", "认分明、花朝梦回，贴奁解鬓提梳坐。恁小桃待绽，风鹃声紧，丽韶催过。", "无那。金鱼锁。任蠹蚀鞋香，雁抛钿朵。残棉断粒，最苦狸寒莺饿。", "罨银床、秋梧自鸣，更无杼柚相应和。怕眠时、独影凄凉，掩却霜篝火。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南斋病卧","p":"","d":"宋代","a":"刘敞","c":["香卷风飘幌，灯昏雨映帘。客愁浑不寐，更觉漏声添。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"谢蔚宗木棉","p":"","d":"宋代","a":"沈辽","c":["峤南地熟气如烟，木华蒙茸散为绵。使君作紬远相寄，表似夷锦红欲燃。", "病士榻上残青毡，山中苦寒多破穿。使君相赠何可言，困来不妨伸脚眠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东邻二首 其一","p":"","d":"宋代","a":"唐庚","c":["即今乐事属墙东，岁晚何曾酒盏空。白蜜已输仍节近，红藤未动况年丰。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寓斋","p":"","d":"宋代","a":"李吕","c":["萍梗天地间，初不异万物。", "可能发深省，惟有一事实。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送王允常佥事之广东","p":"","d":"明代","a":"王鏊","c":["柳叶桄榔五岭南，使君曾此驻帷襜。法冠直指新峨廌，包匦生黎旧贡蚺。", "不信鳄鱼还作恶，只应泉水便名廉。殊方风土须珍重，莫为溪山久滞淹。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"致一斋述事","p":"","d":"宋代","a":"范成大","c":["文书烟海困浮沉，不觉盘跚百病侵。", "偶问客年惊我老，忽闻莺语叹春深。", "今朝麦粒黄堪麪，几日秧田绿似针。", "除却一＊春雨足，眼前无物可关心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南内朝贺归呈同官","p":"","d":"唐代","a":"韩愈","c":["薄云蔽秋曦，清雨不成泥。罢贺南内衙，归凉晓凄凄。", "绿槐十二街，涣散驰轮蹄。余惟戆书生，孤身无所赍。", "三黜竟不去，致官九列齐。岂惟一身荣，佩玉冠簪犀。", "滉荡天门高，著籍朝厥妻。文才不如人，行又无町畦。", "问之朝廷事，略不知东西。况于经籍深，岂究端与倪。", "君恩太山重，不见酬稗稊。所职事无多，又不自提撕。", "明庭集孔鸾，曷取于凫鹥.树以松与柏，不宜间蒿藜。", "婉娈自媚好，几时不见挤。贪食以忘躯，鲜不调盐醯。", "法吏多少年，磨淬出角圭。将举汝愆尤，以为己阶梯。", "收身归关东，期不到死迷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"赠伯澜","p":"","d":"清代","a":"丘逢甲","c":["乘兴曾游大海东，樱花开处唱秦风。归来小试经纶手，一卷周官补考工。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西瓜","p":"","d":"宋代","a":"顾逢","c":["多自淮乡得，天然碧玉团。破来肌体莹，嚼处齿牙寒。", "清敌炎威退，凉生酒量宽。东门无此种，雪片簇冰盘。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哀江南八首 其八","p":"","d":"明代","a":"谢榛","c":["氛祲频年动，东南尽处看。海摇千舰出，兵犯七闽寒。", "杀伐宁无定，凭陵信有端。遥闻日本使，犹自贡长安。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"句","p":"","d":"宋代","a":"孙月境","c":["莫欺春到荼醾尽，更有杨花落后飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"忆袁氏姊","p":"","d":"近代","a":"黄仁基","c":["炮声晚未休，云自苏山北。老姐招不来，守此山中宅。", "避寇互来往，久聚忘主客。熟知寇未至，我与姐复隔。", "去年六月晨，倚涧方朝汲。奔雷赴其前，巨弹背后坼。", "跳波溅衣襟，两耳为之塞。至今水边石，有铁尚深黑。", "性命才脱遗，悲愤又横臆。独坐对苍茫，倾耳待其寂。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"食荠有感二首 其二","p":"","d":"明代","a":"韩雍","c":["宦辙驱驰二十霜，迁官今喜到南荒。消閒遂我吟诗兴，取乐留宾索酒尝。", "薇省漫言勋业减，金瓯谁覆姓名香。食前方丈成何用，不若贫家菜味长。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"双楠送何致远归陕西二首 其一","p":"","d":"宋代","a":"张嵲","c":["乱后生涯似转蓬，何堪送客值秋风。含悽试看东归路，只见青山绕汉中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和春深二十首 其十","p":"","d":"唐代","a":"白居易","c":["何处春深好，春深经业家。唯求太常第，不管曲江花。", "折桂名惭郤，收萤志慕车。官场泥补处，最怕寸阴斜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬纪伯紫即送其之晋阳","p":"","d":"明代","a":"杨思圣","c":["大江势浩浩，南北错舆舱。往往异人出，结交在一言。", "我家漳水涯，子居白下门。素心各有托，意气自孤骞。", "相逢长安陌，双眼望朝暾。长安多王侯，第宅若云屯。", "绮筵罗珍食，朱缨驰华轩。宾从纷遝沓，附势如灼薰。", "静交有吾徒，冥然绝世喧。不就唐生决，肯借金张援。", "时时顾蓬径，樽酒共讨论。落日登高台，慷慨天为昏。", "击筑声泪下，重招烈士魂。忽整晋阳驾，贻诗重玙璠。", "以俪魏给事，无乃非其伦。感君安所赠，此意贵永敦。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"寄叶解元","p":"","d":"宋代","a":"韩淲","c":["醉中曾写雪色壁，非此主人无此客。夜寒烟雨池阁深，秉烛看梅忘堕帻。", "春来相望鹅湖边，桃花满地松拂天。抱琴挟书过飘泉，想君风度尤翩翩。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"眼儿媚","p":"","d":"宋代","a":"赵桓","c":["宸传三百旧京华。仁孝自名家。一旦奸邪，倾天拆地，忍听琵琶。", "如今在外多萧索，迤逦近胡沙。家邦万里，伶仃父子，向晓霜花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"涿郡览古 其五","p":"","d":"清代","a":"弘历","c":["琼楼边洞乘云去，璧水琴高跨鲤来。此事今胡艰目睹，列仙传记果真哉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"萧洒桐庐郡十绝 其四","p":"","d":"宋代","a":"范仲淹","c":["萧洒桐庐郡，公馀午睡浓。人生安乐处，谁复问千钟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"上黄端明寿诗以竚期三入后一品见玄孙为韵","p":"","d":"宋代","a":"李吕","c":["骨秀类天人，神清若岩电。", "寿与山岳齐，造物兹可见。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"初夏别墅","p":"","d":"宋代","a":"林表民","c":["池馆春方谢，连朝雨似烟。", "乱荷藏睡鹭，繁木集嘶蝉。", "地僻观书乐，心清得句玄。", "野僧时过我，携手弄云泉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杂感六首 其二","p":"","d":"宋代","a":"陆游","c":["士生诵二典，恍若生唐虞。升降奉玉帛，可否闻吁俞。", "阙里得其传，功与造化俱。孰知千载后，乃尊重译书。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"书韩隐人壁","p":"","d":"宋代","a":"赵湘","c":["雨黑径垂莎，全家在薜萝。", "树高穿井出，门掩烧痕过。", "写易澌生砚，悬壶月上柯。", "近来山屐老，枯齿旅无多。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵蔡叔清六言二首其","p":"","d":"宋代","a":"赵蕃","c":["陶潜必遗俗患，侯喜新有诗声。", "容我深藏蹇步，看君大展修程。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"夏日游永光寺","p":"","d":"明代","a":"李英","c":["石径经行处，禅堂爱客吟。残花含雨落，新竹入园深。", "松偃苔能上，山高日易沈。僧来同把袂，半偈去尘心。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"浮邱八景 其四 大雅堂","p":"","d":"明代","a":"邓时雨","c":["太史藏书开石室，超然云构傍丹邱。追思雅颂成周日，海内争誇共唱酬。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"即事","p":"","d":"明代","a":"张穆","c":["门前溪水接平湖，酒舍渔家共一区。莲舫载书疑太乙，羊裘垂钓笑潜夫。", "蘋风不定蜻蜓立，柳色难分翡翠俱。沧海新来说深浅，他年将更问麻姑。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题诗意图","p":"","d":"元代","a":"陶宗仪","c":["杖藜访友趁萧閒，采药山深待未还。流水石桥松影合，溪童指点乱云间。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"东郊","p":"","d":"宋代","a":"郭祥正","c":["东郊怅望惜春归，颇觉年来万事非。不奈离愁须觅酒，得闻歌响却沾衣。", "蜜蜂捕蕊穿花去，巢燕寻泥拍水飞。物态风光能几许，老无忧患世人稀。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"咏史二十二首 其十八 后梁太祖","p":"","d":"宋代","a":"赵戣","c":["未必黄明在，终令丑口亡。难教疏网漏，不直败毡藏。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"虎丘寺同子与孔嘉淳父公瑕伯龙舍弟送别袁鲁望张伯起会试北上得阳字","p":"","d":"明代","a":"王世贞","c":["绝巘精蓝半夕阳，清尊别思倚苍茫。凭栏顿喜云霄近，结驷毋惊道路长。", "池拥双龙元是剑，天回北斗尽成章。因窥雁塔岧峣里，似有题名在上方。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"袷乡回升楼","p":"","d":"隋代","a":"佚名","c":["涣号爰发，皇敷至仁。", "幽隐尽达，洪德日新。", "国容肃穆，天宇晏温。", "惠浃四远，富寿无垠。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"临江仙 其三用欧阳永叔夏景韵","p":"","d":"明代","a":"龚鼎孳","c":["谁遣封姨吹画楫，晴湖蹴作涛声。轻寒罗袖最分明。", "催花落尽。此别太生生。", "薄福东君应自悔，一春云幔风旌。双蛾小皱縠纹平。", "夕阳无赖，不管钿钗横。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"刘太尉琨伤乱","p":"","d":"南北朝","a":"江淹","c":["皇晋遘阳九，天下横氛雾。", "秦赵值薄蚀，幽并逢虎据。", "伊余荷宠灵，感激狥驰骛。", "虽无六奇术，冀与张韩遇。", "宁戚扣角歌，桓公遭乃举。", "荀息冒险难，实以忠贞故。", "空令日月逝，愧无古人度。", "饮马出城濠，北望沙漠路。", "千里何萧条，白日隐寒树。", "投袂既愤懑，抚枕怀百虑。", "功名惜未立，玄发已改素。", "时哉苟有会，治乱惟冥数。"],"tags":["抒情"],"z":"","y":"注释 ①阳九：厄运。 ②薄蚀：日月相掩食。此指灾难......","s":"","k":"诗"},
  {"t":"自安仁至豫章途中杂兴十九首 其三","p":"","d":"宋代","a":"赵蕃","c":["极目荒陂十里馀，坏塍依约旧犁锄。问言业薄无牛力，更说州家催积租。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂二百零五首 其二十一","p":"","d":"宋代","a":"释正觉","c":["深明无底，灵异无根。案山行尽，不见有家。识浪沥乾，不见有己。", "石女掣开金锁钥，木人拨动玉轮机。方信道从佛口生，法化生得佛法分。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"有鸟二十章 其十","p":"","d":"唐代","a":"元稹","c":["有鸟有鸟名为鸮，深藏孔穴难动摇。鹰鹯绕树探不得，随珠弹尽声转娇。", "主人烦惑罢擒取，许占神林为物妖。当时幸有燎原火，何不鼓风连夜烧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"答瘿公","p":"","d":"清代","a":"黄节","c":["直知无俚惟听曲，已笑何缘却赠词。贺老琵琶李谟笛，不堪重为念奴悲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鳙溪行","p":"","d":"宋代","a":"王炎","c":["小溪一曲山四合，溪边杨柳藏门阑。", "当时玉人在花下，对花窈窕矜红颜。", "一双白璧不可聘，许我结佩乘青鸾。", "我时年少气方锐，自负落笔翻波澜。", "谓趁春风上霄汉，可以终老同清欢。", "不知辛苦得一第，始见崎岖行路难。", "有如萍草无根蒂，二纪流落江湖间。", "莫年通籍入金马，虎豹嗔人窥九关。", "天边失脚身堕地，春风破浪扁舟还。", "云軿未几舍我去，空委玉骨埋青山。", "重来溪上事皆变，惆怅齐眉难再见。", "王母麻姑安在哉，过眼百年皆露电。", "老身老子恩义深，不为向来花映面。", "花枝一谢明年开，玉人一去何时回。", "人今不见花亦尽，至此终日空徘徊。", "百川宁有西流水，万古滔滔同一轨。", "不堪回首细绎思，临没之言犹在耳。", "蜀乡有凤空求凰，秦树无乌共将子。", "年来年去春复冬，眩生有尽情无穷。", "一泓清泪洒不断，四山萧飒来悲风。", "惟有老人老更健，年过九十如霜松。", "尊则吾母舅，亲又吾妇翁。", "收泪相劳问，停车少从容。", "悲思无益不自禁，暂时借酒浇心胸。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"酬韩质舟行阻冻","p":"","d":"唐代","a":"韦应物","c":["晨坐枉嘉藻，持此慰寝兴。中获辛苦奏，长河结阴冰。", "皓曜群玉发，凄清孤景凝。至柔反成坚，造化安可恒。", "方舟未得行，凿饮空兢兢。寒苦弥时节，待泮岂所能。", "何必涉广川，荒衢且升腾。殷勤宣中意，庶用达吾朋。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题信州半月岩","p":"","d":"宋代","a":"程公许","c":["岩际半轮月，神工幻怪奇。", "本来无显晦，何自有盈亏。", "岚雾凝蟾彩，藤萝影桂枝。", "能令万里客，为尔忆峨眉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"渡淮即事","p":"","d":"元代","a":"萨都剌","c":["杨花点点冲帆过，燕子双双掠水飞。淮上渔人閒不得，船头对结绿蓑衣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"松门","p":"邵公济求泰定山房十诗","d":"宋代","a":"苏籀","c":["昼扃熟鹿守，晨启素鸦驯。", "延陵挂孤剑，吴月照峩岷。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"哭夫诗百首","p":"","d":"明代","a":"薄少君","c":["海内风流一瞬倾，彼苍难问古今争。哭君莫作秋闺怨，《薤露》须歌铁板声。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"自宜兴过溧阳","p":"","d":"宋代","a":"赵蕃","c":["荆溪路入白云径，势与松江相并宽。政以楫轻忧逆浪，忽逢风转起飞翰。", "须臾又报一舍过，转盻应无百里难。却恨铜官易成远，不容双目细留看。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"遣兴十二首 其八","p":"","d":"明代","a":"林大钦","c":["已见繁华悲眼前，又闻陵谷变桑田。南州野士居郑谷，不吃鱼粱吃紫烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再登斗野亭路旧韵寄太虚","p":"","d":"宋代","a":"李之仪","c":["北舟揽黄氏，楚楚不自平。故步聊低回，新月微风清。", "蛙声语莫下，泡涌浮修甍。何在超世游，翳路情难倾。", "西堂梦不到，春草还复生。长年浸枯蘖，有时怀层城。", "适从吴儿炊，又作淮人烹。皇皇遍诸侯，吾人愧安行。", "独抱照乘姿，花枝似相明。拂衣归待旦，南州逢顾荣。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"宫词","p":"","d":"明代","a":"朱权","c":["寒蝉泣露曳秋声，杨柳枝头淡月明。", "半掩笼门怕关上，今宵犹恐幸车行。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送边将","p":"","d":"唐代","a":"李咸用","c":["天骄频犯塞，铁骑又征西。臣节轻乡土，雄心生鼓鼙。", "地寒花不艳，沙远日难低。渐喜秋弓健，雕翻白草齐。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"春帖子词","p":"","d":"宋代","a":"苏轼","c":["草木渐知春，萌芽处处新。", "从今八千岁，合抱是灵椿。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"吊陈鲁斋兄丈","p":"","d":"清代","a":"许传霈","c":["携杖萝岩下，高风羡岸然。青蓝联旧契，葭莩托良缘。", "孰意今把袂，为时未届年。大风一曲后，遽尔渺云烟。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈颂六十首 其三十三","p":"","d":"宋代","a":"释昙华","c":["西天四七，唐土二三。尽向者里钉桩摇橹，新东林为你诸人解缆放船。", "未说超宗异目，若得齐眉共瞩。亦可明窗下安排，未免栏腮掴出。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"怨诗","p":"","d":"唐代","a":"孟郊","c":["试妾与君泪，两地滴池水。", "看取芙蓉花，今年为谁死！"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"偈二首 其一","p":"","d":"宋代","a":"释法因","c":["天上月圆，人间月半。七八是数，事却难算。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"秋途暮息","p":"","d":"宋代","a":"曾丰","c":["密密初秋雨，蒙蒙欲暮天。", "牛羊争欲下，车马敢求前。", "蟋蟀挑孤咏，梧桐搅独眠。", "及身无一事，梦到汗漫边。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"西湖明月引/江城梅花引","p":"","d":"宋代","a":"刘埙","c":["江村烟雨暗萧萧。涨寒潮。送春桡。目断京尘，何日听鸾箫。金雀觚棱千里外，指天际，碧云深，魂欲飘。薰炉炷愁烟尽销。酒孤斟、谁与招。满怀情思，任吟笺、赋笔难描。惆怅山风、吹梦老秋宵。绿漾湖心波影阔，终待到，借垂杨、月半桥。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"杀羊岩","p":"","d":"清代","a":"姚燮","c":["旷尽险重发，目眩心不持。杀羊名其岩，于义竟难知。", "殷红抛暗云，林果偶离枝。跳涧来碧猴，急攫无少迟。", "穷天寡悦象，生气蚀已亏。好杀不屠狼，残忍终奚为？", "初平百卷石，鞭血犹丝丝。要媚山鬼妆，泼草成胭脂。", "薄袖难障风，似有微腥吹。且就乌桕坪，一晞阳阿晖。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送顾军咨归梁溪","p":"","d":"明代","a":"高启","c":["新柳休攀短短条，离愁似雪未能销。", "春回废苑还芳草，人渡空江正落潮。", "德曜宅前今独去，平津门下旧相招。", "重来莫在花开后，拟听狂歌醉几朝。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题日出雨脚图二首","p":"","d":"宋代","a":"韩元吉","c":["绝壑春林映绿，半山晓雾迷红。", "长忆西岩梦觉，小舟欸乃声中。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"山居杂咏 其十七 折藕","p":"","d":"明代","a":"成鹫","c":["浮生聊寄迹，决绝复奚辞。一洗尘根净，方知涅不缁。", "可堪盈手赠，偏与素心宜。大地同饥渴，于君有所思。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"华阳吟三十首","p":"","d":"宋代","a":"白玉蟾","c":["片饷工夫炼汞池，一炉猛火夜烧天。", "忽然神水落金井，打合灵砂月样圆。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"十月九日与客饮忽记去年此时自锦屏归山南道","p":"","d":"宋代","a":"陆游","c":["去年纵猎韩坛侧，玉鞭自探南山雪。", "今年痛饮蜀江边，金杯却吸峨眉月。", "竹枝歌舞新教成，凄怨传得三巴声。", "城头筑观出云雨，峨眉正与阑干平。", "酒酣诗就掷杯去，醉蹋玻璃江上路。", "悬知幽涧断桥边，已有梅花开半树。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"送曹应则归省","p":"","d":"明代","a":"如兰","c":["壮志欲飞腾，扶摇北海鹏。双亲俱未老，一弟已为僧。", "远水浮春棹，虚窗坐夜灯。明朝望乡国，遥指白云层。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"梅花 其二","p":"","d":"宋代","a":"司马光","c":["塞北为君戍，江南是妾家。遥知关外雪，只似岭头花。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"南阳春日十首 其四","p":"","d":"宋代","a":"陈舜俞","c":["花前惆怅转难平，屈指光阴已半生。犹把此身尝患难，不知何日得功名。", "未安去住千丝乱，已去悲欢一梦惊。拟入醉乡销此恨，快风无故析春酲。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"二风诗。治风诗五篇。至正","p":"","d":"唐代","a":"元结","c":["（古有正王，能正慎恭和以安上下，故为《至正》之诗", "一章四韵八句）", "为君之道，何以为明？功不滥赏，罪不滥刑；", "谠言则听，谄言不听；王至是然，可为明焉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次俞子中病起韵","p":"","d":"元代","a":"凌云翰","c":["桐江清隐客，头白太平时。每唱紫芝曲，闲临碧落碑。", "无愁何用解，示病不须医。恐有登高兴，先期报我知。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"和雁湖先生病起自警八章","p":"","d":"宋代","a":"程公许","c":["葆光悟老子说，游仙续景纯诗。", "木铣可使石透，盘水犹严手持。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"丰城送成父弟还玉山三首 其一","p":"","d":"宋代","a":"赵蕃","c":["溪上同舟送，江头独步归。秋风方落木，客路要添衣。", "故旧询安否，形容话瘠肥。吾行犹许远，尔去复谁依。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"读次文渼陂诗","p":"","d":"宋代","a":"王安中","c":["白发郎潜旧令君，东轩携酒几回登。当初天上化凫舄，今日人间下马陵。", "边地久无能赋笔，县斋新有读书灯。昔游零落岑参在，故语流传许十称。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"证道歌","p":"颂证道歌","d":"宋代","a":"释印肃","c":["一超直入如来地，自是众生不了利。", "行住坐卧总皆真，逐末兴心成执滞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"过天津访万中丞伯修四首 其四","p":"","d":"明代","a":"胡应麟","c":["玉帐梅花照叵罗，南楼吹笛夜如何。中丞节钺行三辅，大将楼船出九河。", "赤日桑乾穷兕虎，青天蒲类息蛟鼍。燕然片碣题铭处，万丈穷崖绝顶磨。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"练川杂诗四首 其四","p":"","d":"元代","a":"张仲深","c":["江深风物异，归计每逡巡。有酒愁难破，吟诗兴自神。", "枯萑晴似雪，独鹤夜如人。遁世当无闷，行藏一任真。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"除夕伍汝真用待隐园韵即席次答五首 其一","p":"","d":"明代","a":"王守仁","c":["一年今又去，独客尚无归。人世伤多难，亲庭叹久违。", "壮心都欲尽，衰病特相依。旅馆聊随俗，桃符换早扉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"鹤冲天 次柳屯田韵","p":"","d":"清代","a":"吴湖帆","c":["明蟾海上。比目颙凝望。离会两难期，还相向。爱浪恩波送，秋碧顿回春荡。", "名无关得丧。红粉禅心，漫道色生空相。芳盟暗忆，消息风魔情障。", "画里唤真真，如亲访。许似桐花凤，秦楼愿，箫吹畅。", "凭阑争一饷。好景流连，便尔倚偎随唱。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题淩云《长沙妓》传奇","p":"满江红","d":"清代","a":"黄之隽","c":["似我缘悭，浑不信、当年淮海。人老去、尚招烟月，粉恩香爱。", "一管罗浮仙史笔，写生墨沈随风洒。使怜才、一点翠楼心，居然在。", "珠十斛，谁堪买。花四照，谁能采。有燕姬梦向，玉堂人拜。", "绣虎始知多巧遇，彩鸾端合酬情债。笑樊川、空手写扬州，无聊赖。"],"tags":[],"z":"","y":"","s":"","k":"词"},
  {"t":"病目初起汪象先太学以玉簪十二馈我即取小军持承露分贮几上觉茅斋秋色种种撩人报以口号二 其二","p":"","d":"明代","a":"胡应麟","c":["荏苒秋光遍六街，玉妃联袂到空斋。军持满插文园露，何似华堂十二钗。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"再次韵赵帅见寄三首","p":"","d":"宋代","a":"陈造","c":["倏晴骤雨寒犹在，约勒群芳未尽开。", "销得燕堂千杖鼓，旋看锦缬裹条枚。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"蜀道","p":"","d":"明代","a":"宗臣","c":["蜀道之难自古今，岂令华发独能任。思家多少玄猿泪，解绶徘徊赤子心。", "秋落舟航巫峡险，人言风雪锦江深。坐来万里谁消息，明月关山处处砧。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"发长安堰","p":"","d":"宋代","a":"叶绍翁","c":["夏老虫声切，晨兴草气香。", "买瓜依绿树，出水{左氵右旱}青身。", "船聚知村近，牛闲觉昼长，", "双凫莲叶荡，无雨故生凉。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"济源上枉舒员外两篇因酬六韵","p":"","d":"唐代","a":"白居易","c":["歇手不判案，举头仍见山。", "虽来鞍马上，不离诗酒间。", "济源三临泛，王屋一登攀。", "犹嫌百里近，祇得十日闲。", "明朝却归府，尘事如循环。", "犹听瑶华曲，稍开风土颜。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"题柳山人壁二首","p":"","d":"宋代","a":"叶适","c":["水北柳六一，家传掷卦灵。", "秋清演渔曲，春近著牛经。", "掩肆花竹秀，排门柑橘馨。", "应怜喜功者，虚要岘山铭。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"次韵友人山居秋日就述鄙怀八首 其五","p":"","d":"元代","a":"王祎","c":["忆昔天子都，三载竟忘归。谓将拾功名，所志非轻肥。", "翻然忽自悔，自售古所讥。归来山中居，坐看双轮飞。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"高士颂九十一首 其六十八 梁鸿","p":"","d":"明代","a":"黄省曾","c":["伯鸾者何，脩远之子。介耻攀龙，贫资畜豕。仰颂逸民，庶追芳趾。", "贞配孟光，骨埋吴土。"],"tags":[],"z":"","y":"","s":"","k":"诗"},
  {"t":"导引","p":"导引","d":"宋代","a":"和岘","c":["气和玉烛，睿化著鸿明。", "缇管一阳生。", "郊禋盛礼燔柴毕，旋轸凤凰城。", "森罗仪卫振华缨。", "载路溢欢声。", "皇图大业超前古，垂象泰阶平。", "岁时丰衍，九土乐升平。", "睹寰海澄清。", "道高尧舜垂衣治，日月并文明。", "嘉禾甘露登歌荐，云物焕祥经。", "兢兢惕惕持谦德，未许禅云亭。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"六州","p":"六州","d":"宋代","a":"和岘","c":["严夜警，铜莲漏迟迟。", "清禁肃，森陛戟，羽卫俨皇闱。", "角声励，钲鼓攸宜。", "金管成雅奏，逐吹逶迤。", "荐苍璧，郊祀神祗。", "属景运纯禧。", "京坻丰衍，群材乐育，诸侯述职，盛德服蛮夷。", "殊祥萃，九苞丹凤来仪。", "膏露降，和气洽，三秀焕灵芝。", "鸿猷播，史册相辉。", "张四维。", "卜世永固丕基。", "敷玄化，荡荡无为。", "合尧舜文思。", "混并寰宇，休牛归马，销金偃革，蹈咏庆昌期。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"十二时・忆少年","p":"十二时・忆少年","d":"宋代","a":"和岘","c":["承宝运，驯致隆平。", "鸿庆被寰瀛。", "时清俗阜，治定功成。", "遐迩咏由庚。", "严郊祀，文物声明。", "会天正、星拱奏严更。", "布羽仪簪缨。", "宸心虔洁，明德播惟馨。", "动苍冥。", "神降享精诚。", "燔柴半，万乘移天仗，肃銮辂旋衡。", "千官云拥，群后葵倾。", "玉帛旅明庭。", "韶濩荐，金奏谐声。", "集休亨。", "皇泽浃黎庶，普率洽恩荣。", "仰钦元后，睿圣贯三灵。", "万邦宁。", "景贶福千龄。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"点绛唇","p":"点绛唇","d":"宋代","a":"王禹","c":["雨恨云愁，江南依旧称佳丽。", "水村渔市。", "一缕孤烟细。", "天际征鸿，遥认行如缀。", "平生事。", "此时凝睇。", "谁会凭阑意。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"越江吟","p":"越江吟","d":"宋代","a":"苏易简","c":["神仙神仙瑶池宴。", "片片。", "碧桃零落春风晚。", "翠云开处，隐隐金舆挽。", "玉麟背冷清风远。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"甘草子","p":"甘草子","d":"宋代","a":"寇准","c":["春早。", "柳丝无力，低拂清门道。", "暖日笼啼鸟。", "初坼桃花小。", "遥望碧天净如扫。", "曳一缕、轻烟缥缈。", "堪惜流年谢芳草。", "任玉壶倾倒。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"踏莎行","p":"踏莎行","d":"宋代","a":"寇准","c":["春色将阑，莺声渐老。", "红英落尽青梅小。", "画堂人静雨濛濛，屏山半掩馀香袅。", "密约沈沈，离情杳杳。", "菱花尘满慵将照。", "倚楼无语欲销魂，长空黯淡连芳草。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"阳关引","p":"阳关引","d":"宋代","a":"寇准","c":["塞草烟光阔。", "渭水波声咽。", "春朝雨霁轻尘歇。", "征鞍发。", "指青青杨柳，又是轻攀折。", "动黯然、知有后会甚时节。", "更尽一杯酒，歌一阕。", "叹人生，最难欢聚易离别。", "且莫辞沉醉，听取阳关彻。", "念故人、千里自此共明月。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"点绛唇","p":"点绛唇","d":"宋代","a":"寇准","c":["水陌轻寒，社公雨足东风慢。", "定巢新燕。", "湿雨穿花转。", "象尺熏炉，拂晓停针线。", "愁蛾浅。", "飞红零乱。", "侧卧珠帘卷。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"江南春・秋风清","p":"江南春・秋风清","d":"宋代","a":"寇准","c":["波渺渺，柳依依。", "孤村芳草远，斜日杏花飞。", "江南春尽离肠远，苹满汀洲人未归。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"夜度娘","p":"夜度娘","d":"宋代","a":"寇准","c":["烟波渺渺一千里，白苹香散东风起。", "日暮汀洲一望时，柔情不断如春水。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"木兰花・玉楼春","p":"木兰花・玉楼春","d":"宋代","a":"钱惟演","c":["城上风光莺语乱。", "城下烟波春拍岸。", "绿杨芳草几时休，泪眼愁肠先已断。", "情怀渐变成衰晚。", "鸾鉴朱颜惊暗换。", "昔年多病厌芳尊，今日芳尊惟恐浅。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"玉楼春","p":"玉楼春","d":"宋代","a":"钱惟演","c":["锦箨参差朱槛曲。", "露濯文犀和粉绿。", "未容浓翠伴桃红，已许纤枝留凤宿。", "嫩似春荑明似玉。", "一寸芳心谁管束。", "劝君速吃莫踟蹰，看被南风吹作竹。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"踏莎行","p":"踏莎行","d":"宋代","a":"陈尧佐","c":["二社良辰，千家庭院。", "翩翩又见新来燕。", "凤凰巢稳许为邻，潇湘烟暝来何晚。", "乱入红楼，低飞绿岸。", "画梁时拂歌尘散。", "为谁归去为谁来，主人恩重珠帘卷。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆钱塘，不是人寰是天上。", "万家掩映翠微间。", "处处水潺潺。", "异花四季当窗放。", "出入分明在屏障。", "别来隋柳几经秋。", "何日得重游。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆钱塘，临水傍山三百寺。", "僧房携杖遍曾游。", "闲话觉忘忧。", "栴檀楼阁云霞畔。", "钟梵清宵彻天汉。", "别来遥礼祗焚香。", "便恐是西方。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆西湖，湖上春来无限景。", "吴姬个个是神仙。", "兢泛木兰船。", "楼台簇簇疑蓬岛。", "野人祗合其中老。", "别来已是二十年。", "东望眼将穿。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆西湖，尽日凭阑楼上望。", "三三两两钓鱼舟。", "岛屿正清秋。", "笛声依约芦花里。", "白鸟成行忽惊起。", "别来闲整钓鱼竿。", "思入水云寒。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆孤山，山在湖心如黛簇。", "僧房四面向湖开。", "轻棹去还来。", "芰荷香喷连云阁。", "阁上清声檐下铎。", "别来尘土污人衣。", "空役梦魂飞。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆西山，灵隐寺前三竺后。", "冷泉亭上旧曾游。", "三伏似清秋。", "白猿时见攀高树。", "长啸一声何处去。", "别来几向画阑看。", "终是欠峰峦。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆高峰，峰上塔高尘世外。", "昔年独上最高层。", "月出见觚稜。", "举头咫尺疑天汉。", "星斗分明在身畔。", "别来无翼可飞腾。", "何日得重登。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆吴山，山上森森吴相庙。", "庙前江水怒为涛。", "千古恨犹高。", "寒鸦日暮鸣还聚。", "时有阴云笼殿宇。", "别来有负谒灵祠。", "遥奠酒盈卮。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆龙山，日月宫中谁得到。", "宫中旦暮听潮声。", "台殿竹风清。", "门前岁岁生灵草。", "人采食之多不老。", "别来已白数茎头。", "早晚却重游。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"酒泉子","p":"酒泉子","d":"宋代","a":"潘阆","c":["长忆观潮，满郭人争江上望。", "来疑沧海尽成空。", "万面鼓声中。", "弄涛儿向涛头立。", "手把红旗旗不湿。", "别来几向梦中看。", "梦觉尚心寒。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"扫市舞","p":"扫市舞","d":"宋代","a":"潘阆","c":["出砒霜，价钱可。", "赢得拨灰兼弄火。", "畅杀我。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"凤栖梧・蝶恋花","p":"凤栖梧・蝶恋花","d":"宋代","a":"丁谓","c":["十二层楼春色早。", "三殿笙歌，九陌风光好。", "堤柳岸花连复道。", "玉梯相对开蓬岛。", "莺啭乔林鱼在藻。", "太液微波，绿斗王孙草。", "南阙万人瞻羽葆。", "后天祝圣天难老。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"凤栖梧・蝶恋花","p":"凤栖梧・蝶恋花","d":"宋代","a":"丁谓","c":["朱阙玉城通阆苑。", "月桂星榆，春色无深浅。", "潇瑟篌笙仙客宴。", "蟠桃花满蓬莱殿。", "九色明霞裁羽扇。", "云雾为车，鸾鹤骖雕辇。", "路指瑶池归去晚。", "壶中日月如天远。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"相思令・相思儿令","p":"相思令・相思儿令","d":"宋代","a":"林逋","c":["吴山青。", "越山青。", "两岸青山相对迎。", "争忍有离情。", "君泪盈。", "妾泪盈。", "罗带同心结未成。", "江边潮已平。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"点绛唇","p":"点绛唇","d":"宋代","a":"林逋","c":["金谷年年，乱生春色谁为主。", "馀花落处。", "满地和烟雨。", "又是离歌，一阕长亭暮。", "王孙去。", "萋萋无数。", "南北东西路。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"霜天晓角","p":"霜天晓角","d":"宋代","a":"林逋","c":["冰清霜洁。", "昨夜梅花发。", "甚处玉龙三弄，声摇动、枝头月。", "梦绝。", "金兽爇。", "晓寒兰烬灭。", "要卷珠帘清赏，且莫扫、阶前雪。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"瑞鹧鸪","p":"瑞鹧鸪","d":"宋代","a":"林逋","c":["众芳摇落独鲜妍。", "占尽风情向小园。", "疏影横斜水清浅，暗香浮动月黄昏。", "寒禽欲下先偷眼，粉蝶如知合断魂。", "幸有微吟可相狎，不须檀板共金尊。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"少年游","p":"少年游","d":"宋代","a":"杨亿","c":["江南节物，水昏云淡，飞雪满前村。", "千寻翠岭，一枝芳艳，迢递寄归人。", "寿阳妆罢，冰姿玉态，的的写天真。", "等闲风雨又纷纷。", "更忍向、笛中闻。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"生查子","p":"生查子","d":"宋代","a":"陈亚","c":["朝庭数擢贤，旋占凌霄路。", "自是郁陶人，险难无移处。", "也知没药疗饥寒，食薄何相误。", "大幅纸连粘，甘草归田赋。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"生查子","p":"生查子","d":"宋代","a":"陈亚","c":["相思意已深，白纸书难足。", "字字苦参商，故要槟郎读。", "分明记得约当归，远至樱桃熟。", "何事菊花时，犹未回乡曲。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"生查子","p":"生查子","d":"宋代","a":"陈亚","c":["小院雨馀凉，石竹风生砌。", "罢扇尽从容，半下纱厨睡。", "起来闲坐北亭中，滴尽真珠泪。", "为念婿辛勤，去折蟾宫桂。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"生查子","p":"生查子","d":"宋代","a":"陈亚","c":["浪荡去未来，踯躅花频换。", "可惜石榴裙，兰麝香销半。", "琵琶闲抱理相思，必拨朱弦断。", "拟续断朱弦，待这冤家看。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"喜迁莺","p":"喜迁莺","d":"宋代","a":"夏竦","c":["霞散绮，月沈钩。", "帘卷未央楼。", "夜凉河汉截天流。", "宫阙锁清秋。", "瑶阶曙。", "金盘露。", "凤髓香和烟雾。", "三千珠翠拥宸游。", "水殿按《凉州》。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"鹧鸪天","p":"鹧鸪天","d":"宋代","a":"夏竦","c":["镇日无心扫黛眉。", "临行愁见理征衣。", "尊前只恐伤郎意，阁泪汪汪不敢垂。", "停宝马，捧瑶卮。", "相斟相劝忍分离。", "不如饮待奴先醉，图得不知郎去时。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"多丽","p":"多丽","d":"宋代","a":"聂冠卿","c":["想人生，美景良辰堪惜。", "问其间、赏心乐事，就中难是并得。", "况东城、凤台沙苑，泛晴波、浅照金碧。", "露洗华桐，烟霏丝柳，绿阴摇曳，荡春一色。", "画堂迥、玉簪琼佩，高会尽词客。", "清欢久、重然绛蜡，别就瑶席。", "有翩若轻鸿体态，暮为行雨标格。", "逞朱唇、缓歌妖丽，似听流莺乱花隔。", "慢舞萦回，娇鬟低亸，腰肢纤细困无力。", "忍分散、彩云归后，何处更寻觅。", "休辞醉，明月好花，莫谩轻掷。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"望汉月・忆汉月","p":"望汉月・忆汉月","d":"宋代","a":"李遵","c":["黄菊一丛临砌。", "颗颗露珠装缀。", "独教冷落向秋天，恨东君不曾留意。", "雕阑新雨霁。", "绿藓上，乱铺金蕊。", "此花开后更无花，愿爱惜、莫同桃李。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"滴滴金","p":"滴滴金","d":"宋代","a":"李遵","c":["帝城五夜宴游歇。", "残灯外、看残月。", "都人犹在醉乡中，听更漏初彻。", "行乐已成闲话说。", "如春梦、觉时节。", "大家同约探春行，问甚花先发。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"苏幕遮","p":"苏幕遮","d":"宋代","a":"范仲淹","c":["碧云天，黄叶地。", "秋色连波，波上寒烟翠。", "山映斜阳天接水。", "芳草无情，更在斜阳外。", "黯乡魂，追旅思。", "夜夜除非，好梦留人睡。", "明月楼高休独倚。", "酒入愁肠，化作相思泪。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"渔家傲","p":"渔家傲","d":"宋代","a":"范仲淹","c":["塞下秋来风景异。", "衡阳雁去无留意。", "四面边声连角起。", "千嶂里。", "长烟落日孤城闭。", "浊酒一杯家万里。", "燕然未勒归无计。", "羌管悠悠霜满地。", "人不寐。", "将军白发征夫泪。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"御街行","p":"御街行","d":"宋代","a":"范仲淹","c":["纷纷堕叶飘香砌。", "夜寂静、寒声碎。", "真珠帘卷玉楼空，天淡银河垂地。", "年年今夜，月华如练，长是人千里。", "愁肠已断无由醉。", "酒未到、先成泪。", "残灯明灭枕头欹。", "谙尽孤眠滋味。", "都来此事，眉间心上，无计相回避。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"剔银灯","p":"剔银灯","d":"宋代","a":"范仲淹","c":["昨夜因看蜀志。", "笑曹操、孙权、刘备。", "用尽机关，徒劳心力，只得三分天地。", "屈指细寻思，争如共、刘伶一醉。", "人世都无百岁。", "少痴呆、老成尩悴。", "只有中间，些子少年，忍把浮名牵系。", "一品与千金，问白发、如何回避。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"定风波","p":"定风波","d":"宋代","a":"范仲淹","c":["罗绮满城春欲暮。", "百花洲上寻芳去。", "浦映□花花映浦。", "无尽处。", "恍然身入桃源路。", "莫怪山翁聊逸豫。", "功名得丧归时数。", "莺解新声蝶解舞。", "天赋与。", "争教我辈无欢绪。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"剔银灯","p":"剔银灯","d":"宋代","a":"沈邈","c":["一夜隋河风劲。", "霜湿水天如镜。", "古柳堤长，寒烟不起，波上月无流影。", "那堪频听。", "疏星外、离鸿相应。", "须信道、情多是病。", "酒未到、愁肠还醒。", "数叠兰衾，馀香未减，甚时枕鸳重并。", "教伊须更。", "将盟誓、后约言定。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"剔银灯","p":"剔银灯","d":"宋代","a":"沈邈","c":["江上秋高霜早。", "云静月华如扫。", "候雁初飞，啼螀正苦，又是黄花衰草。", "等闲临照。", "潘郎鬓、星星易老。", "那堪更、酒醒孤棹。", "望千里、长安西笑。", "臂上妆痕，胸前泪粉，暗惹离愁多少。", "此情谁表。", "除非是、重相见了。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"长相思","p":"长相思","d":"宋代","a":"杨适1","c":["南山明。", "北山明。", "中有长亭号丈亭。", "沙边供送迎。", "东江清。", "西江清。", "海上潮来两岸平。", "行人分棹行。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"黄莺儿","p":"黄莺儿","d":"宋代","a":"柳永","c":["园林晴昼春谁主。", "暖律潜催，幽谷暄和，黄鹂翩翩，乍迁芳树。", "观露湿缕金衣，叶映如簧语。", "晓来枝上绵蛮，似把芳心、深意低诉。", "无据。", "乍出暖烟来，又趁游蜂去。", "恣狂踪迹，两两相呼，终朝雾吟风舞。", "当上苑柳秾时，别馆花深处。", "此际海燕偏饶，都把韶光与。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"玉女摇仙佩","p":"玉女摇仙佩","d":"宋代","a":"柳永","c":["飞琼伴侣，偶别珠宫，未返神仙行缀。", "取次梳妆，寻常言语，有得几多姝丽。", "拟把名花比。", "恐旁人笑我，谈何容易。", "细思算、奇葩艳卉，惟是深红浅白而已。", "争如这多情，占得人间，千娇百媚。", "须信画堂绣阁，皓月清风，忍把光阴轻弃。", "自古及今、佳人才子，少得当年双美。", "且恁相偎依。", "未消得、怜我多才多艺。", "愿妳妳、兰心蕙性，枕前言下，表余深意。", "为盟誓。", "今生断不孤鸳被。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"雪梅香","p":"雪梅香","d":"宋代","a":"柳永","c":["景萧索，危楼独立面晴空。", "动悲秋情绪，当时宋玉应同。", "渔市孤烟袅寒碧，水村残叶舞愁红。", "楚天阔，浪浸斜阳，千里溶溶。", "临风。", "想佳丽，别后愁颜，镇敛眉峰。", "可惜当年，顿乖雨迹云踪。", "雅态妍姿正欢洽，落花流水忽西东。", "无憀恨、相思意，尽分付征鸿。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"尾犯","p":"尾犯","d":"宋代","a":"柳永","c":["夜雨滴空阶，孤馆梦回，情绪萧索。", "一片闲愁，想丹青难貌。", "秋渐老、蛩声正苦，夜将阑、灯花旋落。", "最无端处，总把良宵，祗恁孤眠却。", "佳人应怪我，别后寡信轻诺。", "记得当初，翦香云为约。", "甚时向、幽闺深处，按新词、流霞共酌。", "再同欢笑，肯把金玉珠珍博。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"早梅芳・喜迁莺","p":"早梅芳・喜迁莺","d":"宋代","a":"柳永","c":["海霞红，山烟翠。", "故都风景繁华地。", "谯门画戟，下临万井，金碧楼台相倚。", "芰荷浦溆，杨柳汀洲，映虹桥倒影，兰舟飞棹，游人聚散，一片湖光里。", "汉元侯，自从破虏征蛮，峻陟枢庭贵。", "筹帷厌久，盛年昼锦，归来吾乡我里。", "铃斋少讼，宴馆多欢，未周星，便恐皇家，图任勋贤，又作登庸计。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"斗百花","p":"斗百花","d":"宋代","a":"柳永","c":["飒飒霜飘鸳瓦，翠幕轻寒微透，长门深锁悄悄，满庭秋色将晚。", "眼看菊蕊，重阳泪落如珠，长是淹残粉面。", "鸾辂音尘远。", "无险幽恨，寄情空殢纨扇。", "应是帝王，当初怪妾辞辇。", "陡顿今来，宫中第一妖娆，却道昭阳飞燕。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"斗百花","p":"斗百花","d":"宋代","a":"柳永","c":["煦色韶光明媚。", "轻霭低笼芳树。", "池塘浅蘸烟芜，帘幕闲垂风絮。", "春困厌厌，抛掷斗草工夫，冷落踏青心绪。", "终日卮朱户。", "远恨绵绵，淑景迟迟难度。", "年少傅粉，依前醉眠何处。", "深院无人，黄昏乍拆秋千，空锁满庭花雨。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"斗百花","p":"斗百花","d":"宋代","a":"柳永","c":["满搦宫腰纤细。", "年纪方当笄岁。", "刚被风流沾惹，与合垂杨双髻。", "初学严妆，如描似削身材，怯雨羞云情意。", "举措多娇媚。", "争奈心性，未会先怜佳婿。", "长是夜深，不肯便入鸳被。", "与解罗裳，盈盈背立银釭，却道你但先睡。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"甘草子","p":"甘草子","d":"宋代","a":"柳永","c":["秋暮。", "乱洒衰荷，颗颗真珠雨。", "雨过月华生，冷彻鸳鸯浦。", "池长凭阑愁无侣。", "奈此个、单栖情绪。", "却傍金笼共鹦鹉。", "念粉郎言语。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"甘草子","p":"甘草子","d":"宋代","a":"柳永","c":["秋尽。", "叶翦红绡，砌菊遗金粉。", "雁字一行来，还有边庭信。", "飘散露华清风紧。", "动翠幕、晓寒犹嫩。", "中酒残妆慵整顿。", "聚两眉离恨。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"送征衣","p":"送征衣","d":"宋代","a":"柳永","c":["过韶阳。", "璇枢电绕，华渚虹流，运应千载会昌。", "罄寰宇、荐殊祥。", "吾皇。", "诞弥月，瑶图缵庆，玉叶腾芳。", "并景贶、三灵眷祐，挺英哲、掩前王。", "迂年年、嘉节清和，颁率土称觞。", "无间要荒华夏，尽万里、走梯航。", "彤庭舜张大乐，禹会群方。", "鹓行。", "望上国，山呼鳌抃，遥爇炉香。", "竟就日、瞻云献寿，指南山、等无疆。", "愿巍巍、宝历鸿基，齐天地遥长。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"昼夜乐","p":"昼夜乐","d":"宋代","a":"柳永","c":["洞房记得初相遇。", "便只合、长相聚。", "何期小会幽欢，变作离情别绪。", "况值阑珊春色暮。", "对满目、乱花狂絮。", "直恐好风光，尽随伊归去。", "一场寂寞凭谁诉。", "算前言、总轻负。", "早知恁地难拼，悔不当时留住。", "其奈风流端正外，更别有、系人心处。", "一日不思量，也攒眉千度。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"昼夜乐","p":"昼夜乐","d":"宋代","a":"柳永","c":["秀香家住桃花径。", "算神仙、才堪并。", "层波细翦明眸，腻玉圆搓素颈。", "爱把歌喉当筵逞。", "遏天边，乱云愁凝。", "言语似娇莺，一声声堪听。", "洞房饮散帘帏静。", "拥香衾、欢心称。", "金炉麝袅青烟，凤帐烛摇红影。", "无限狂心乘酒兴。", "这欢娱、渐入嘉景。", "犹自怨邻鸡，道秋宵不永。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"柳腰轻","p":"柳腰轻","d":"宋代","a":"柳永","c":["英英妙舞腰肢软。", "章台柳、昭阳燕。", "锦衣冠盖，绮堂筵会，是处千金争选。", "顾香砌、丝管初调，倚轻风、佩环微颤。", "乍入霓裳促遍。", "逞盈盈、渐催檀板。", "慢垂霞袖，急趋莲步，进退奇容千变。", "算何止、倾国倾城，暂回眸、万人肠断。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"西江月","p":"西江月","d":"宋代","a":"柳永","c":["凤额绣帘高卷，兽环朱户频摇。", "两竿红日上花梢。", "春睡厌厌难觉。", "好梦狂随飞絮，闲愁浓胜香醪。", "不成雨暮与云朝。", "又是韶光过了。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"倾杯乐","p":"倾杯乐","d":"宋代","a":"柳永","c":["禁漏花深，绣工日永，蕙风布暖。", "变韶景、都门十二，元宵三五，银蟾光满。", "连云复道凌飞观。", "耸皇居丽，嘉气瑞烟葱蒨。", "翠华宵幸，是处层城阆苑。", "龙凤烛、交光星汉。", "对咫尺鳌山开羽扇。", "会乐府两籍神仙，梨园四部弦管。", "向晓色、都人未散。", "盈万井、山呼鳌抃。", "愿岁岁，天仗里、长瞻凤辇。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"笛家弄・笛家","p":"笛家弄・笛家","d":"宋代","a":"柳永","c":["花发西园，草薰南陌，韶光明媚，乍晴轻暖清明后。", "水嬉舟动，禊饮筵开，银塘似染，金堤如绣。", "是处王孙，几多游妓，往往携纤手。", "遣离人、对嘉景，触目伤怀，尽成感旧。", "别久。", "帝城当日，兰堂夜烛，百万呼卢，画阁春风，十千沽酒。", "未省、宴处能忘管弦，醉里不寻花柳。", "岂知秦楼，玉箫声断，前事难重偶。", "空遗恨，望仙乡，一饷消凝，泪沾襟袖。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"},
  {"t":"倾杯乐","p":"倾杯乐","d":"宋代","a":"柳永","c":["皓月初圆，暮云飘散，分明夜色如晴昼。", "渐消尽、醺醺残酒。", "危阁迥、凉生襟袖。", "追旧事、一饷凭阑久。", "如何媚容艳态，抵死孤欢偶。", "朝思暮想，自家空恁添清瘦。", "算到头、谁与伸剖。", "向道我别来，为伊牵系，度岁经年，偷眼觑、也不忍觑花柳。", "可惜恁、好景良宵，未曾略展双眉暂开口。", "问甚时与你，深怜痛惜还依旧。"],"tags":["全宋词"],"z":"","y":"","s":"","k":"词"}
];